/**
 * Convert VodContent to VodSlideData for use in VodHeroSliderV2
 * Used for WIDEO and START sections that have local VOD content
 */
fun VodContent.toVodSlideData(): VodSlideData = VodSlideData(
    title = title,
    genre = category,
    duration = "90 min", // Default duration
    year = "2024 r.",
    country = "Polska",
    ageRating = "12 lat",
    description = description,
    price = price ?: "Bezpłatne",
    // Prefer backdrop for MovieDetail's full-bleed background (matches Kino Play tab path
    // which builds VodSlideData with backdropUrl explicitly). Fall back to poster only
    // when no backdrop is available — better than always showing the small portrait poster.
    backgroundUrl = backdropUrl ?: imageUrl,
    posterUrl = imageUrl,
    youtubeUrl = youtubeUrl,
    cast = cast,
    isKinoPlay = true,
    channelLogoUrl = channelLogoUrl
)

