@Composable
private fun TvAppIconCard(
    channel: TvChannel,
    isFocused: Boolean,
    focusRequester: FocusRequester,
    onFocusChange: () -> Unit,
    sx: (Int) -> androidx.compose.ui.unit.Dp,
    sy: (Int) -> androidx.compose.ui.unit.Dp
) {
    Column(
        modifier = Modifier
            .width(sx(320))
            .height(sy(220))
            .focusRequester(focusRequester)
            .onFocusChanged { focusState ->
                if (focusState.isFocused) onFocusChange()
            }
            .focusable(),
        horizontalAlignment = Alignment.CenterHorizontally,
        verticalArrangement = Arrangement.spacedBy(sy(8))
    ) {
        Box(
            modifier = Modifier
                .size(sx(300), sy(170))
                .clip(RoundedCornerShape(sx(12)))
                .border(
                    width = if (isFocused) (6 * sx(1).value / 1.dp.value).dp else 0.dp,
                    color = if (isFocused) Color(0xFF5AECD3) else Color.Transparent,
                    shape = RoundedCornerShape(sx(12))
                )
        ) {
            AsyncImage(
                model = channel.logo,
                contentDescription = channel.name,
                modifier = Modifier.fillMaxSize(),
                contentScale = ContentScale.Fit
            )
        }
        if (isFocused) {
            Text(
                text = if (channel.channelNumber != null) {
                    "${channel.channelNumber}. ${channel.name}"  // Display: "600. Ginx eSports TV", "700. Polsat Sport 1"
                } else {
                    channel.name
                },
                color = Color(0xFFEEEEEE),
                fontSize = (20 * (sy(1).value / 1.dp.value)).sp,
                fontWeight = FontWeight.W700,
                textAlign = TextAlign.Center
            )
        }
    }
}

// MARK: - Channel List Card (Figma design: 208x208 with channel number)
/**
 * ChannelListCard - Converted from Figma (node-id=6102:17460)
 *
 * Specs:
 * - Card: 208x208px (square)
 * - Background: rgba(0,0,0,0.6) default, rgba(0,0,0,0.8) focused
 * - Logo: 148x148px (centered)
 * - Channel number label: 40px height, padding 8/12, border 2px, radius 4px
 * - Font: Manrope Medium 24px
 */
@OptIn(ExperimentalComposeUiApi::class)
@Composable
private fun ChannelListCard(
    channel: TvChannel,
    isFocused: Boolean,
    focusRequester: FocusRequester,
    onFocusChange: () -> Unit,
    onClick: () -> Unit = {},
    sx: (Int) -> androidx.compose.ui.unit.Dp,
    sy: (Int) -> androidx.compose.ui.unit.Dp,
    displayNumber: Int? = null,  // Custom number to display (null = use channel.channelNumber)
    useZeroPadding: Boolean = true  // true = "01", false = "1"
) {
    Column(
        modifier = Modifier
            .size(sx(TELEWIZJA_CHANNEL_LIST_CARD_WIDTH), sy(TELEWIZJA_CHANNEL_LIST_CARD_HEIGHT))  // Figma: 208x208
            .clip(RoundedCornerShape(sx(12)))
            .background(Color(0xFF000000).copy(alpha = if (isFocused) 0.3f else 0.1f))  // Black with 0.1/0.3 opacity (like WIDEO)
            .border(
                width = if (isFocused) sx(4) else 0.dp,  // Standard focused border
                color = if (isFocused) Color(0xFF5AECD3) else Color.Transparent,
                shape = RoundedCornerShape(sx(12))
            )
            .focusRequester(focusRequester)
            .onFocusChanged { focusState ->
                if (focusState.isFocused) onFocusChange()
            }
            .onPreviewKeyEvent { event ->
                if (event.type == KeyEventType.KeyDown &&
                    (event.key == Key.Enter || event.key == Key.DirectionCenter)) {
                    android.util.Log.d("CHANNEL_LIST_CLICK", "OK pressed on channel: ${channel.name}")
                    onClick()
                    true
                } else {
                    false
                }
            }
            .focusable()
            .padding(bottom = sy(20)),  // Figma: padding-bottom 20px
        horizontalAlignment = Alignment.CenterHorizontally,
        verticalArrangement = Arrangement.spacedBy(sy(8))
    ) {
        // Logo (148x148)
        Box(
            modifier = Modifier.size(sx(TELEWIZJA_CHANNEL_LIST_CARD_LOGO_SIZE), sy(TELEWIZJA_CHANNEL_LIST_CARD_LOGO_SIZE)),  // Figma: 148x148
            contentAlignment = Alignment.Center
        ) {
            AsyncImage(
                model = channel.logo,
                contentDescription = channel.name,
                modifier = Modifier.fillMaxSize(),
                contentScale = ContentScale.Fit
            )
        }

        // Channel number label
        Box(
            modifier = Modifier
                .height(sy(54))  // 54px height fits 28sp lineHeight perfectly without cutoff
                .widthIn(min = sx(52))  // Minimum width to fit 2-digit number (01, 02, etc.)
                .clip(RoundedCornerShape(sx(4)))  // Figma: radius 4px
                .border(
                    width = sx(2),  // Figma: 2px border
                    color = Color(0xFFEEEEEE).copy(alpha = 0.4f),  // Figma: rgba(238,238,238,0.4)
                    shape = RoundedCornerShape(sx(4))
                )
                .padding(horizontal = sx(12)),  // Only horizontal padding - vertical removed to prevent cutoff
            contentAlignment = Alignment.Center
        ) {
            Text(
                text = run {
                    val number = displayNumber ?: channel.channelNumber ?: 0
                    if (useZeroPadding) number.toString().padStart(2, '0') else number.toString()
                },
                fontSize = (24 * sy(1).value / 1).sp,  // Figma: 24px
                fontWeight = FontWeight.Medium,  // Figma: Medium (500)
                lineHeight = (28 * sy(1).value / 1).sp,  // Reduced from 32px to 28px - fits in 54px box without cutoff
                letterSpacing = 0.48.sp,  // Figma: 2% of 24px = 0.48sp
                color = Color(0xFFEEEEEE)  // Figma: #EEEEEE
            )
        }
    }
}

// MARK: - Channel Logos Grid (Row 2: Kanały TV - 2x7 grid)
@Composable
private fun ChannelLogosGrid(
    channels: List<TvChannel>,
    focusedRowIndex: Int,
    focusedColIndex: Int,
    onFocusChange: (rowOffset: Int, colOffset: Int) -> Unit,
    channelFocusRequesters: Map<Pair<Int, Int>, FocusRequester>,
    sx: (Int) -> androidx.compose.ui.unit.Dp,
    sy: (Int) -> androidx.compose.ui.unit.Dp
) {
    val rowIndex = 2 // Grid is in Row 2
    val rows = channels.chunked(7) // 2 rows of 7 channels each

    Column(
        modifier = Modifier.padding(start = sx(80)),
        verticalArrangement = Arrangement.spacedBy(sy(20))
    ) {
        rows.forEachIndexed { gridRowIndex, rowChannels ->
            Row(
                horizontalArrangement = Arrangement.spacedBy(sx(20))
            ) {
                rowChannels.forEachIndexed { colIndex, channel ->
                    val globalColIndex = gridRowIndex * 7 + colIndex
                    val isFocused = focusedRowIndex == rowIndex && focusedColIndex == globalColIndex
                    val focusRequester = channelFocusRequesters[Pair(rowIndex, globalColIndex)] ?: FocusRequester()

                    ChannelLogoCard(
                        channel = channel,
                        isFocused = isFocused,
                        focusRequester = focusRequester,
                        onFocusChange = { onFocusChange(rowIndex, globalColIndex) },
                        sx = sx,
                        sy = sy
                    )
                }
            }
        }
    }
}

@OptIn(ExperimentalComposeUiApi::class)
@Composable
fun TopMenuScreen2(
    onBackPressed: (isMenuFocused: Boolean) -> Boolean = { false },
    onReturnToEpgDay: () -> Unit = {},  // NEW: Return to EPG Day Test from PIP
    onShowMainMenu: () -> Unit = {},
    onNavigateToLiveScreen: (String) -> Unit = {},
    onNavigateToEpg: () -> Unit = {},
    onNavigateToEpgDay: (channelId: String, itemId: String?, scrollPosition: Int, sectionId: String) -> Unit = { _, _, _, _ -> },
    onNavigateToStartupMode: () -> Unit = {},  // Navigate to startup mode selection
    onFocusRestored: () -> Unit = {},
    restoredTelewizjaFocus: FocusState? = null,
    restoredSection: String? = null,
    pipPlayer: com.google.android.exoplayer2.ExoPlayer? = null,  // PIP player instance
    onClosePip: () -> Unit = {},  // Callback to close PIP
    onNavigateToChannelGrid: (title: String, category: String, filter: ((TvChannel) -> Boolean)?, channelList: List<TvChannel>?) -> Unit = { _, _, _, _ -> },
    onNavigateToVodGrid: (title: String, prefiltered: List<VodContent>?, sourceSection: String) -> Unit = { _, _, _ -> },  // Navigate to VOD grid (Nagrania, Wypożyczone, Do obejrzenia, etc.)
    onNavigateToKinoGrid: (title: String, prefiltered: List<VodContent>?, sourceSection: String) -> Unit = { _, _, _ -> },  // Navigate to KINO grid (Akcja, Horror - vertical posters)
    onNavigateToRecordingsGrid: (title: String, sourceSection: String) -> Unit = { _, _ -> },  // Navigate to Recordings grid (Zarządzaj nagraniami)
    onNavigateToAppsGrid: () -> Unit = {},  // Navigate to grid wszystkich aplikacji (z CategoryIcon "Aplikacje")
    onNavigateToMovieDetail: (VodSlideData) -> Unit = {},  // Navigate to MovieDetailScreen from KINO PLAY slider
    onNavigateToPurchase: (VodSlideData) -> Unit = {},  // Navigate directly to PurchaseScreen (quick mode)
    onNavigateToVodPlayer: (url: String, title: String) -> Unit = { _, _ -> },  // Navigate to VOD player with seeking
    onNavigateToOlympics: (content: List<VodContent>, sourceSection: String) -> Unit = { _, _ -> },  // Navigate to Olympics page
    availableUpdate: com.uxellence.tv.v3.update.AppUpdateInfo? = null,
    updateState: com.uxellence.tv.v3.update.UpdateState = com.uxellence.tv.v3.update.UpdateState.READY,
    onUpdateDownload: (com.uxellence.tv.v3.update.AppUpdateInfo) -> Unit = {},
    onUpdateInstall: () -> Unit = {},
    onDismissUpdateBadge: () -> Unit = {}
) {
    val configuration = LocalConfiguration.current
    val scaleX = configuration.screenWidthDp / 1920f
    val scaleY = configuration.screenHeightDp / 1080f
    fun sx(px: Int) = (px * scaleX).dp
    fun sy(px: Int) = (px * scaleY).dp

    val context = LocalContext.current
    val coroutineScope = rememberCoroutineScope()
    val repository = remember { com.uxellence.tv.v3.repository.EpgRepository.getInstance(context) }

    // Remote config from Supabase (colors, texts, feature flags)
    val appConfig by ConfigManager.configState.collectAsState()

    // Global state for keyboard shortcuts (defined early for use in global handlers)
    var isEpgSectionExpanded by remember { mutableStateOf(com.uxellence.tv.v3.utils.VersionTracker.getEpgSectionExpanded(context)) }
    var showNagraniaV2 by remember { mutableStateOf(com.uxellence.tv.v3.utils.VersionTracker.getNagraniaVersion(context) == "v2") }

    // Global state for slider version:
    // 1 = V1 (original carousel slider)
    // 2 = V2 (bullets + auto-rotation)
    // 3 = V3 (no bullets, no auto-rotation, shuffled order)
    // Cycled with Key.Nine (V1 → V2 → V3 → V1), affects ODKRYWAJ, KINO_PLAY, WIDEO sections
    // Persisted in SharedPreferences
    val sliderPrefs = remember { context.getSharedPreferences("slider_prefs", android.content.Context.MODE_PRIVATE) }
    var sliderVersion by remember { mutableIntStateOf(sliderPrefs.getInt("slider_version", 4)) }  // Default 4: KINO_PLAY=2 buttons, ODKRYWAJ=V2 slider with bullets

    // Quick purchase mode - Key.Six toggles: Slider → MovieDetail → Purchase (default) vs Slider → Purchase (quick)
    var quickPurchaseMode by remember { mutableStateOf(sliderPrefs.getBoolean("quick_purchase_mode", false)) }

    // V3 Slider auto-slide toggle - Key.Eight toggles bullets and auto-rotation for V3 slider in ODKRYWAJ
    // When enabled: bullets appear, progress bar fills, auto-slides to next slide
    // When disabled: no bullets, manual navigation only (default V3 behavior)
    var v3SliderAutoSlideEnabled by remember {
        mutableStateOf(sliderPrefs.getBoolean("v3_auto_slide_enabled", false))
    }

    // Search keyboard mode - Key.Nine cycles: 0=ABC, 1=System fullwidth, 2=System left panel
    val searchPrefs = remember { context.getSharedPreferences("search_prefs", android.content.Context.MODE_PRIVATE) }
    var searchKeyboardMode by remember { mutableIntStateOf(searchPrefs.getInt("search_keyboard_mode", 0)) }

    // APLIKACJE variant - 0=hero slider + channels, 1=channels-only (Aplikacje na top, bez slidera)
    var aplikacjeVariant by remember { mutableIntStateOf(sliderPrefs.getInt("aplikacje_variant", 0)) }

    // KINO_PLAY "Wypożyczone" channel position:
    //   0 = above slider (Aplikacje-style top row) — TODO, currently same as v1
    //   1 = below slider, above "Polecane" (DEFAULT)
    // Empty when no rentals exist; toggles via DevTogglesModal under key "0".
    var vodWypozyczoneVariant by remember { mutableIntStateOf(sliderPrefs.getInt("vod_wypozyczone_variant", 1)) }

    // Dev modal — Key.Zero otwiera ekran przełączników trybów
    var showDevModal by remember { mutableStateOf(false) }

    // Profil variant — 0=tooltip "Profil", 1=tooltip "Wyjdź z profilu"
    var profileVariant by remember { mutableIntStateOf(sliderPrefs.getInt("profile_variant", 0)) }

    // Wybrany profil (id z UserProfile w ProfileScreenContent: "1"=Piotr, "2"=Angelika, "kids"=Dzieci)
    var selectedProfileId by remember { mutableStateOf(sliderPrefs.getString("selected_profile", "1") ?: "1") }

    val menuItems = remember {
        listOf(
            MenuItem2("ODKRYWAJ", "Start"),       // Moved from position 1 to 0
            MenuItem2("MOJE", "Moje"),            // Moved from position 2 to 1
            MenuItem2("TELEWIZJA", "Telewizja"),  // Moved from position 3 to 2
            MenuItem2("KINO_PLAY", "Kino Play"),  // Moved from position 4 to 3
            MenuItem2("WIDEO", "Wideo"),          // Moved from position 5 to 4
            MenuItem2("APLIKACJE", "Aplikacje"),  // Moved from position 6 to 5
            MenuItem2("SEARCH", "Search")         // Moved from position 0 to 6 (Lupa na koniec)
        )
    }

    val globalFocusState = GlobalFocusManager.rememberGlobalFocusState(
        initialRow = if (restoredTelewizjaFocus != null && restoredSection == "TELEWIZJA") {
            1  // Restore to content mode (actual channel/item restoration handled by ID-based logic)
        } else {
            0  // Default to menu
        },
        initialPosition = MenuPositions.getPositionForSection(restoredSection ?: "ODKRYWAJ"),  // Match position to section
        initialSection = restoredSection ?: "ODKRYWAJ"  // Restore saved section or default to ODKRYWAJ
    )

    // Aktualizuj selectedProfileId po opuszczeniu sekcji PROFILE (gdy profil został wybrany)
    LaunchedEffect(globalFocusState.value.sectionId) {
        if (globalFocusState.value.sectionId != "PROFILE") {
            val current = sliderPrefs.getString("selected_profile", "1") ?: "1"
            if (current != selectedProfileId) selectedProfileId = current
        }
    }

    // Track fresh PIP mode (resets automatically when pipPlayer changes)
    var freshPipMode by remember(pipPlayer) {
        mutableStateOf(pipPlayer != null)
    }

    // PIP dialog state - show when PLAY/PAUSE pressed with active PIP
    var showPipDialog by remember { mutableStateOf(false) }

    // Debounce state for PLAY/PAUSE to prevent rapid dialog opens (50ms minimum between opens)
    var lastDialogOpenTime by remember { mutableLongStateOf(0L) }

    // Settings backdrop state - shown when Android settings drawer is open
    var showSettingsBackdrop by remember { mutableStateOf(false) }

    // Detect return from settings → hide backdrop
    val lifecycleOwner = LocalLifecycleOwner.current
    DisposableEffect(lifecycleOwner) {
        val observer = LifecycleEventObserver { _, event ->
            if (event == Lifecycle.Event.ON_RESUME) {
                showSettingsBackdrop = false
            }
        }
        lifecycleOwner.lifecycle.addObserver(observer)
        onDispose { lifecycleOwner.lifecycle.removeObserver(observer) }
    }

    var isContentLoading by remember { mutableStateOf(false) }

    val focusRequesters = remember(menuItems.size) {
        menuItems.associate { it.id to FocusRequester() }
    }

    // Left Profil button state (v4.0.0: Profil is on left side, before Start)
    var isLeftProfilFocused by remember { mutableStateOf(false) }
    val leftProfilFocusRequester = remember { FocusRequester() }

    // Right section state (0=Konto, 1=Ustawienia, -1=none focused)
    // Note: Profil moved to left side in v4.0.0
    var focusedRightButton by remember { mutableStateOf(-1) }
    val rightButtonFocusRequesters = remember {
        mapOf(
            0 to FocusRequester(), // Konto (account icon)
            1 to FocusRequester()  // Ustawienia (settings gear)
            // Profile usunięty z prawej strony - teraz jest tylko na LEWEJ stronie przed Start
        )
    }

    // Pakiety button state (between menu and right section)
    var isPakietyFocused by remember { mutableStateOf(false) }
    val pakietyFocusRequester = remember { FocusRequester() }

    // State for keyboard shortcuts (loaded from SharedPreferences)
    var isCandyBarVisible by remember { mutableStateOf(com.uxellence.tv.v3.utils.VersionTracker.getCandyBarVisibility(context)) }
    var showProfileNotificationBadge by remember { mutableStateOf(com.uxellence.tv.v3.utils.VersionTracker.getNotificationBadge(context)) }
    var showKontoUpdateBadge by remember {
        mutableStateOf(com.uxellence.tv.v3.utils.VersionTracker.getKontoUpdateBadge(context))
    }

    // TopMenu design variant (1-4, cycled with key "4")
    val menuPrefs = remember { context.getSharedPreferences("top_menu_prefs", android.content.Context.MODE_PRIVATE) }
    var currentMenuVariant by remember { mutableIntStateOf(menuPrefs.getInt("menu_variant", 1)) }
    val currentVariantConfig = remember(currentMenuVariant) { MENU_VARIANTS.getOrNull(currentMenuVariant - 1) ?: MENU_VARIANTS[0] }

    // Manage focus for right section buttons
    LaunchedEffect(focusedRightButton) {
        if (focusedRightButton >= 0 && globalFocusState.value.currentRow == 0) {
            // Focus on right section button
            delay(50)
            rightButtonFocusRequesters[focusedRightButton]?.requestFocus()
        }
    }

    // Manage focus for Pakiety button
    LaunchedEffect(isPakietyFocused) {
        if (isPakietyFocused && globalFocusState.value.currentRow == 0) {
            delay(50)
            pakietyFocusRequester.requestFocus()
        }
    }

    // Manage focus for left Profil button (v4.0.0: Profil moved to left side)
    LaunchedEffect(isLeftProfilFocused) {
        if (isLeftProfilFocused && globalFocusState.value.currentRow == 0) {
            delay(50)
            leftProfilFocusRequester.requestFocus()
        }
    }

    // Auto-focus buttons when returning from their content to menu
    // ACCOUNT → Konto button (right section, index 0)
    // PROFILE → Profil button (LEFT side in v4.0.0)
    // POINTS_HISTORY → CandyBar/Pakiety button (when CandyBar visible)
    // PAKIETY → Pakiety button (when CandyBar not visible)
    // NOTE: No delay! Immediate focus prevents "through Start" flash when returning from content
    LaunchedEffect(globalFocusState.value.sectionId, globalFocusState.value.currentRow) {
        if (globalFocusState.value.currentRow == 0) {
            when (globalFocusState.value.sectionId) {
                "ACCOUNT" -> {
                    focusedRightButton = 0  // Focus Konto button (index 0)
                    isPakietyFocused = false
                    isLeftProfilFocused = false
                }
                "PROFILE" -> {
                    // v4.0.0: Profil is now on the LEFT side
                    isLeftProfilFocused = true
                    focusedRightButton = -1
                    isPakietyFocused = false
                }
                "POINTS_HISTORY", "PAKIETY" -> {
                    // Both use the same Pakiety button (different sectionId based on CandyBar visibility)
                    focusedRightButton = -1
                    isPakietyFocused = true  // Focus CandyBar/Pakiety button
                    isLeftProfilFocused = false
                }
            }
        }
    }

    // Special sections that have their own buttons (not main menu tabs)
    // These should NOT be overwritten by position-based section detection
    val specialSections = listOf("PROFILE", "ACCOUNT", "POINTS_HISTORY", "PAKIETY")

    LaunchedEffect(globalFocusState.value.currentPosition, globalFocusState.value.currentRow) {
        if (globalFocusState.value.currentRow == 0) {
            val currentSection = MenuPositions.getSectionForPosition(globalFocusState.value.currentPosition)
            // Don't overwrite special sections - they are managed by their dedicated buttons
            // (Profil on left, CandyBar/Konto on right, Pakiety button)
            if (globalFocusState.value.sectionId != currentSection &&
                globalFocusState.value.sectionId !in specialSections) {
                // DEBOUNCE: Wait 350ms before loading content
                // If user moves LEFT/RIGHT quickly, LaunchedEffect cancels and content never loads
                // This allows free navigation without blocking - content loads only when user stops
                delay(350)

                // Show loader (smooth fade in)
                isContentLoading = true

                // Change section
                globalFocusState.value = globalFocusState.value.copy(sectionId = currentSection)

                // Short delay for content initialization (50ms - optimized from original 100ms)
                delay(50)

                // Hide loader (smooth fade out)
                isContentLoading = false
            }
        }
    }

    // Load content when special buttons are focused (like main tabs)
    // v4.0.0: Profil is on LEFT side, CandyBar/Konto/Ustawienia on RIGHT side
    // Same 350ms debounce pattern for consistent behavior
    // Also handles returning to main tabs - updates sectionId when focus leaves special buttons
    LaunchedEffect(focusedRightButton, isPakietyFocused, isLeftProfilFocused, profileVariant) {
        if (globalFocusState.value.currentRow == 0) {
            val targetSection = when {
                isLeftProfilFocused && profileVariant == 0 -> "PROFILE"  // v1 only: auto-preview na fokus. v2: dopiero po ENTER.
                isPakietyFocused && isCandyBarVisible -> "POINTS_HISTORY"
                isPakietyFocused && !isCandyBarVisible -> "PAKIETY"
                focusedRightButton == 0 -> "ACCOUNT"
                // focusedRightButton == 1 is Settings (external app, no section)
                else -> null  // Focus is on main tabs
            }

            if (targetSection != null && globalFocusState.value.sectionId != targetSection) {
                // DEBOUNCE: Same 350ms as main tabs
                delay(350)

                // Show loader
                isContentLoading = true

                // Change section
                globalFocusState.value = globalFocusState.value.copy(sectionId = targetSection)

                // Short delay for content initialization
                delay(50)

                // Hide loader
                isContentLoading = false
            } else if (targetSection == null && !isPakietyFocused && !isLeftProfilFocused && focusedRightButton == -1) {
                // Focus returned to main tabs - update sectionId based on currentPosition
                val currentSection = MenuPositions.getSectionForPosition(globalFocusState.value.currentPosition)
                if (globalFocusState.value.sectionId != currentSection) {
                    // DEBOUNCE: Same 350ms as main tabs
                    delay(350)

                    // Show loader
                    isContentLoading = true

                    // Change section
                    globalFocusState.value = globalFocusState.value.copy(sectionId = currentSection)

                    // Short delay for content initialization
                    delay(50)

                    // Hide loader
                    isContentLoading = false
                }
            }
        }
    }

    LaunchedEffect(globalFocusState.value.currentRow, globalFocusState.value.currentPosition) {
        if (globalFocusState.value.currentRow == 0) {
            val currentSection = MenuPositions.getSectionForPosition(globalFocusState.value.currentPosition)
            focusRequesters[currentSection]?.requestFocus()
        }
    }

    // Haze state for blur effect under menu
    val hazeState = remember { HazeState() }

    // Track if TELEWIZJA "Skróty v2" channel is focused (for top gradient visibility)
    var isTelewizjaSkrotyFocused by remember { mutableStateOf(false) }

    Box(
        modifier = Modifier
            .fillMaxSize()
            .background(appConfig.backgroundColor)  // Dynamic from remote config
            .onPreviewKeyEvent { event ->
                if (event.type != KeyEventType.KeyDown) {
                    return@onPreviewKeyEvent false
                }

                // PIP Dialog Guard: CRITICAL - Must be FIRST before any key handling!
                // When dialog is open, only allow specific keys through (whitelist pattern)
                // Strengthened input gate prevents unexpected keys from reaching background navigation
                if (showPipDialog) {
                    if (event.key in DIALOG_ALLOWED_KEYS) {
                        android.util.Log.d("TopMenuScreen2", "PIP dialog open - allowing key to dialog: ${event.key}")
                        return@onPreviewKeyEvent false  // Let dialog handle allowed keys
                    } else {
                        android.util.Log.d("TopMenuScreen2", "PIP dialog open - blocking unexpected key: ${event.key}")
                        return@onPreviewKeyEvent true  // Consume and block all other keys
                    }
                }

                if (event.key == Key.Back) {
                    // PIP mode: BACK from menu on ANY tab - always return to EPG
                    if (pipPlayer != null && globalFocusState.value.currentRow == 0) {
                        android.util.Log.d("PIP_NAVIGATION", "BACK from menu with PIP (tab: ${globalFocusState.value.sectionId}) - returning to EPG Day Test")
                        onReturnToEpgDay()
                        onClosePip()
                        return@onPreviewKeyEvent true
                    }

                    // SEARCH handles its own BACK (channels→keyboard→menu)
                    if (globalFocusState.value.sectionId == "SEARCH" && globalFocusState.value.currentRow != 0) {
                        return@onPreviewKeyEvent false // Let SearchScreen handle BACK
                    }

                    // Normal BACK - from content to menu
                    if (globalFocusState.value.currentRow != 0) {
                        // Set button focus states FIRST to prevent "through Start" flash
                        when (globalFocusState.value.sectionId) {
                            "ACCOUNT" -> {
                                focusedRightButton = 0  // Konto button
                                isPakietyFocused = false
                                isLeftProfilFocused = false
                            }
                            "PROFILE" -> {
                                isLeftProfilFocused = true  // Left Profil button
                                focusedRightButton = -1
                                isPakietyFocused = false
                            }
                            "POINTS_HISTORY", "PAKIETY" -> {
                                isPakietyFocused = true  // CandyBar/Pakiety button
                                focusedRightButton = -1
                                isLeftProfilFocused = false
                            }
                        }
                        globalFocusState.value = GlobalFocusManager.returnToMenu(globalFocusState.value)
                        return@onPreviewKeyEvent true
                    }

                    // BACK from menu without PIP - consume event (stay in app, don't exit)
                    return@onPreviewKeyEvent true
                }

                // PIP: Handle "0" key to close PIP
                if (event.key == Key.Zero && pipPlayer != null) {
                    android.util.Log.d("TopMenuScreen2", "Key 0: Closing PIP")
                    onClosePip()
                    return@onPreviewKeyEvent true
                }

                // PIP: Handle PLAY/PAUSE key - show dialog when PIP is active
                // Debounce: Minimum 50ms between dialog opens to prevent rapid key press issues
                val keyCode = event.nativeKeyEvent.keyCode
                if ((keyCode == android.view.KeyEvent.KEYCODE_MEDIA_PLAY_PAUSE ||
                     keyCode == android.view.KeyEvent.KEYCODE_MEDIA_PLAY ||
                     keyCode == android.view.KeyEvent.KEYCODE_MEDIA_PAUSE) && pipPlayer != null) {
                    val currentTime = System.currentTimeMillis()
                    if (currentTime - lastDialogOpenTime >= 50) {
                        android.util.Log.d("TopMenuScreen2", "PLAY/PAUSE pressed with active PIP - showing dialog")
                        showPipDialog = true
                        lastDialogOpenTime = currentTime
                    } else {
                        android.util.Log.d("TopMenuScreen2", "PLAY/PAUSE debounced - ignoring rapid key press")
                    }
                    return@onPreviewKeyEvent true
                }

                // ===== GLOBAL KEYBOARD SHORTCUTS (work everywhere) =====

                // Global: Key "1" - Return to main menu (works from any tab)
                if (event.key == Key.One) {
                    android.util.Log.d("TopMenuScreen2", "Key '1' pressed - Returning to main menu")
                    onShowMainMenu()
                    return@onPreviewKeyEvent true
                }

                // Global: Key "3" - Toggle EPG "Było w TV" section (changed from Key.One)
                if (event.key == Key.Three) {
                    isEpgSectionExpanded = !isEpgSectionExpanded
                    com.uxellence.tv.v3.utils.VersionTracker.setEpgSectionExpanded(context, isEpgSectionExpanded)
                    android.util.Log.d("TopMenuScreen2", "Key '3' pressed - EPG section toggled: $isEpgSectionExpanded (saved to prefs)")
                    return@onPreviewKeyEvent true
                }

                // Global: Key "4" - Cycle TopMenu design variant (1→2→3→4→1)
                if (event.key == Key.Four) {
                    currentMenuVariant = (currentMenuVariant % 4) + 1
                    menuPrefs.edit().putInt("menu_variant", currentMenuVariant).apply()
                    android.util.Log.d("TopMenuScreen2", "Key '4' pressed - Menu variant changed to: $currentMenuVariant/4 (${currentVariantConfig.name})")
                    android.widget.Toast.makeText(context, "Menu: Wersja ${currentMenuVariant}/4", android.widget.Toast.LENGTH_SHORT).show()
                    return@onPreviewKeyEvent true
                }

                // Global: Key "5" - Toggle CandyBar visibility
                if (event.key == Key.Five) {
                    isCandyBarVisible = !isCandyBarVisible
                    com.uxellence.tv.v3.utils.VersionTracker.setCandyBarVisibility(context, isCandyBarVisible)
                    android.util.Log.d("TopMenuScreen2", "Key '5' pressed - CandyBar visibility toggled: $isCandyBarVisible (saved to prefs)")
                    return@onPreviewKeyEvent true
                }

                // Global: Key "6" - Toggle quick purchase mode (Slider → Purchase directly, skipping MovieDetail)
                if (event.key == Key.Six) {
                    quickPurchaseMode = !quickPurchaseMode
                    sliderPrefs.edit().putBoolean("quick_purchase_mode", quickPurchaseMode).apply()
                    android.util.Log.d("TopMenuScreen2", "Key '6' pressed - Quick purchase mode: $quickPurchaseMode (saved to prefs)")
                    return@onPreviewKeyEvent true
                }

                // Global: Key "7" - Open startup mode selection
                if (event.key == Key.Seven) {
                    android.util.Log.d("TopMenuScreen2", "Key '7' pressed - Opening startup mode selection")
                    onNavigateToStartupMode()
                    return@onPreviewKeyEvent true
                }

                // Global: Key "8" - Toggle V3 slider auto-slide and bullets (for ODKRYWAJ)
                // When enabled: bullets appear with progress bar, auto-slides every 8 seconds
                // When disabled: no bullets, manual navigation only (default V3 behavior)
                if (event.key == Key.Eight) {
                    v3SliderAutoSlideEnabled = !v3SliderAutoSlideEnabled
                    sliderPrefs.edit().putBoolean("v3_auto_slide_enabled", v3SliderAutoSlideEnabled).apply()
                    android.util.Log.d("TopMenuScreen2", "Key '8' pressed - V3 slider auto-slide: ${if (v3SliderAutoSlideEnabled) "ENABLED" else "DISABLED"} (saved)")
                    return@onPreviewKeyEvent true
                }

                // Key "9" - Toggle Search keyboard mode (ABC keyboard ↔ System keyboard)
                if (event.key == Key.Nine) {
                    searchKeyboardMode = (searchKeyboardMode + 1) % 3
                    searchPrefs.edit().putInt("search_keyboard_mode", searchKeyboardMode).apply()
                    val modeNames = arrayOf("Klawiatura ABC", "Systemowa klawiatura", "Panel + klawiatura")
                    android.widget.Toast.makeText(context, "Szukaj: ${modeNames[searchKeyboardMode]}", android.widget.Toast.LENGTH_SHORT).show()
                    android.util.Log.d("TopMenuScreen2", "Key '9' pressed - Search mode: $searchKeyboardMode (${modeNames[searchKeyboardMode]})")
                    return@onPreviewKeyEvent true
                }

                // Key "0" - Open dev modal (przełączniki trybów)
                if (event.key == Key.Zero) {
                    showDevModal = true
                    android.util.Log.d("TopMenuScreen2", "Key '0' pressed - opening dev modal")
                    return@onPreviewKeyEvent true
                }

                // ===== END GLOBAL SHORTCUTS =====

                when (globalFocusState.value.currentRow) {
                    0 -> { // Menu navigation
                        when (event.key) {
                            Key.DirectionLeft -> {
                                if (focusedRightButton >= 0) {
                                    // In right section - navigate left: Ustawienia(1) -> Konto(0) -> Pakiety/CandyBar -> menu
                                    // Profile usunięty z prawej - teraz jest na LEWEJ stronie
                                    if (focusedRightButton > 0) {
                                        // Move to previous button (Ustawienia->Konto)
                                        focusedRightButton--
                                    } else {
                                        // From Konto(0) -> Pakiety/CandyBar (center element)
                                        focusedRightButton = -1
                                        isPakietyFocused = true
                                    }
                                } else if (isPakietyFocused) {
                                    // From Pakiety/CandyBar -> last menu item (SEARCH)
                                    // IMPORTANT: Update currentPosition BEFORE isPakietyFocused
                                    // LaunchedEffect uses isPakietyFocused as key, so it runs when isPakietyFocused changes.
                                    // We need currentPosition to be already updated when LaunchedEffect reads it.
                                    val lastMenuPosition = menuItems.size - 1
                                    globalFocusState.value = globalFocusState.value.copy(currentPosition = lastMenuPosition)
                                    isPakietyFocused = false  // This triggers LaunchedEffect with correct currentPosition
                                } else if (isLeftProfilFocused) {
                                    // Already at leftmost element (Profil), stay there
                                    // Do nothing
                                } else if (globalFocusState.value.currentPosition == 0) {
                                    // At Start (first menu item) -> go to Profil on the left
                                    isLeftProfilFocused = true
                                } else {
                                    // Normal menu navigation
                                    globalFocusState.value = GlobalFocusManager.navigateRow(globalFocusState.value, RowDirection.LEFT)
                                }
                                true
                            }
                            /**
                             * RIGHT KEY NAVIGATION (Row 0: Menu)
                             *
                             * Layout: Profil (left) | [Start ... SEARCH] | CandyBar | Konto | Ustawienia | Clock
                             * - Profil → Start (first menu item)
                             * - Last item (SEARCH) → Pakiety/CandyBar
                             * - Pakiety/CandyBar → Konto(0) → Ustawienia(1)
                             * - Other items → Continue normal menu navigation via GlobalFocusManager
                             *
                             * @see GlobalFocusManager.navigateRow for normal menu navigation
                             */
                            Key.DirectionRight -> {
                                if (focusedRightButton >= 0) {
                                    // In right section - navigate right: Konto(0) -> Ustawienia(1)
                                    // Profile usunięty z prawej - max = 1 (Ustawienia)
                                    if (focusedRightButton < 1) {
                                        focusedRightButton++
                                    }
                                    // else: already at Ustawienia(1), stay there
                                } else if (isPakietyFocused) {
                                    // From Pakiety/CandyBar -> first right section button (Konto)
                                    isPakietyFocused = false
                                    focusedRightButton = 0  // Always start with Konto
                                } else if (isLeftProfilFocused) {
                                    // From Profil (left side) -> Start (first menu item)
                                    isLeftProfilFocused = false
                                    globalFocusState.value = globalFocusState.value.copy(currentPosition = 0)
                                } else {
                                    // Check if at last menu item (dynamic based on menuItems.size)
                                    val lastMenuPosition = menuItems.size - 1
                                    if (globalFocusState.value.currentPosition == lastMenuPosition) {
                                        // Move to Pakiety/CandyBar (center element)
                                        isPakietyFocused = true
                                    } else {
                                        // Normal menu navigation
                                        globalFocusState.value = GlobalFocusManager.navigateRow(globalFocusState.value, RowDirection.RIGHT)
                                    }
                                }
                                true
                            }
                            // Keys 1, 5, 6 removed - now handled globally above
                            Key.DirectionDown, Key.Enter, Key.DirectionCenter -> {
                                if (focusedRightButton >= 0) {
                                    // In right section - let button handle ENTER/DPAD_CENTER via onPreviewKeyEvent
                                    false // Don't consume, delegate to button
                                } else if (isPakietyFocused) {
                                    // Pakiety focused - navigate to PAKIETY section
                                    isPakietyFocused = false
                                    globalFocusState.value = GlobalFocusManager.transitionToContent(
                                        globalFocusState.value,
                                        "PAKIETY"
                                    )
                                    true
                                } else if (isLeftProfilFocused) {
                                    // Left Profil focused - navigate to PROFILE section
                                    isLeftProfilFocused = false
                                    globalFocusState.value = GlobalFocusManager.transitionToContent(
                                        globalFocusState.value,
                                        "PROFILE"
                                    )
                                    true
                                } else {
                                    // In main menu - transition to content
                                    val currentSection = MenuPositions.getSectionForPosition(globalFocusState.value.currentPosition)
                                    // Allow all sections (including ACCOUNT) to transition to content
                                    globalFocusState.value = GlobalFocusManager.transitionToContent(globalFocusState.value, currentSection)
                                    true
                                }
                            }
                            else -> false
                        }
                    }
                    else -> { // Content area navigation
                        val currentSection = globalFocusState.value.sectionId
                        
                        when (currentSection) {
                            "KINO_PLAY" -> {
                                // KINO_PLAY handles its own navigation entirely
                                false // Let VodWithChannels handle all keys
                            }
                            "WIDEO" -> {
                                // WIDEO handles its own navigation entirely
                                false // Let VodWithChannels handle all keys
                            }
                            "TELEWIZJA" -> {
                                // TELEWIZJA handles its own navigation, but intercept key "2" for EPG refresh
                                if (event.key == Key.Two && event.type == KeyEventType.KeyDown) {
                                    // Force EPG refresh
                                    android.util.Log.d("TELEWIZJA_DEBUG", "Key '2' pressed - Force refreshing EPG...")
                                    coroutineScope.launch {
                                        repository.clearCache()
                                        repository.startBackgroundRefresh()
                                        android.util.Log.d("TELEWIZJA_DEBUG", "EPG refresh triggered, wait 30 seconds...")
                                    }
                                    true
                                } else {
                                    false // Let TelewizjaChannelsScreen handle other keys
                                }
                            }
                            "MOJE" -> {
                                // MOJE handles its own navigation entirely
                                false // Let MojeChannelsScreen handle all keys
                            }
                            "APLIKACJE" -> {
                                // APLIKACJE handles its own navigation entirely
                                false // Let AplikacjeChannelsScreen handle all keys
                            }
                            "ODKRYWAJ" -> {
                                // ODKRYWAJ handles its own navigation entirely
                                false // Let OdkrywajChannelsScreen handle all keys
                            }
                            "SEARCH" -> {
                                // SEARCH handles its own navigation entirely
                                false // Let SearchScreenNew handle all keys
                            }
                            "ACCOUNT" -> {
                                // ACCOUNT handles its own navigation entirely
                                false // Let AccountChannelsScreen handle all keys
                            }
                            "PROFILE" -> {
                                // PROFILE handles its own navigation entirely
                                false // Let ProfileScreenContent handle all keys
                            }
                            else -> {
                                // Fallback for sections without own navigation (POINTS_HISTORY, PAKIETY, etc.)
                                when (event.key) {
                                    Key.DirectionUp -> {
                                        // Set button focus states FIRST to prevent "through Start" flash
                                        when (globalFocusState.value.sectionId) {
                                            "ACCOUNT" -> {
                                                focusedRightButton = 0
                                                isPakietyFocused = false
                                                isLeftProfilFocused = false
                                            }
                                            "PROFILE" -> {
                                                isLeftProfilFocused = true
                                                focusedRightButton = -1
                                                isPakietyFocused = false
                                            }
                                            "POINTS_HISTORY", "PAKIETY" -> {
                                                isPakietyFocused = true
                                                focusedRightButton = -1
                                                isLeftProfilFocused = false
                                            }
                                        }
                                        globalFocusState.value = GlobalFocusManager.returnToMenu(globalFocusState.value)
                                        true
                                    }
                                    else -> false
                                }
                            }
                        }
                    }
                }
            }
    ) {
        // Wrap FullPageContent to block focus when dialog is open
        // .haze(hazeState) marks this content as blur source for menu overlay
        Box(
            modifier = Modifier
                .fillMaxSize()
                .haze(hazeState)  // Blur source - content under menu will be blurred
                .then(
                    if (showPipDialog) {
                        // When dialog open, overlay blocks background keys but lets dialog keys through
                        // CRITICAL: NO .focusable() here - overlay must NOT capture focus!
                        Modifier
                            .onPreviewKeyEvent { event ->
                                // Let dialog handle UP/DOWN/ENTER/BACK for its own navigation
                                when (event.key) {
                                    Key.DirectionUp,
                                    Key.DirectionDown,
                                    Key.Enter,
                                    Key.DirectionCenter,
                                    Key.Back -> false  // Pass through to dialog
                                    else -> true  // Block all other keys from background
                                }
                            }
                    } else {
                        Modifier  // Normal state - no blocking
                    }
                )
        ) {
            FullPageContent(
                selectedSection = globalFocusState.value.sectionId,
                onReturnToMenu = { globalFocusState.value = GlobalFocusManager.returnToMenu(globalFocusState.value) },
                onUserNavigated = { freshPipMode = false },  // Clear fresh PIP mode when user navigates
                onPrepareReturnFocus = { sectionId ->
                    // Set button focus states BEFORE returning to menu (prevents "through Start" flash)
                    when (sectionId) {
                        "ACCOUNT" -> {
                            focusedRightButton = 0  // Konto button
                            isPakietyFocused = false
                            isLeftProfilFocused = false
                        }
                        "PROFILE" -> {
                            isLeftProfilFocused = true  // Left Profil button
                            focusedRightButton = -1
                            isPakietyFocused = false
                        }
                        "POINTS_HISTORY", "PAKIETY" -> {
                            isPakietyFocused = true  // CandyBar/Pakiety button
                            focusedRightButton = -1
                            isLeftProfilFocused = false
                        }
                    }
                },
                shouldAutoFocus = globalFocusState.value.currentRow != 0,
                sx = { sx(it) },
                sy = { sy(it) },
                globalFocusState = globalFocusState,
                onNavigateToEpg = onNavigateToEpg,
                onNavigateToEpgDay = onNavigateToEpgDay,
                onNavigateToStartupMode = onNavigateToStartupMode,
                onFocusRestored = onFocusRestored,
                restoredTelewizjaFocus = restoredTelewizjaFocus,
                onNavigateToChannelGrid = onNavigateToChannelGrid,
                onNavigateToVodGrid = onNavigateToVodGrid,
                onNavigateToKinoGrid = onNavigateToKinoGrid,
                onNavigateToMovieDetail = onNavigateToMovieDetail,
                onNavigateToPurchase = onNavigateToPurchase,
                onNavigateToVodPlayer = onNavigateToVodPlayer,
                quickPurchaseMode = quickPurchaseMode,
                onNavigateToRecordingsGrid = onNavigateToRecordingsGrid,
                onNavigateToAppsGrid = onNavigateToAppsGrid,
                aplikacjeVariant = aplikacjeVariant,
                vodWypozyczoneVariant = vodWypozyczoneVariant,
                onProfileSelected = { profile ->
                    // Zapisz wybrany profil i wróć na ekran główny — UI top menu zaktualizuje się przez LaunchedEffect na zmianę sectionId
                    sliderPrefs.edit().putString("selected_profile", profile.id).apply()
                    isLeftProfilFocused = false
                    // Bezpośrednio zmień sectionId na obecną pozycję menu (bypass LaunchedEffect debounce)
                    val targetSection = MenuPositions.getSectionForPosition(globalFocusState.value.currentPosition)
                    globalFocusState.value = GlobalFocusManager.returnToMenu(globalFocusState.value).copy(sectionId = targetSection)
                },
                isEpgSectionExpanded = isEpgSectionExpanded,
                onEpgSectionExpandedChange = { expanded ->
                    isEpgSectionExpanded = expanded
                },
                showNagraniaV2 = showNagraniaV2,
                onShowNagraniaV2Change = { v2 ->
                    showNagraniaV2 = v2
                },
                sliderVersion = sliderVersion,
                v3SliderAutoSlideEnabled = v3SliderAutoSlideEnabled,  // Key.Eight toggle for V3 slider
                onFocusedChannelChange = { signal ->
                    isTelewizjaSkrotyFocused = signal == "SHOW_GRADIENT"
                },
                onNavigateToOlympics = onNavigateToOlympics,
                availableUpdate = availableUpdate,
                updateState = updateState,
                onUpdateDownload = onUpdateDownload,
                onUpdateInstall = onUpdateInstall,
                onDismissUpdateBadge = {
                    onDismissUpdateBadge()
                    showKontoUpdateBadge = false
                },
                searchKeyboardMode = searchKeyboardMode
            )
        }

        // Gradient from top (same as EPG Day TopMenuOverlay)
        // Solid dark purple at top (0-30%), fades to transparent (30-60%)
        // Hidden in KINO_PLAY when on slider or row 1 - shows only from row 2+
        val isKinoPlayOnSlider = globalFocusState.value.sectionId == "KINO_PLAY" &&
                                  globalFocusState.value.currentRow <= 1

        if (!isKinoPlayOnSlider) {
            Box(
                modifier = Modifier
                    .fillMaxWidth()
                    .height(sy(TOP_MENU_GRADIENT_HEIGHT))  // 600px height
                    .align(Alignment.TopCenter)
                    .zIndex(5f)  // Above content (0f), below menu (10f)
                    .background(
                        brush = Brush.verticalGradient(
                            0.0f to Color(0xFF281443),    // 0%: Solid dark purple at top
                            0.3f to Color(0xFF281443),    // 30%: Still solid dark purple
                            0.6f to Color(0x00281443),    // 60%: Transparent
                            startY = 0f,
                            endY = sy(TOP_MENU_GRADIENT_HEIGHT).value
                        )
                    )
            )
        }

        // PNG gradient overlay - on top of content and above the Brush gradient
        // Only visible when focused on "Skróty v2" in TELEWIZJA section
        // Animated with fade in/out (300ms)
        val topGradientAlpha by animateFloatAsState(
            targetValue = if (isTelewizjaSkrotyFocused) 1f else 0f,
            animationSpec = tween(durationMillis = 300),
            label = "top_gradient_alpha"
        )

        if (topGradientAlpha > 0f) {
            Image(
                painter = painterResource(R.drawable.gradient_top_100),
                contentDescription = null,
                modifier = Modifier
                    .fillMaxWidth()
                    .align(Alignment.TopCenter)
                    .zIndex(6f)  // Above brush gradient (5f), below menu bar (10f)
                    .alpha(topGradientAlpha),
                contentScale = ContentScale.FillWidth
            )
        }

        // Smooth loader overlay (Netflix-style transition)
        AnimatedVisibility(
            visible = isContentLoading,
            enter = fadeIn(animationSpec = tween(150)),
            exit = fadeOut(animationSpec = tween(150))
        ) {
            Box(
                modifier = Modifier
                    .fillMaxSize()
                    .background(Color(0xFF281443)), // Menu background color
                contentAlignment = Alignment.Center
            ) {
                Column(horizontalAlignment = Alignment.CenterHorizontally) {
                    CircularProgressIndicator(
                        color = Color(0xFF5AECD3), // Aqua focus color
                        modifier = Modifier.size(56.dp),
                        strokeWidth = 4.dp
                    )
                    Spacer(modifier = Modifier.height(16.dp))
                    Text(
                        text = "Ładowanie...",
                        color = Color(0xFFEEEEEE),
                        fontSize = 20.sp,
                        fontWeight = FontWeight.Medium
                    )
                }
            }
        }

        val compatMenuState = TopMenuState2(
            focusedItemId = MenuPositions.getSectionForPosition(globalFocusState.value.currentPosition),
            selectedItemId = globalFocusState.value.sectionId,
            isMenuFocused = globalFocusState.value.currentRow == 0 && focusedRightButton == -1 && !isPakietyFocused && !isLeftProfilFocused
        )

        // v2: ukryj top menu na ekranie profilu — user musi wybrać profil bez rozpraszania
        val hideTopMenu = profileVariant == 1 && globalFocusState.value.sectionId == "PROFILE"
        if (!hideTopMenu) TopMenuBar2(
            menuItems = menuItems,
            menuState = compatMenuState,
            focusRequesters = focusRequesters,
            onMenuItemFocused = { itemId ->
                val newPosition = MenuPositions.getPositionForSection(itemId)
                globalFocusState.value = globalFocusState.value.copy(currentPosition = newPosition)
            },
            sx = { sx(it) },
            sy = { sy(it) },
            isVodMode = globalFocusState.value.sectionId == "KINO_PLAY",
            currentSelectedSection = globalFocusState.value.sectionId,
            isInStartContent = false,
            // Left Profil (v4.0.0)
            isLeftProfilFocused = isLeftProfilFocused,
            leftProfilFocusRequester = leftProfilFocusRequester,
            // Right section
            focusedRightButton = focusedRightButton,
            rightButtonFocusRequesters = rightButtonFocusRequesters,
            onKontoClick = {
                // Konto → Navigate to ACCOUNT section
                globalFocusState.value = GlobalFocusManager.transitionToContent(
                    globalFocusState.value,
                    "ACCOUNT"
                )
                focusedRightButton = -1  // Clear right section focus
            },
            onSettingsClick = {
                showSettingsBackdrop = true
                coroutineScope.launch {
                    delay(150)  // Allow backdrop to render before launching settings
                    val intent = android.content.Intent(android.provider.Settings.ACTION_SETTINGS)
                    context.startActivity(intent)
                }
            },
            onProfileClick = {
                // Profil → Navigate to PROFILE section (profile switching)
                globalFocusState.value = GlobalFocusManager.transitionToContent(
                    globalFocusState.value,
                    "PROFILE"
                )
                isLeftProfilFocused = false  // Clear left Profil focus
            },
            profileVariant = profileVariant,
            selectedProfileId = selectedProfileId,
            onPakietyClick = {
                // Pakiety → Navigate to PAKIETY section
                globalFocusState.value = GlobalFocusManager.transitionToContent(
                    globalFocusState.value,
                    "PAKIETY"
                )
                isPakietyFocused = false
            },
            isPakietyFocused = isPakietyFocused,
            pakietyFocusRequester = pakietyFocusRequester,
            isCandyBarVisible = isCandyBarVisible,
            onCandyBarClick = {
                // CandyBar → Navigate to Points History or similar
                globalFocusState.value = GlobalFocusManager.transitionToContent(
                    globalFocusState.value,
                    "POINTS_HISTORY"  // TODO: May need adjustment for actual destination
                )
                isPakietyFocused = false
            },
            showProfileNotificationBadge = showProfileNotificationBadge,
            showKontoUpdateBadge = showKontoUpdateBadge,
            hazeState = hazeState,  // Pass haze state for blur effect
            variantConfig = currentVariantConfig,  // Design variant (key "4" to cycle)
            modifier = Modifier.align(Alignment.TopCenter).zIndex(10f)
        )

        // PIP (Picture-in-Picture) Overlay
        if (pipPlayer != null) {
            Box(
                modifier = Modifier
                    .align(Alignment.BottomEnd)
                    .padding(bottom = sy(80), end = sx(80))
                    .size(width = sx(480), height = sy(270))  // 480×270px (16:9 aspect ratio)
                    .zIndex(1000f)  // Highest - above everything including dialog
            ) {
                AndroidView(
                    factory = { ctx ->
                        com.google.android.exoplayer2.ui.PlayerView(ctx).apply {
                            useController = false  // No controls, just video
                            player = pipPlayer
                        }
                    },
                    update = { playerView ->
                        // Upewnij się że player odtwarza po przypisaniu
                        pipPlayer?.let { player ->
                            if (!player.isPlaying) {
                                player.playWhenReady = true
                            }
                        }
                    },
                    modifier = Modifier.fillMaxSize()
                )
            }
        }

        // Settings backdrop overlay - dark layer behind Android settings drawer
        if (showSettingsBackdrop) {
            Box(
                modifier = Modifier
                    .fillMaxSize()
                    .zIndex(50f)
                    .background(Color(0xFF281443))
            ) {
                Column(
                    modifier = Modifier
                        .align(Alignment.CenterStart)
                        .padding(start = sx(200)),
                    horizontalAlignment = Alignment.Start
                ) {
                    Icon(
                        imageVector = Icons.Default.Settings,
                        contentDescription = null,
                        tint = Color(0xFFEEEEEE),
                        modifier = Modifier.size(sx(64))
                    )
                    Spacer(modifier = Modifier.height(sy(16)))
                    Text(
                        text = "Ustawienia systemowe",
                        color = Color(0xFFEEEEEE),
                        fontSize = (64 * sy(1).value).sp,
                        fontWeight = FontWeight.Medium
                    )
                }
            }
        }

        // PIP Dialog - shown when PLAY/PAUSE pressed with active PIP
        if (showPipDialog && pipPlayer != null) {
            PipDialogMenu(
                onDismiss = {
                    showPipDialog = false
                },
                onFullscreen = {
                    onReturnToEpgDay()
                    onClosePip()
                },
                onClose = {
                    onClosePip()
                },
                sx = ::sx,
                sy = ::sy
            )
        }

        // Dev modal (otwierany Key.Zero) — przełączniki trybów / wariantów
        if (showDevModal) {
            DevTogglesModal(
                aplikacjeVariant = aplikacjeVariant,
                onAplikacjeVariantCycle = {
                    aplikacjeVariant = (aplikacjeVariant + 1) % 2
                    sliderPrefs.edit().putInt("aplikacje_variant", aplikacjeVariant).apply()
                },
                profileVariant = profileVariant,
                onProfileVariantCycle = {
                    profileVariant = (profileVariant + 1) % 2
                    sliderPrefs.edit().putInt("profile_variant", profileVariant).apply()
                },
                vodWypozyczoneVariant = vodWypozyczoneVariant,
                onVodWypozyczoneVariantCycle = {
                    vodWypozyczoneVariant = (vodWypozyczoneVariant + 1) % 2
                    sliderPrefs.edit().putInt("vod_wypozyczone_variant", vodWypozyczoneVariant).apply()
                },
                onDismiss = { showDevModal = false }
            )
        }
    }
}

/**
 * Dev modal — przełączniki trybów developerskich. Otwierany Key.Zero.
 */
@Composable
private fun DevTogglesModal(
    aplikacjeVariant: Int,
    onAplikacjeVariantCycle: () -> Unit,
    profileVariant: Int,
    onProfileVariantCycle: () -> Unit,
    vodWypozyczoneVariant: Int,
    onVodWypozyczoneVariantCycle: () -> Unit,
    onDismiss: () -> Unit
) {
    val aplikacjeVariantLabels = arrayOf("Hero+kanały", "Aplikacje na top + slider")
    val profileVariantLabels = arrayOf("Wersja 1 (Profil)", "Wersja 2 (Wyjdź z profilu)")
    val vodWypLabels = arrayOf("v1: nad sliderem", "v2: pod sliderem (default)")
    val ctx = androidx.compose.ui.platform.LocalContext.current
    // Read rentals.value so the count label re-renders after clearAll
    val rentalCount = com.uxellence.tv.v3.rental.RentalManager.rentals.value.size
    val items: List<Triple<String, String, () -> Unit>> = listOf(
        Triple("Aplikacje variant", aplikacjeVariantLabels.getOrElse(aplikacjeVariant) { aplikacjeVariant.toString() }, onAplikacjeVariantCycle),
        Triple("Profil variant", profileVariantLabels.getOrElse(profileVariant) { profileVariant.toString() }, onProfileVariantCycle),
        Triple("Wypożyczone Kino Play", vodWypLabels.getOrElse(vodWypozyczoneVariant) { vodWypozyczoneVariant.toString() }, onVodWypozyczoneVariantCycle),
        Triple(
            "Wypożyczone",
            "Wyczyść ($rentalCount)",
            { com.uxellence.tv.v3.rental.RentalManager.clearAll(ctx) }
        )
    )
    var selectedIndex by remember { mutableStateOf(0) }
    val focusRequesters = remember(items.size) { List(items.size) { FocusRequester() } }
    LaunchedEffect(Unit) {
        if (focusRequesters.isNotEmpty()) focusRequesters[0].requestFocus()
    }

    androidx.compose.ui.window.Dialog(
        onDismissRequest = onDismiss,
        properties = androidx.compose.ui.window.DialogProperties(usePlatformDefaultWidth = false)
    ) {
        Box(
            modifier = Modifier
                .fillMaxWidth(0.55f)
                .wrapContentHeight()
                .background(Color(0xFF281443), RoundedCornerShape(16.dp))
                .border(2.dp, Color(0xFF5FEDD4), RoundedCornerShape(16.dp))
                .padding(32.dp)
                .onPreviewKeyEvent { event ->
                    if (event.type == KeyEventType.KeyDown && event.key == Key.Back) {
                        onDismiss(); true
                    } else false
                }
        ) {
            Column(verticalArrangement = Arrangement.spacedBy(6.dp)) {
                Text(
                    text = "Tryby (debug)",
                    color = Color(0xFFEEEEEE),
                    fontSize = 14.sp,
                    fontWeight = FontWeight.Bold,
                    modifier = Modifier.padding(bottom = 4.dp)
                )
                items.forEachIndexed { idx, (label, value, action) ->
                    val isItemFocused = selectedIndex == idx
                    Row(
                        modifier = Modifier
                            .fillMaxWidth()
                            .background(
                                if (isItemFocused) Color(0xFF5FEDD4).copy(alpha = 0.18f) else Color(0x10FFFFFF),
                                RoundedCornerShape(8.dp)
                            )
                            .padding(horizontal = 16.dp, vertical = 7.dp)
                            .focusRequester(focusRequesters[idx])
                            .onFocusChanged { if (it.isFocused) selectedIndex = idx }
                            .focusable()
                            .onPreviewKeyEvent { event ->
                                if (event.type == KeyEventType.KeyDown &&
                                    (event.key == Key.Enter || event.key == Key.DirectionCenter)
                                ) {
                                    action(); true
                                } else false
                            },
                        horizontalArrangement = Arrangement.SpaceBetween,
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Text(label, color = Color(0xFFEEEEEE), fontSize = 10.sp)
                        Text(value, color = Color(0xFF5FEDD4), fontSize = 10.sp, fontWeight = FontWeight.Bold)
                    }
                }
                Text(
                    text = "↑↓ wybór  ·  OK toggle  ·  BACK zamknij",
                    color = Color(0x88EEEEEE),
                    fontSize = 8.sp,
                    modifier = Modifier.padding(top = 6.dp)
                )
            }
        }
    }
}

/**
 * TopMenuBar2 - Redesigned per Figma (2025-12)
 *
 * v4.0.0 STRUCTURE:
 * [Profil] | [Menu Container: Start ... Search] | [CandyBar] [Konto] [Ustawienia] | [Clock]
 *
 * - Profil is on LEFT side (before Start)
 * - Right section icons (0=Konto, 1=Ustawienia):
 *   - Konto → ACCOUNT section
 *   - Ustawienia → Android system settings
 */
@Composable
internal fun TopMenuBar2(
    menuItems: List<MenuItem2>,
    menuState: TopMenuState2,
    focusRequesters: Map<String, FocusRequester>,
    onMenuItemFocused: (String) -> Unit,
    sx: (Int) -> androidx.compose.ui.unit.Dp,
    sy: (Int) -> androidx.compose.ui.unit.Dp,
    isVodMode: Boolean = false,
    currentSelectedSection: String = "",
    isInStartContent: Boolean = false,
    // Left Profil (v4.0.0: moved to left side)
    isLeftProfilFocused: Boolean = false,
    leftProfilFocusRequester: FocusRequester? = null,
    // Right section (0=Konto, 1=Ustawienia)
    focusedRightButton: Int = -1,
    rightButtonFocusRequesters: Map<Int, FocusRequester> = emptyMap(),
    onKontoClick: () -> Unit = {},                                      // Konto → ACCOUNT
    onSettingsClick: () -> Unit = {},                                   // Ustawienia → System settings
    onProfileClick: () -> Unit = {},                                    // Profil → PROFILE section
    onPakietyClick: () -> Unit = {},
    isPakietyFocused: Boolean = false,
    pakietyFocusRequester: FocusRequester? = null,
    isCandyBarVisible: Boolean = false,                                  // Toggle between Pakiety and CandyBar
    onCandyBarClick: () -> Unit = {},                                    // CandyBar -> Points History
    showProfileNotificationBadge: Boolean = false,
    showKontoUpdateBadge: Boolean = false,
    hazeState: HazeState? = null,                                         // Haze state for blur effect
    variantConfig: TopMenuVariantConfig = MENU_VARIANTS[0],              // Design variant config (key "4" to cycle)
    profileVariant: Int = 0,                                             // 0=tooltip "Profil", 1=tooltip "Wyjdź z profilu"
    selectedProfileId: String = "1",                                     // Aktywny profil: "1"=Piotr, "2"=Angelika, "kids"=Dzieci
    modifier: Modifier = Modifier
) {
    var currentTime by remember { mutableStateOf(LocalTime.now()) }

    LaunchedEffect(Unit) {
        while (true) {
            currentTime = LocalTime.now()
            delay(1000)
        }
    }

    Box(
        modifier = modifier
            .fillMaxWidth()
            .wrapContentHeight()
    ) {
        // Layer 0: Top gradient overlay - DISABLED (duplicate, main gradient is at lines 1850-1865)
        // Using only one gradient (#48227C) for consistent look with app background
        // Box(
        //     modifier = Modifier
        //         .fillMaxWidth()
        //         .height(sy(TopMenuDesign.GRADIENT_HEIGHT))
        //         .background(
        //             brush = Brush.verticalGradient(
        //                 colors = listOf(
        //                     TopMenuDesign.COLOR_GRADIENT_TOP,  // #281443 at top
        //                     Color.Transparent                   // Transparent at bottom
        //                 )
        //             )
        //         )
        // )

        // Layer 1: Aqua Ellipse Glow (ambient light at top)
        // DISABLED - needs gradient implementation instead of solid color + blur
        // AquaEllipseGlow(
        //     sx = sx,
        //     sy = sy,
        //     modifier = Modifier
        //         .align(Alignment.TopCenter)
        //         .offset(y = sy(TopMenuDesign.CONTAINER_TOP_OFFSET))
        // )

        // Determine if using classic layout (v4.0.0 Google Play design) vs modern Figma design
        // V2 (CLASSIC_FILL) and V3 (FLOATING_FILL) use classic layout with profile on left
        val useClassicLayout = variantConfig.focusType == FocusType.CLASSIC_FILL ||
                               variantConfig.focusType == FocusType.FLOATING_FILL

        // Layer 2: Main row with container + clock
        if (useClassicLayout) {
            // === CLASSIC LAYOUT (v4.0.0) ===
            // Profil on left, Container wraps menu items, right section is outside without background
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(top = sy(20), start = sx(20), end = sx(20))
                    .height(sy(97)),  // v4.0.0: 97px height
                horizontalArrangement = Arrangement.SpaceBetween,
                verticalAlignment = Alignment.CenterVertically
            ) {
                // LEFT SIDE: Profil + Container with menu items
                Row(
                    horizontalArrangement = Arrangement.spacedBy(sx(15)),  // Gap between Profil and container
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    // Profil button (separate, no background - on left side before menu)
                    if (leftProfilFocusRequester != null) {
                        ProfilButton(
                            isFocused = isLeftProfilFocused,
                            isSelected = currentSelectedSection == "PROFILE",
                            focusRequester = leftProfilFocusRequester,
                            onClick = onProfileClick,
                            showBadge = showProfileNotificationBadge,
                            onBoundsChanged = { },
                            focusType = variantConfig.focusType,
                            selectedProfileId = selectedProfileId,
                            sx = sx,
                            sy = sy
                        )
                    }

                    // Container ONLY for menu items (no shadow, no blur)
                    // For FLOATING_FILL: wrap with Box to hold AnimatedFocusIndicator
                    val isFloatingFillLayout = variantConfig.focusType == FocusType.FLOATING_FILL

                    // Map to store bounds of focusable elements (for FLOATING_FILL)
                    val focusBoundsMap = remember { mutableStateMapOf<String, FocusableBounds>() }
                    // Track container position for relative calculations
                    var containerOffsetX by remember { mutableFloatStateOf(0f) }
                    var containerOffsetY by remember { mutableFloatStateOf(0f) }

                    Box(
                        modifier = Modifier
                            .height(sy(97))
                            .wrapContentWidth()
                            .background(Color(0x4A000000), RoundedCornerShape(sx(49)))
                            .padding(horizontal = sx(10), vertical = sy(8))
                            .onGloballyPositioned { coords ->
                                containerOffsetX = coords.positionInRoot().x
                                containerOffsetY = coords.positionInRoot().y
                            },
                        // FLOATING_FILL: TopStart for correct indicator positioning
                        contentAlignment = if (isFloatingFillLayout) Alignment.TopStart else Alignment.Center
                    ) {
                        // AnimatedFocusIndicator for FLOATING_FILL (rendered below buttons)
                        if (isFloatingFillLayout) {
                            // Determine which item to highlight and with what color:
                            // - Menu focused: show AQUA on focused item
                            // - Menu not focused (content focused): show WHITE on selected item
                            val (indicatorKey, indicatorColor) = if (menuState.isMenuFocused && !isInStartContent) {
                                menuState.focusedItemId to TopMenuDesign.COLOR_FOCUS_BORDER  // Aqua
                            } else {
                                menuState.selectedItemId to Color.White  // White for selected
                            }

                            // Convert from root coordinates to container-relative
                            val relativeBounds = indicatorKey.takeIf { it.isNotEmpty() }?.let { key ->
                                focusBoundsMap[key]?.let { bounds ->
                                    bounds.copy(
                                        x = bounds.x - containerOffsetX,
                                        y = bounds.y - containerOffsetY
                                    )
                                }
                            }

                            AnimatedFocusIndicator(
                                targetBounds = relativeBounds,
                                borderWidth = sx(variantConfig.focusBorderWidth),
                                isVisible = relativeBounds != null,
                                focusType = variantConfig.focusType,
                                indicatorColor = indicatorColor,
                                sx = sx,
                                sy = sy,
                                modifier = Modifier.zIndex(-1f)
                            )
                        }

                        Row(
                            // V3 (FLOATING_FILL): smaller gaps (6px), V2 (CLASSIC_FILL): normal gaps (13px)
                            horizontalArrangement = Arrangement.spacedBy(sx(if (isFloatingFillLayout) 6 else 13)),
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            // Menu items (Start, Moje, Telewizja, Kino Play, Wideo, Aplikacje, Search)
                        menuItems.forEach { item ->
                            if (item.id == "SEARCH") {
                                MenuSearchIcon2(
                                    isSelected = menuState.selectedItemId == item.id,
                                    isFocused = menuState.focusedItemId == item.id && menuState.isMenuFocused,
                                    focusRequester = focusRequesters[item.id]!!,
                                    onFocused = { onMenuItemFocused(item.id) },
                                    currentSelectedSection = currentSelectedSection,
                                    isInStartContent = isInStartContent,
                                    isMenuFocused = menuState.isMenuFocused,  // For FLOATING_FILL icon color
                                    onBoundsChanged = { bounds ->
                                        if (isFloatingFillLayout) focusBoundsMap[item.id] = bounds
                                    },
                                    focusType = variantConfig.focusType,
                                    sx = sx,
                                    sy = sy
                                )
                            } else {
                                MenuButton2(
                                    title = item.title,
                                    isSelected = menuState.selectedItemId == item.id,
                                    isFocused = menuState.focusedItemId == item.id && menuState.isMenuFocused,
                                    focusRequester = focusRequesters[item.id]!!,
                                    onFocused = { onMenuItemFocused(item.id) },
                                    currentSelectedSection = currentSelectedSection,
                                    isInStartContent = isInStartContent,
                                    isMenuFocused = menuState.isMenuFocused,  // For FLOATING_FILL text color
                                    onBoundsChanged = { bounds ->
                                        if (isFloatingFillLayout) focusBoundsMap[item.id] = bounds
                                    },
                                    focusType = variantConfig.focusType,
                                    sx = sx,
                                    sy = sy
                                )
                            }
                        }
                    }
                }
                }  // End of LEFT SIDE Row (Profil + Container)

                // RIGHT: No background! (outside container)
                Row(
                    horizontalArrangement = Arrangement.spacedBy(sx(15)),  // v4.0.0: 15px gap
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    // CandyBar or Pakiety button
                    if (pakietyFocusRequester != null) {
                        if (isCandyBarVisible) {
                            CandyBarButton(
                                isFocused = isPakietyFocused,
                                isSelected = currentSelectedSection == "POINTS_HISTORY",
                                focusRequester = pakietyFocusRequester,
                                onClick = onCandyBarClick,
                                onBoundsChanged = { },
                                focusType = variantConfig.focusType,
                                sx = sx,
                                sy = sy
                            )
                        } else {
                            PakietyButton(
                                isFocused = isPakietyFocused,
                                isSelected = currentSelectedSection == "PAKIETY",
                                focusRequester = pakietyFocusRequester,
                                onClick = onPakietyClick,
                                onBoundsChanged = { },
                                focusType = variantConfig.focusType,
                                sx = sx,
                                sy = sy
                            )
                        }
                    }

                    // Konto icon
                    if (rightButtonFocusRequesters.containsKey(0)) {
                        KontoButton(
                            isFocused = focusedRightButton == 0,
                            isSelected = currentSelectedSection == "ACCOUNT",
                            focusRequester = rightButtonFocusRequesters[0]!!,
                            onClick = onKontoClick,
                            showBadge = showKontoUpdateBadge,
                            onBoundsChanged = { },
                            focusType = variantConfig.focusType,
                            sx = sx,
                            sy = sy
                        )
                    }

                    // Ustawienia icon
                    if (rightButtonFocusRequesters.containsKey(1)) {
                        SettingsButton(
                            isFocused = focusedRightButton == 1,
                            focusRequester = rightButtonFocusRequesters[1]!!,
                            onClick = onSettingsClick,
                            onBoundsChanged = { },
                            focusType = variantConfig.focusType,
                            sx = sx,
                            sy = sy
                        )
                    }
                    // Note: Profil moved to LEFT SIDE (before Start) in v4.0.0

                    // Clock (outside container)
                    Text(
                        text = "${currentTime.hour.toString().padStart(2, '0')}:${currentTime.minute.toString().padStart(2, '0')}",
                        color = TopMenuDesign.COLOR_TEXT,
                        fontSize = (32 * sy(1).value / 1).sp,
                        fontWeight = FontWeight.Bold,
                        letterSpacing = 0.2.sp
                    )
                }
            }
        } else {
        // === MODERN LAYOUT (Figma 2025-12) ===
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .padding(
                    top = sy(TopMenuDesign.CONTAINER_TOP_OFFSET),  // 32px from top
                    start = sx(TopMenuDesign.MARGIN_LEFT),         // 54px from left edge
                    end = sx(TopMenuDesign.MARGIN_RIGHT)           // 60px from right edge
                )
                .height(sy(TopMenuDesign.CONTAINER_HEIGHT)),  // Figma: 112px
            horizontalArrangement = Arrangement.spacedBy(sx(TopMenuDesign.GAP_CONTAINER_CLOCK)),  // 40px gap between container and clock
            verticalAlignment = Alignment.CenterVertically
        ) {
            // === SINGLE CONTAINER: Menu + Search + Pakiety + Icons (fills available space) ===
            // Using Card with CardDefaults.cardElevation (same approach as SliderMix)
            val containerShape = RoundedCornerShape(sx(TopMenuDesign.CONTAINER_BORDER_RADIUS))

            // Create blur style for menu container (only used for BLUR background type)
            val menuBlurStyle = HazeStyle(
                backgroundColor = TopMenuDesign.COLOR_BG_CONTAINER,  // Required: container background color
                blurRadius = 25.dp,
                tint = HazeTint(Color.White.copy(alpha = 0.05f))
            )

            // Determine container color based on variant's background type
            val containerColor = when (variantConfig.backgroundType) {
                BackgroundType.BLUR -> TopMenuDesign.COLOR_BG_CONTAINER
                BackgroundType.SOLID -> variantConfig.backgroundColor
                BackgroundType.GRADIENT -> Color.Transparent  // Gradient drawn separately
                BackgroundType.TRANSPARENT -> Color.Transparent
            }

            // Apply haze blur only for BLUR background type
            val useBlur = variantConfig.backgroundType == BackgroundType.BLUR && hazeState != null

            Card(
                modifier = Modifier
                    .weight(1f)  // Fill available space (stretches between margins)
                    .height(sy(TopMenuDesign.CONTAINER_HEIGHT))  // Figma: 112px
                    .then(
                        if (useBlur) {
                            Modifier.hazeChild(
                                state = hazeState!!,
                                shape = containerShape,  // Match Card's rounded corners
                                style = menuBlurStyle
                            )
                        } else {
                            Modifier
                        }
                    )
                    .then(
                        // Apply gradient background for GRADIENT type
                        if (variantConfig.backgroundType == BackgroundType.GRADIENT) {
                            Modifier.background(
                                brush = Brush.verticalGradient(
                                    colors = listOf(
                                        variantConfig.backgroundColor,
                                        variantConfig.backgroundColor.copy(alpha = 0.3f)
                                    )
                                ),
                                shape = containerShape
                            )
                        } else {
                            Modifier
                        }
                    ),
                shape = containerShape,
                colors = CardDefaults.cardColors(
                    containerColor = containerColor
                ),
                elevation = CardDefaults.cardElevation(defaultElevation = 8.dp)  // Same as SliderMix
            ) {
                // Center content vertically inside Card
                Box(
                    modifier = Modifier.fillMaxSize(),
                    contentAlignment = Alignment.Center
                ) {
                // === ANIMATED FOCUS INDICATOR SYSTEM ===
                // Map to store bounds of all focusable elements
                val focusBoundsMap = remember { mutableStateMapOf<String, FocusableBounds>() }
                val density = LocalDensity.current

                // Track container root position for relative calculations
                var containerRootX by remember { mutableFloatStateOf(0f) }
                var containerRootY by remember { mutableFloatStateOf(0f) }

                // Determine current focused/selected element key and indicator color
                // V1 selected state: pokazuj selected (biały) TYLKO gdy menu nie jest focused
                val (currentFocusKey: String?, indicatorColor: Color) = when {
                    // Left Profil focused - aqua (v4.0.0: Profil is inside container on left)
                    isLeftProfilFocused -> "profile" to TopMenuDesign.COLOR_FOCUS_BORDER
                    // Menu focused - pokazuj fokus (aqua)
                    menuState.isMenuFocused && menuState.focusedItemId != null ->
                        "menu_${menuState.focusedItemId}" to TopMenuDesign.COLOR_FOCUS_BORDER
                    // Inne elementy focused (pakiety, right buttons) - aqua
                    isPakietyFocused -> "pakiety" to TopMenuDesign.COLOR_FOCUS_BORDER
                    focusedRightButton == 0 -> "konto" to TopMenuDesign.COLOR_FOCUS_BORDER
                    focusedRightButton == 1 -> "settings" to TopMenuDesign.COLOR_FOCUS_BORDER
                    // Pakiety/CandyBar selected (biały) - gdy jesteśmy w POINTS_HISTORY lub PAKIETY content
                    !menuState.isMenuFocused && (currentSelectedSection == "POINTS_HISTORY" || currentSelectedSection == "PAKIETY") ->
                        "pakiety" to Color.White
                    // Konto selected (biały) - gdy jesteśmy w ACCOUNT content
                    !menuState.isMenuFocused && currentSelectedSection == "ACCOUNT" ->
                        "konto" to Color.White
                    // Profile selected (biały) - gdy jesteśmy w PROFILE content
                    !menuState.isMenuFocused && currentSelectedSection == "PROFILE" ->
                        "profile" to Color.White
                    // Menu NIE focused - pokazuj selected (biały) dla V1
                    !menuState.isMenuFocused && menuState.selectedItemId != null ->
                        "menu_${menuState.selectedItemId}" to Color.White
                    else -> null to Color.Transparent
                }

                // Show floating indicator for FLOATING_INDICATOR and FLOATING_FILL focus types
                val showFocusIndicator = currentFocusKey != null && !isInStartContent &&
                    (variantConfig.focusType == FocusType.FLOATING_INDICATOR ||
                     variantConfig.focusType == FocusType.FLOATING_FILL)

                // Container for AnimatedFocusIndicator - starts at 0,0 of outer Box
                Box(
                    modifier = Modifier
                        .fillMaxSize()
                        .zIndex(-1f)
                        .onGloballyPositioned { coords ->
                            containerRootX = coords.positionInRoot().x
                            containerRootY = coords.positionInRoot().y
                        },
                    contentAlignment = Alignment.TopStart
                ) {
                    AnimatedFocusIndicator(
                        targetBounds = currentFocusKey?.let { key ->
                            focusBoundsMap[key]?.let { bounds ->
                                // Convert from root coordinates to container-relative
                                bounds.copy(
                                    x = bounds.x - containerRootX,
                                    y = bounds.y - containerRootY
                                )
                            }
                        },
                        borderWidth = sx(variantConfig.focusBorderWidth),  // V1: 4px
                        isVisible = showFocusIndicator,
                        focusType = variantConfig.focusType,
                        indicatorColor = indicatorColor,  // Aqua dla focus, biały dla selected
                        sx = sx,
                        sy = sy
                    )
                }

                // Main container row with 3 sections: LEFT | CENTER | RIGHT
                Row(
                    horizontalArrangement = Arrangement.SpaceBetween,
                    verticalAlignment = Alignment.CenterVertically,
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(horizontal = sx(TopMenuDesign.CONTAINER_PADDING_H), vertical = sy(TopMenuDesign.CONTAINER_PADDING_V))  // Figma: 16px H, 10px V
                        .height(sy(TopMenuDesign.ITEM_HEIGHT))  // Figma: 80px
                ) {
                    // === LEFT SECTION: Profil + Menu items (Start, Moje, Telewizja, etc.) ===
                    Row(
                        horizontalArrangement = Arrangement.spacedBy(sx(TopMenuDesign.ITEM_GAP)),  // Figma: 20px gap
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        // Profil button (inside container, before menu items - v4.0.0)
                        if (leftProfilFocusRequester != null) {
                            Box {
                                ProfilButton(
                                    isFocused = isLeftProfilFocused,
                                    isSelected = currentSelectedSection == "PROFILE",
                                    focusRequester = leftProfilFocusRequester,
                                    onClick = onProfileClick,
                                    showBadge = showProfileNotificationBadge,
                                    onBoundsChanged = { bounds ->
                                        focusBoundsMap["profile"] = bounds
                                    },
                                    focusType = variantConfig.focusType,
                                    selectedProfileId = selectedProfileId,
                                    sx = sx,
                                    sy = sy
                                )
                                // Floating tooltip label (Popup renders outside parent bounds)
                                if (isLeftProfilFocused) {
                                    Popup(
                                        alignment = Alignment.BottomCenter,
                                        offset = IntOffset(0, sy(95).value.toInt())  // Below button (80px height + 15px gap)
                                    ) {
                                        Text(
                                            text = if (profileVariant == 1) "Wyjdź z profilu" else "Profil",
                                            color = Color(0xFF5FEDD4),  // Aqua
                                            fontSize = (24 * sy(1).value).sp,
                                            fontWeight = FontWeight.Medium
                                        )
                                    }
                                }
                            }
                        }

                        // Menu items (Start, Moje, Telewizja, Kino Play, Wideo, Aplikacje, Search)
                        menuItems.forEach { item ->
                            if (item.id == "SEARCH") {
                                MenuSearchIcon2(
                                    isSelected = menuState.selectedItemId == item.id,
                                    isFocused = menuState.focusedItemId == item.id && menuState.isMenuFocused,
                                    focusRequester = focusRequesters[item.id]!!,
                                    onFocused = { onMenuItemFocused(item.id) },
                                    currentSelectedSection = currentSelectedSection,
                                    isInStartContent = isInStartContent,
                                    onBoundsChanged = { bounds ->
                                        focusBoundsMap["menu_${item.id}"] = bounds
                                    },
                                    focusType = variantConfig.focusType,
                                    sx = sx,
                                    sy = sy
                                )
                            } else {
                                MenuButton2(
                                    title = item.title,
                                    isSelected = menuState.selectedItemId == item.id,
                                    isFocused = menuState.focusedItemId == item.id && menuState.isMenuFocused,
                                    focusRequester = focusRequesters[item.id]!!,
                                    onFocused = { onMenuItemFocused(item.id) },
                                    currentSelectedSection = currentSelectedSection,
                                    isInStartContent = isInStartContent,
                                    isMenuFocused = menuState.isMenuFocused,  // CRITICAL: Pass menu focus state for border logic
                                    onBoundsChanged = { bounds ->
                                        focusBoundsMap["menu_${item.id}"] = bounds
                                    },
                                    focusType = variantConfig.focusType,  // Design variant focus style
                                    sx = sx,
                                    sy = sy
                                )
                            }
                        }
                    }

                    // === CENTER SECTION: Pakiety OR CandyBar (centered between left and right) ===
                    if (pakietyFocusRequester != null) {
                        if (isCandyBarVisible) {
                            CandyBarButton(
                                isFocused = isPakietyFocused,
                                isSelected = currentSelectedSection == "POINTS_HISTORY",
                                focusRequester = pakietyFocusRequester,
                                onClick = onCandyBarClick,
                                onBoundsChanged = { bounds ->
                                    focusBoundsMap["pakiety"] = bounds
                                },
                                focusType = variantConfig.focusType,
                                sx = sx,
                                sy = sy
                            )
                        } else {
                            PakietyButton(
                                isFocused = isPakietyFocused,
                                isSelected = currentSelectedSection == "PAKIETY",
                                focusRequester = pakietyFocusRequester,
                                onClick = onPakietyClick,
                                onBoundsChanged = { bounds ->
                                    focusBoundsMap["pakiety"] = bounds
                                },
                                focusType = variantConfig.focusType,
                                sx = sx,
                                sy = sy
                            )
                        }
                    }

                    // === RIGHT SECTION: Konto, Ustawienia, Profil (aligned to right) ===
                    Row(
                        horizontalArrangement = Arrangement.spacedBy(sx(TopMenuDesign.ITEM_GAP)),  // Figma: 20px gap
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        // Konto icon (person)
                        if (rightButtonFocusRequesters.containsKey(0)) {
                            Box {
                                KontoButton(
                                    isFocused = focusedRightButton == 0,
                                    isSelected = currentSelectedSection == "ACCOUNT",
                                    focusRequester = rightButtonFocusRequesters[0]!!,
                                    onClick = onKontoClick,
                                    showBadge = showKontoUpdateBadge,
                                    onBoundsChanged = { bounds ->
                                        focusBoundsMap["konto"] = bounds
                                    },
                                    focusType = variantConfig.focusType,
                                    sx = sx,
                                    sy = sy
                                )
                                // Floating tooltip label (Popup renders outside parent bounds)
                                if (focusedRightButton == 0) {
                                    Popup(
                                        alignment = Alignment.BottomCenter,
                                        offset = IntOffset(0, sy(95).value.toInt())  // Below button (80px height + 15px gap)
                                    ) {
                                        Text(
                                            text = "Konto",
                                            color = Color(0xFF5FEDD4),  // Aqua
                                            fontSize = (24 * sy(1).value).sp,
                                            fontWeight = FontWeight.Medium
                                        )
                                    }
                                }
                            }
                        }

                        // Ustawienia icon (gear)
                        if (rightButtonFocusRequesters.containsKey(1)) {
                            Box {
                                SettingsButton(
                                    isFocused = focusedRightButton == 1,
                                    focusRequester = rightButtonFocusRequesters[1]!!,
                                    onClick = onSettingsClick,
                                    onBoundsChanged = { bounds ->
                                        focusBoundsMap["settings"] = bounds
                                    },
                                    focusType = variantConfig.focusType,
                                    sx = sx,
                                    sy = sy
                                )
                                // Floating tooltip label (Popup renders outside parent bounds)
                                if (focusedRightButton == 1) {
                                    Popup(
                                        alignment = Alignment.BottomCenter,
                                        offset = IntOffset(0, sy(95).value.toInt())  // Below button (80px height + 15px gap)
                                    ) {
                                        Text(
                                            text = "Ustawienia",
                                            color = Color(0xFF5FEDD4),  // Aqua
                                            fontSize = (24 * sy(1).value).sp,
                                            fontWeight = FontWeight.Medium
                                        )
                                    }
                                }
                            }
                        }
                        // NOTE: Profil button usunięty z prawej strony - teraz jest tylko na LEWEJ stronie przed Start
                    }
                }
                }  // End centering Box
            }  // End SINGLE CONTAINER (Card)

            // === CLOCK (outside container, no extra padding needed - margins are on parent Row) ===
            Text(
                text = "${currentTime.hour.toString().padStart(2, '0')}:${currentTime.minute.toString().padStart(2, '0')}",
                color = TopMenuDesign.COLOR_TEXT,                    // Figma: #EEEEEE
                fontSize = (32 * sy(1).value / 1).sp,                // Figma: 32px (Layout Engineer pattern)
                fontWeight = FontWeight.Bold,                         // Figma: Bold
                letterSpacing = 0.2.sp
            )
        }
        }  // End else (modern layout)
    }
}

/**
 * CandyBar button showing points and days - NEW Figma design (node 253:8401)
 * Structure: [Wallet Icon 48x48] [gap 8px] "40 pkt" [divider] "21 dni"
 * Figma: bg rgba(0,0,0,0.4), rounded-[302px], h-80
 * Focus: 8px border #5FEDD4 OUTSIDE - now handled by AnimatedFocusIndicator
 */
@Composable
private fun CandyBarButton(
    points: Int = 40,
    days: Int = 21,
    isFocused: Boolean,
    isSelected: Boolean = false,  // NEW: Selected state when POINTS_HISTORY section is active
    focusRequester: FocusRequester,
    onClick: () -> Unit,
    onBoundsChanged: (FocusableBounds) -> Unit = {},  // NEW: Report bounds for AnimatedFocusIndicator
    focusType: FocusType = FocusType.FLOATING_INDICATOR,  // Design variant focus style
    sx: (Int) -> androidx.compose.ui.unit.Dp,
    sy: (Int) -> androidx.compose.ui.unit.Dp,
    modifier: Modifier = Modifier
) {
    // For buttons OUTSIDE container, FLOATING_FILL should behave like CLASSIC_FILL
    val useClassicStyleFill = focusType == FocusType.CLASSIC_FILL || focusType == FocusType.FLOATING_FILL

    // Background color depends on focus type and selected state
    val backgroundColor = when {
        useClassicStyleFill && isFocused -> Color(0xFF5AECD3)  // Aqua fill on focus
        useClassicStyleFill && isSelected -> Color.White       // White fill on selected
        useClassicStyleFill -> Color(0x0AEEEEEE)               // Transparent default
        else -> TopMenuDesign.COLOR_BG_ITEM                    // Figma: rgba(0,0,0,0.4)
    }

    // Content color depends on focus type and selected state
    val contentColor = when {
        useClassicStyleFill && isFocused -> Color(0xFF48227C)  // Purple on focus
        useClassicStyleFill && isSelected -> Color(0xFF48227C) // Purple on selected
        useClassicStyleFill -> Color(0xFFEEEEEE)               // White default
        else -> TopMenuDesign.COLOR_TEXT                       // Figma: #EEEEEE
    }

    // Use 40px for pill shape (half of height 80px) - gives perfect pill
    val candyBarShape = RoundedCornerShape(sx(40))
    val density = LocalDensity.current

    // Focus border/glow now handled by AnimatedFocusIndicator
    Box(
        modifier = modifier
            .height(sy(TopMenuDesign.ITEM_HEIGHT))      // Figma: 80px
            .wrapContentWidth()
            // REMOVED: shadow() and border() for focused state - now handled by AnimatedFocusIndicator
            // Background only
            .background(backgroundColor, candyBarShape)
            .focusRequester(focusRequester)
            .onPreviewKeyEvent { event ->
                if (event.type == KeyEventType.KeyDown &&
                    (event.key == Key.Enter || event.key == Key.DirectionCenter ||
                     event.key == Key.DirectionDown)) {
                    onClick()
                    true
                } else {
                    false
                }
            }
            .focusable()
            .onGloballyPositioned { coords ->
                // Report bounds for AnimatedFocusIndicator (pill shape = 40px corner radius)
                val cornerRadiusPx = with(density) { sx(40).toPx() }
                onBoundsChanged(
                    FocusableBounds(
                        x = coords.positionInRoot().x,
                        y = coords.positionInRoot().y,
                        width = coords.size.width.toFloat(),
                        height = coords.size.height.toFloat(),
                        cornerRadius = cornerRadiusPx
                    )
                )
            },
        contentAlignment = Alignment.Center
    ) {
        // NEW Figma layout: Row with icon + text row
        Row(
            modifier = Modifier
                .wrapContentSize()
                .padding(horizontal = sx(16)),  // Figma: px-16
            horizontalArrangement = Arrangement.spacedBy(sx(TopMenuDesign.CANDYBAR_GAP_ICON_TEXT)),  // 8px gap
            verticalAlignment = Alignment.CenterVertically
        ) {
            // Wallet icon (48x48px)
            Icon(
                painter = painterResource(id = R.drawable.ic_wallet),
                contentDescription = "Punkty",
                tint = contentColor,
                modifier = Modifier.size(sx(TopMenuDesign.CANDYBAR_ICON_SIZE))  // 48x48px
            )

            // Text row: "40 pkt" | divider | "21 dni"
            Row(
                horizontalArrangement = Arrangement.spacedBy(sx(TopMenuDesign.CANDYBAR_GAP_TEXT_DIVIDER)),  // 12px gap
                verticalAlignment = Alignment.CenterVertically
            ) {
                // Points text
                Text(
                    text = "$points pkt",
                    color = contentColor,
                    fontSize = (TopMenuDesign.CANDYBAR_TEXT_SIZE * sy(1).value).sp,  // 24px
                    fontWeight = FontWeight.Medium,
                    letterSpacing = 0.48.sp  // Figma: 0.48px letter spacing
                )

                // Vertical divider (2px width, 24px height, #EEEEEE)
                Box(
                    modifier = Modifier
                        .width(sx(TopMenuDesign.CANDYBAR_DIVIDER_WIDTH))   // 2px
                        .height(sy(TopMenuDesign.CANDYBAR_DIVIDER_HEIGHT)) // 24px
                        .background(contentColor)  // #EEEEEE
                )

                // Days text
                Text(
                    text = "$days dni",
                    color = contentColor,
                    fontSize = (TopMenuDesign.CANDYBAR_TEXT_SIZE * sy(1).value).sp,  // 24px
                    fontWeight = FontWeight.Medium,
                    letterSpacing = 0.48.sp  // Figma: 0.48px letter spacing
                )
            }
        }
    }
}

/**
 * Profile button with new Figma design
 * Figma: Size 80x80px, icon 40px, bg rgba(0,0,0,0.4)
 * Focus: 8px border #5FEDD4 + glow (NO aqua fill)
 */
@Composable
private fun ProfileButton(
    isFocused: Boolean,
    focusRequester: FocusRequester,
    onClick: () -> Unit,
    showBadge: Boolean = false,
    sx: (Int) -> androidx.compose.ui.unit.Dp,
    sy: (Int) -> androidx.compose.ui.unit.Dp,
    modifier: Modifier = Modifier
) {
    // Figma: background rgba(0,0,0,0.4), focus = border only (not fill)
    val backgroundColor = TopMenuDesign.COLOR_BG_ITEM              // Figma: rgba(0,0,0,0.4)
    val contentColor = TopMenuDesign.COLOR_TEXT                     // Figma: #EEEEEE

    // Figma: Focus = 8px outline + glow
    val borderWidth = if (isFocused) sx(TopMenuDesign.FOCUS_BORDER_WIDTH) else 0.dp  // 8px
    val borderColor = if (isFocused) TopMenuDesign.COLOR_FOCUS_BORDER else Color.Transparent

    Box(
        modifier = modifier
            .size(sx(TopMenuDesign.ICON_SIZE), sy(TopMenuDesign.ICON_SIZE))  // Figma: 80x80px
            // 1. Glow effect (boxShadow in CSS) - blur 80px, 30% alpha aqua
            .then(
                if (isFocused) Modifier.shadow(
                    elevation = sx(40),
                    shape = CircleShape,
                    ambientColor = TopMenuDesign.COLOR_FOCUS_GLOW,
                    spotColor = TopMenuDesign.COLOR_FOCUS_GLOW
                ) else Modifier
            )
            // 2. Background
            .background(backgroundColor, CircleShape)
            // 3. Outline (CSS outline: 8px solid)
            .border(borderWidth, borderColor, CircleShape)
            .focusRequester(focusRequester)
            .focusable()
            .clickable { onClick() },
        contentAlignment = Alignment.Center
    ) {
        Box {
            Image(
                painter = painterResource(id = R.drawable.lamp),
                contentDescription = "Profil",
                modifier = Modifier.size(sx(40), sy(40))           // Figma: 40px icon
            )

            // Notification badge (upper-right corner on button area, not on icon)
            if (showBadge) {
                Box(
                    modifier = Modifier
                        .size(sx(32), sy(32))
                        .offset(x = sx(34), y = -sy(10))
                        .background(Color.Red, CircleShape)
                        .border(sx(3), Color.White, CircleShape)
                )
            }
        }
    }
}

