/**
 * Menu button with new Figma design
 * Figma: Height 80px, border-radius 64px, bg rgba(0,0,0,0.4)
 * Focus: 8px border #5FEDD4 + glow (NO aqua fill)
 * Selected: white background, purple text
 */
@Composable
private fun MenuButton2(
    title: String,
    isSelected: Boolean,
    isFocused: Boolean,
    focusRequester: FocusRequester,
    onFocused: () -> Unit,
    currentSelectedSection: String = "",
    isInStartContent: Boolean = false,
    isMenuFocused: Boolean = true,  // NEW: Whether menu is focused (for FLOATING_FILL text color)
    onBoundsChanged: (FocusableBounds) -> Unit = {},  // Report bounds for AnimatedFocusIndicator
    focusType: FocusType = FocusType.FLOATING_INDICATOR,  // Design variant focus style
    sx: (Int) -> androidx.compose.ui.unit.Dp,
    sy: (Int) -> androidx.compose.ui.unit.Dp
) {
    // CLASSIC_FILL mode - design from version 4.0.0 (Google Play)
    val useClassicFill = focusType == FocusType.CLASSIC_FILL
    // FLOATING_FILL mode - transparent tabs with floating aqua indicator
    val useFloatingFill = focusType == FocusType.FLOATING_FILL
    // FLOATING_INDICATOR mode - AnimatedFocusIndicator handles both focus AND selected states
    val useFloatingIndicator = focusType == FocusType.FLOATING_INDICATOR

    // Background color depends on focus type
    val backgroundColor = when {
        // CLASSIC_FILL: aqua fill ONLY when menu focused AND element focused
        useClassicFill && isFocused && !isInStartContent && isMenuFocused -> Color(0xFF5AECD3)  // Aqua fill
        // CLASSIC_FILL: white fill ONLY when content focused AND element selected
        useClassicFill && isSelected && !isMenuFocused -> Color.White
        useClassicFill -> Color(0x0AEEEEEE)  // Transparent default
        // FLOATING_FILL: always transparent (floating indicator handles both focus and selected)
        useFloatingFill -> Color.Transparent
        // Other focus types: always dark background
        else -> TopMenuDesign.COLOR_BG_ITEM  // Figma: rgba(0,0,0,0.4)
    }

    // Text color depends on focus type
    val textColor = when {
        // CLASSIC_FILL: purple text ONLY when menu focused AND element focused
        useClassicFill && isFocused && !isInStartContent && isMenuFocused -> Color(0xFF48227C)  // Purple
        // CLASSIC_FILL: purple text ONLY when content focused AND element selected
        useClassicFill && isSelected && !isMenuFocused -> Color(0xFF48227C)  // Purple
        useClassicFill -> Color(0xFFEEEEEE)  // White
        // FLOATING_FILL: purple text when indicator is behind (focused OR selected when menu not focused)
        useFloatingFill && isFocused && !isInStartContent -> Color(0xFF48227C)  // Purple (focused - aqua indicator)
        useFloatingFill && isSelected && !isMenuFocused -> Color(0xFF48227C)  // Purple (selected - white indicator)
        useFloatingFill -> Color(0xFFEEEEEE)  // White (no indicator behind)
        // Other focus types: always white text
        else -> TopMenuDesign.COLOR_TEXT  // Figma: #EEEEEE
    }

    // Determine if button should show its own focus border (not floating indicator)
    val showOwnFocusBorder = isFocused && !isInStartContent && focusType == FocusType.BORDER_INSIDE

    // Border: for selected state OR for BORDER_INSIDE focus type
    // CLASSIC_FILL, FLOATING_FILL, FLOATING_INDICATOR use fill/indicator instead of border
    // CRITICAL: Only show selected border when content has focus (!isMenuFocused)
    // When menu is focused, we show focus indicator only, no selected border
    // FLOATING_INDICATOR uses AnimatedFocusIndicator for selected state (white), so no border needed
    val showSelectedBorder = isSelected && !(isFocused && !isInStartContent) && !useClassicFill && !useFloatingFill && !useFloatingIndicator && !isMenuFocused
    val borderWidth = when {
        showOwnFocusBorder -> sx(TopMenuDesign.FOCUS_BORDER_WIDTH)  // 8px aqua for focus
        showSelectedBorder -> sx(TopMenuDesign.SELECTED_BORDER_WIDTH)  // 4px white for selected
        else -> 0.dp
    }
    val borderColor = when {
        showOwnFocusBorder -> TopMenuDesign.COLOR_FOCUS_BORDER  // Aqua
        showSelectedBorder -> TopMenuDesign.COLOR_SELECTED_BORDER  // White
        else -> Color.Transparent
    }

    // Scale animation for SCALE focus type
    val scale by animateFloatAsState(
        targetValue = if (isFocused && !isInStartContent && focusType == FocusType.SCALE) 1.15f else 1f,
        animationSpec = tween(durationMillis = 200),
        label = "button_scale"
    )

    val density = LocalDensity.current

    Box(
        modifier = Modifier
            .height(sy(TopMenuDesign.ITEM_HEIGHT))              // Figma: 80px
            .graphicsLayer(scaleX = scale, scaleY = scale)  // Scale animation for SCALE focus type
            // REMOVED: .focusGlow() - now handled by AnimatedFocusIndicator
            .background(
                color = backgroundColor,
                shape = RoundedCornerShape(sx(TopMenuDesign.ITEM_BORDER_RADIUS))  // Figma: 64px
            )
            .border(
                width = borderWidth,
                color = borderColor,
                shape = RoundedCornerShape(sx(TopMenuDesign.ITEM_BORDER_RADIUS))
            )
            .focusRequester(focusRequester)
            .focusable()
            .onFocusChanged { if (it.isFocused) onFocused() }
            .onGloballyPositioned { coords ->
                // Report bounds for AnimatedFocusIndicator
                val cornerRadiusPx = with(density) { sx(TopMenuDesign.ITEM_BORDER_RADIUS).toPx() }
                onBoundsChanged(
                    FocusableBounds(
                        x = coords.positionInRoot().x,
                        y = coords.positionInRoot().y,
                        width = coords.size.width.toFloat(),
                        height = coords.size.height.toFloat(),
                        cornerRadius = cornerRadiusPx
                    )
                )
            }
            .padding(horizontal = sx(TopMenuDesign.ITEM_PADDING_H)),  // Figma: 24px
        contentAlignment = Alignment.Center
    ) {
        // UNDERLINE focus type: use text decoration
        val showUnderline = isFocused && !isInStartContent && focusType == FocusType.UNDERLINE
        val textDecoration = if (showUnderline) TextDecoration.Underline else TextDecoration.None

        Text(
            text = title,
            color = if (showUnderline) TopMenuDesign.COLOR_FOCUS_BORDER else textColor,  // Aqua when underlined
            style = TextStyle(
                fontSize = (24 * sy(1).value / 1).sp,           // Figma: 24px
                fontWeight = FontWeight.Medium,                  // Figma: Medium (500)
                lineHeight = (32 * sy(1).value / 1).sp,          // Figma: 32px
                letterSpacing = 0.48.sp,                         // Figma: 0.48px
                textDecoration = textDecoration                   // Underline for UNDERLINE focus type
            ),
            textAlign = TextAlign.Center
        )
    }
}

@Composable
private fun FullPageContent(
    selectedSection: String,
    onReturnToMenu: () -> Unit,
    onUserNavigated: () -> Unit = {},  // NEW: Callback when user navigates (clears fresh PIP mode)
    onPrepareReturnFocus: (String) -> Unit = {},  // Set button focus state BEFORE returning to menu (prevents flash)
    shouldAutoFocus: Boolean,
    sx: (Int) -> androidx.compose.ui.unit.Dp,
    sy: (Int) -> androidx.compose.ui.unit.Dp,
    globalFocusState: MutableState<GlobalFocusState>,
    onNavigateToEpg: () -> Unit = {},
    onNavigateToEpgDay: (channelId: String, itemId: String?, scrollPosition: Int, sectionId: String) -> Unit = { _, _, _, _ -> },
    onNavigateToStartupMode: () -> Unit = {},  // Navigate to startup mode selection
    onFocusRestored: () -> Unit = {},
    restoredTelewizjaFocus: FocusState? = null,
    onNavigateToChannelGrid: (title: String, category: String, filter: ((TvChannel) -> Boolean)?, channelList: List<TvChannel>?) -> Unit = { _, _, _, _ -> },
    onNavigateToVodGrid: (title: String, prefiltered: List<VodContent>?, sourceSection: String) -> Unit = { _, _, _ -> },
    onNavigateToKinoGrid: (title: String, prefiltered: List<VodContent>?, sourceSection: String) -> Unit = { _, _, _ -> },
    onNavigateToMovieDetail: (VodSlideData) -> Unit = {},  // Navigate to MovieDetailScreen from KINO PLAY slider
    onNavigateToPurchase: (VodSlideData) -> Unit = {},  // Navigate directly to PurchaseScreen (quick mode)
    onNavigateToVodPlayer: (url: String, title: String) -> Unit = { _, _ -> },  // Navigate to VOD player with seeking
    quickPurchaseMode: Boolean = false,  // When true, skip MovieDetail and go directly to Purchase
    onNavigateToRecordingsGrid: (title: String, sourceSection: String) -> Unit = { _, _ -> },
    onNavigateToAppsGrid: () -> Unit = {},  // Navigate to grid wszystkich aplikacji (z CategoryIcon "Aplikacje")
    aplikacjeVariant: Int = 0,  // 0 = hero+channels, 1 = channels-only (Aplikacje na top)
    vodWypozyczoneVariant: Int = 1,  // 0 = above slider (TODO), 1 = below slider/above Polecane (DEFAULT)
    onProfileSelected: (UserProfile) -> Unit = {},  // Wywoływane po kliknięciu profilu w ProfileScreenContent
    isEpgSectionExpanded: Boolean = false,
    onEpgSectionExpandedChange: (Boolean) -> Unit = {},
    showNagraniaV2: Boolean = false,
    onShowNagraniaV2Change: (Boolean) -> Unit = {},
    sliderVersion: Int = 1,  // 1 = V1 with carousel, 2 = V2 with border
    v3SliderAutoSlideEnabled: Boolean = false,  // Key.Eight toggle for V3 slider auto-slide and bullets
    onFocusedChannelChange: (String) -> Unit = {},  // Callback when focused channel changes (for top gradient on Skróty+)
    onNavigateToOlympics: (content: List<VodContent>, sourceSection: String) -> Unit = { _, _ -> },  // Navigate to Olympics page
    availableUpdate: com.uxellence.tv.v3.update.AppUpdateInfo? = null,
    updateState: com.uxellence.tv.v3.update.UpdateState = com.uxellence.tv.v3.update.UpdateState.READY,
    onUpdateDownload: (com.uxellence.tv.v3.update.AppUpdateInfo) -> Unit = {},
    onUpdateInstall: () -> Unit = {},
    onDismissUpdateBadge: () -> Unit = {},
    searchKeyboardMode: Int = 0
) {
    val context = androidx.compose.ui.platform.LocalContext.current

    // Track fresh entry (transition from menu Row 0 → content Row 1+)
    // Used to auto-focus first interactive element only when user enters section, not while hovering tab
    var previousRow by remember { mutableStateOf(0) }
    val isFreshEntry = remember(globalFocusState.value.currentRow) {
        val wasFreshEntry = previousRow == 0 && globalFocusState.value.currentRow > 0
        previousRow = globalFocusState.value.currentRow
        wasFreshEntry
    }

    when (selectedSection) {
        "SEARCH" -> {
            com.uxellence.tv.v3.search.SearchScreen(
                globalFocusState = globalFocusState,
                sx = sx,
                sy = sy,
                onNavigateToMovieDetail = onNavigateToMovieDetail,
                onReturnToMenu = {
                    globalFocusState.value = GlobalFocusManager.returnToMenu(globalFocusState.value)
                },
                searchKeyboardMode = searchKeyboardMode
            )
        }
        "MOJE" -> {
            MojeScreenContent(
                globalFocusState = globalFocusState,
                onNavigateToVodGrid = onNavigateToVodGrid,
                onNavigateToKinoGrid = onNavigateToKinoGrid,
                onNavigateToRecordingsGrid = onNavigateToRecordingsGrid,
                onNavigateToMovieDetail = onNavigateToMovieDetail,
                sx = sx,
                sy = sy,
                showNagraniaV2 = showNagraniaV2,
                onShowNagraniaV2Change = onShowNagraniaV2Change,
                onFocusedChannelChange = onFocusedChannelChange
            )
        }
        "ODKRYWAJ" -> {
            OdkrywajScreenContent(
                globalFocusState = globalFocusState,
                onUserNavigated = onUserNavigated,  // Clear fresh PIP mode on navigation
                onNavigateToChannelGrid = onNavigateToChannelGrid,
                onNavigateToVodGrid = onNavigateToVodGrid,
                onNavigateToEpgDay = onNavigateToEpgDay,
                onNavigateToOlympics = onNavigateToOlympics,
                appIconsData = emptyMap(),  // TODO: Pass real appIconsData
                sx = sx,
                sy = sy,
                sliderVersion = sliderVersion,  // V3 shortcuts when sliderVersion == 2
                v3SliderAutoSlideEnabled = v3SliderAutoSlideEnabled,  // Key.Eight toggle for V3 slider
                onFocusedChannelChange = onFocusedChannelChange,
                onNavigateToVodPlayer = onNavigateToVodPlayer
            )
        }
        "TELEWIZJA" -> {
            TelewizjaScreenContent(
                globalFocusState = globalFocusState,
                sx = sx,
                sy = sy,
                onNavigateToEpg = onNavigateToEpg,
                onNavigateToEpgDay = onNavigateToEpgDay,
                onNavigateToOlympics = onNavigateToOlympics,
                onFocusRestored = onFocusRestored,
                restoredTelewizjaFocus = restoredTelewizjaFocus,
                onNavigateToChannelGrid = onNavigateToChannelGrid,
                onNavigateToVodGrid = onNavigateToVodGrid,
                onNavigateToKinoGrid = onNavigateToKinoGrid,
                onNavigateToRecordingsGrid = onNavigateToRecordingsGrid,
                isEpgSectionExpanded = isEpgSectionExpanded,
                onEpgSectionExpandedChange = onEpgSectionExpandedChange,
                onFocusedChannelChange = onFocusedChannelChange
            )
        }
        "KINO_PLAY" -> {
            VodScreenContent(
                globalFocusState = globalFocusState,
                onNavigateToVodGrid = onNavigateToVodGrid,
                onNavigateToKinoGrid = onNavigateToKinoGrid,
                onNavigateToMovieDetail = onNavigateToMovieDetail,
                onNavigateToPurchase = onNavigateToPurchase,
                onNavigateToVodPlayer = onNavigateToVodPlayer,
                quickPurchaseMode = quickPurchaseMode,
                sx = sx,
                sy = sy,
                sliderVersion = sliderVersion,
                vodWypozyczoneVariant = vodWypozyczoneVariant,
                onFocusedChannelChange = onFocusedChannelChange
            )
        }
        "WIDEO" -> {
            WideoScreenContent(
                globalFocusState = globalFocusState,
                onNavigateToVodGrid = onNavigateToVodGrid,
                sx = sx,
                sy = sy,
                sliderVersion = sliderVersion,
                onFocusedChannelChange = onFocusedChannelChange
            )
        }
        "APLIKACJE" -> {
            AplikacjeWithHeroScreen(
                globalFocusState = globalFocusState,
                sx = sx,
                sy = sy,
                onNavigateToAppsGrid = onNavigateToAppsGrid,
                aplikacjeVariant = aplikacjeVariant
            )
        }
        "ACCOUNT" -> {
            AccountScreenContent(
                globalFocusState = globalFocusState,
                onNavigateToStartupMode = onNavigateToStartupMode,
                onPrepareReturnFocus = { onPrepareReturnFocus("ACCOUNT") },
                sx = sx,
                sy = sy,
                availableUpdate = availableUpdate,
                updateState = updateState,
                onUpdateDownload = onUpdateDownload,
                onUpdateInstall = onUpdateInstall,
                onDismissUpdateBadge = onDismissUpdateBadge
            )
        }
        "POINTS_HISTORY" -> {
            PointsHistoryScreenContent(
                globalFocusState = globalFocusState,
                onPrepareReturnFocus = { onPrepareReturnFocus("POINTS_HISTORY") },
                sx = sx,
                sy = sy
            )
        }
        "START" -> {
            StartScreenContent(
                globalFocusState = globalFocusState,
                onNavigateToChannelGrid = onNavigateToChannelGrid,
                onNavigateToVodGrid = onNavigateToVodGrid,
                onNavigateToKinoGrid = onNavigateToKinoGrid,
                onNavigateToRecordingsGrid = onNavigateToRecordingsGrid,
                sx = sx,
                sy = sy,
                sliderVersion = sliderVersion
            )
        }
        "PAKIETY" -> {
            // Pakiety section placeholder - will show channel packages
            PakietyScreenContent(
                globalFocusState = globalFocusState,
                onPrepareReturnFocus = { onPrepareReturnFocus("PAKIETY") },
                sx = sx,
                sy = sy
            )
        }
        "PROFILE" -> {
            // Profile section - profile switching
            ProfileScreenContent(
                globalFocusState = globalFocusState,
                onPrepareReturnFocus = { onPrepareReturnFocus("PROFILE") },
                onProfileSelected = onProfileSelected,
                sx = sx,
                sy = sy
            )
        }
        else -> {
            Text(
                text = "$selectedSection - Section",
                color = Color.White,
                fontSize = 24.sp,
                modifier = Modifier.fillMaxSize().wrapContentSize()
            )
        }
    }
}

@Composable
private fun MojeScreenContent(
    globalFocusState: MutableState<GlobalFocusState>,
    onNavigateToVodGrid: (title: String, prefiltered: List<VodContent>?, sourceSection: String) -> Unit = { _, _, _ -> },
    onNavigateToKinoGrid: (title: String, prefiltered: List<VodContent>?, sourceSection: String) -> Unit = { _, _, _ -> },
    onNavigateToRecordingsGrid: (title: String, sourceSection: String) -> Unit = { _, _ -> },
    onNavigateToMovieDetail: (VodSlideData) -> Unit = {},  // ENTER on rented poster → MovieDetail
    sx: (Int) -> androidx.compose.ui.unit.Dp,
    sy: (Int) -> androidx.compose.ui.unit.Dp,
    showNagraniaV2: Boolean = false,
    onShowNagraniaV2Change: (Boolean) -> Unit = {},
    onFocusedChannelChange: (String) -> Unit = {}  // Callback for top gradient (MOJE always shows gradient)
) {
    var resetTrigger by remember { mutableStateOf(0) }
    
    // Detect when user returns to menu to trigger focus reset
    LaunchedEffect(globalFocusState.value.currentRow) {
        if (globalFocusState.value.currentRow == 0 && globalFocusState.value.sectionId == "MOJE") {
            resetTrigger++
        }
    }
    
    MojeChannelsScreen(
        onReturnToMenu = {
            globalFocusState.value = GlobalFocusManager.returnToMenu(globalFocusState.value)
        },
        onNavigateToVodGrid = onNavigateToVodGrid,
        onNavigateToKinoGrid = onNavigateToKinoGrid,
        onNavigateToRecordingsGrid = onNavigateToRecordingsGrid,
        onNavigateToMovieDetail = onNavigateToMovieDetail,
        shouldAutoFocus = globalFocusState.value.sectionId == "MOJE" && globalFocusState.value.currentRow > 0,
        sx = sx,
        sy = sy,
        resetTrigger = resetTrigger,
        showNagraniaV2 = showNagraniaV2,
        onShowNagraniaV2Change = onShowNagraniaV2Change,
        onFocusedChannelChange = onFocusedChannelChange
    )
}

@Composable
private fun AplikacjeScreenContent(
    globalFocusState: MutableState<GlobalFocusState>,
    onNavigateToChannelGrid: (title: String, category: String, filter: ((TvChannel) -> Boolean)?, channelList: List<TvChannel>?) -> Unit = { _, _, _, _ -> },
    onNavigateToVodGrid: (title: String, prefiltered: List<VodContent>?, sourceSection: String) -> Unit = { _, _, _ -> },
    onNavigateToKinoGrid: (title: String, prefiltered: List<VodContent>?, sourceSection: String) -> Unit = { _, _, _ -> },
    appIconsData: Map<String, List<TvChannel>> = emptyMap(),
    sx: (Int) -> androidx.compose.ui.unit.Dp,
    sy: (Int) -> androidx.compose.ui.unit.Dp
) {
    var resetTrigger by remember { mutableStateOf(0) }

    // Detect when user returns to menu to trigger focus reset
    LaunchedEffect(globalFocusState.value.currentRow) {
        if (globalFocusState.value.currentRow == 0 && globalFocusState.value.sectionId == "APLIKACJE") {
            resetTrigger++
        }
    }

    AplikacjeChannelsScreen(
        onReturnToMenu = {
            globalFocusState.value = GlobalFocusManager.returnToMenu(globalFocusState.value)
        },
        shouldAutoFocus = globalFocusState.value.sectionId == "APLIKACJE" && globalFocusState.value.currentRow > 0,
        onNavigateToChannelGrid = onNavigateToChannelGrid,
        onNavigateToVodGrid = onNavigateToVodGrid,
        onNavigateToKinoGrid = onNavigateToKinoGrid,
        appIconsData = appIconsData,
        sx = sx,
        sy = sy,
        resetTrigger = resetTrigger
    )
}

