 * ┌─────────────────────────┐
 * │     Tekst linia 1       │  ← Y: 24px, font 28px medium, centered
 * │     Tekst linia 2       │  ← line-height: 40px
 * │                         │
 * │        [LOGO]           │  ← 144×144px, centered, Y: ~128px
 * │                         │
 * └─────────────────────────┘
 */
@Composable
private fun ShortcutCardV3(
    shortcut: ShortcutItem,
    isFocused: Boolean,
    focusRequester: FocusRequester,
    onNavigateToChannelGrid: (title: String, category: String, filter: ((TvChannel) -> Boolean)?, channelList: List<TvChannel>?) -> Unit = { _, _, _, _ -> },
    onNavigateToVodGrid: (title: String, prefiltered: List<VodContent>?, sourceSection: String) -> Unit = { _, _, _ -> },
    onNavigateToKinoGrid: (title: String, prefiltered: List<VodContent>?, sourceSection: String) -> Unit = { _, _, _ -> },
    onNavigateToRecordingsGrid: (title: String, sourceSection: String) -> Unit = { _, _ -> },
    onNavigateToEpgDay: (channelId: String, itemId: String?, scrollPosition: Int, sectionId: String) -> Unit = { _, _, _, _ -> },
    appIconsData: Map<String, List<TvChannel>> = emptyMap(),
    sx: (Int) -> androidx.compose.ui.unit.Dp,
    sy: (Int) -> androidx.compose.ui.unit.Dp,
    onFocusChange: (Boolean) -> Unit
) {
    val cardWidth = sx(300)
    val cardHeight = sy(314)
    val borderColor = if (isFocused) Color(0xFF5FEDD4) else Color.Transparent  // V3: #5FEDD4 aqua

    Box(
        modifier = Modifier
            .width(cardWidth)
            .height(cardHeight)
            .border(
                width = sx(4),  // V3: 4px border
                color = borderColor,
                shape = RoundedCornerShape(sx(16))  // V3: 16px border radius
            )
            .clip(RoundedCornerShape(sx(16)))
            .background(Color(0x33000000))  // V3: rgba(0,0,0,0.2)
            .focusRequester(focusRequester)
            .onPreviewKeyEvent { event ->
                if (event.type == KeyEventType.KeyDown &&
                    (event.key == Key.Enter || event.key == Key.DirectionCenter)) {
                    android.util.Log.d("SHORTCUT_V3", "=== Enter/OK pressed for: ${shortcut.title} ===")
                    // Extract plain title (without newlines) for navigation
                    val plainTitle = shortcut.title.replace("\n", " ")
                    when {
                        plainTitle.contains("telewizję", ignoreCase = true) -> {
                            android.util.Log.d("SHORTCUT_V3", "Nawigacja do EpgDay - Oglądaj telewizję")
                            onNavigateToEpgDay("", null, 0, "ODKRYWAJ")
                        }
                        plainTitle.contains("lista kanałów", ignoreCase = true) -> {
                            android.util.Log.d("SHORTCUT_V3", "Nawigacja do ChannelGrid - Moja lista kanałów")
                            onNavigateToChannelGrid(
                                "Moja lista kanałów",
                                "Wszystkie",
                                null,
                                appIconsData["Moja lista kanałów"]
                            )
                        }
                        plainTitle.contains("Nagrania", ignoreCase = true) -> {
                            android.util.Log.d("SHORTCUT_V3", "Nawigacja do RecordingsGrid - Nagrania")
                            onNavigateToRecordingsGrid("Zarządzaj nagraniami", "ODKRYWAJ")
                        }
                        plainTitle.contains("Wypożyczone", ignoreCase = true) -> {
                            android.util.Log.d("SHORTCUT_V3", "Nawigacja do KinoGrid - Wypożyczone")
                            val kinoList = VodDataCache.getKinoPlayMovies()
                            val randomMovies = kinoList.shuffled().take(2)
                            onNavigateToKinoGrid("Wypożyczone", randomMovies, "ODKRYWAJ")
                        }
                        plainTitle.contains("obejrzenia", ignoreCase = true) -> {
                            android.util.Log.d("SHORTCUT_V3", "Nawigacja do VodGrid - Do obejrzenia")
                            val vodList = VodDataCache.getVodContentList()
                            val randomFilms = vodList.shuffled().take(20)
                            onNavigateToVodGrid("Do obejrzenia", randomFilms, "ODKRYWAJ")
                        }
                    }
                    true
                } else {
                    false
                }
            }
            .focusable()
            .clickable {
                android.util.Log.d("SHORTCUT_V3", "=== clickable triggered for: ${shortcut.title} ===")
                val plainTitle = shortcut.title.replace("\n", " ")
                when {
                    plainTitle.contains("telewizję", ignoreCase = true) -> {
                        android.util.Log.d("SHORTCUT_V3", "Nawigacja do EpgDay - Oglądaj telewizję")
                        onNavigateToEpgDay("", null, 0, "ODKRYWAJ")
                    }
                    plainTitle.contains("lista kanałów", ignoreCase = true) -> {
                        onNavigateToChannelGrid(
                            "Moja lista kanałów",
                            "Wszystkie",
                            null,
                            appIconsData["Moja lista kanałów"]
                        )
                    }
                    plainTitle.contains("Nagrania", ignoreCase = true) -> {
                        onNavigateToRecordingsGrid("Zarządzaj nagraniami", "ODKRYWAJ")
                    }
                    plainTitle.contains("Wypożyczone", ignoreCase = true) -> {
                        val kinoList = VodDataCache.getKinoPlayMovies()
                        val randomMovies = kinoList.shuffled().take(2)
                        onNavigateToKinoGrid("Wypożyczone", randomMovies, "ODKRYWAJ")
                    }
                    plainTitle.contains("obejrzenia", ignoreCase = true) -> {
                        val vodList = VodDataCache.getVodContentList()
                        val randomFilms = vodList.shuffled().take(20)
                        onNavigateToVodGrid("Do obejrzenia", randomFilms, "ODKRYWAJ")
                    }
                }
            }
            .onFocusChanged { focusState ->
                onFocusChange(focusState.isFocused)
            }
    ) {
        Box(
            modifier = Modifier
                .fillMaxSize()
                .background(
                    if (isFocused) Color(0x4D000000) else Color.Transparent
                )
        ) {
            // Text at top (can be 2 lines)
            Text(
                text = shortcut.title,
                color = Color(0xFFEEEEEE),
                fontSize = (28 * sx(1).value / 1.dp.value).sp,  // V3: 28px font
                fontWeight = FontWeight.Medium,
                textAlign = TextAlign.Center,
                lineHeight = (40 * sy(1).value / 1.dp.value).sp,  // V3: 40px line-height
                maxLines = 2,
                modifier = Modifier
                    .align(Alignment.TopCenter)
                    .padding(top = sy(24))
                    .width(sx(268))  // Padding from edges
            )

            // Logo/icon centered in lower area (Y: ~128px from top)
            Box(
                modifier = Modifier
                    .align(Alignment.TopCenter)
                    .padding(top = sy(78))
                    .size(sx(144))  // V3: 144×144px logo
            ) {
                when (shortcut.icon) {
                    is ShortcutIcon.VectorIcon -> {
                        // Use Image without tint for PNG icons (full color)
                        Image(
                            painter = painterResource(shortcut.icon.iconRes),
                            contentDescription = shortcut.title,
                            modifier = Modifier.fillMaxSize(),
                            contentScale = ContentScale.Fit
                        )
                    }
                    is ShortcutIcon.LottieIcon -> {
                        val composition by rememberLottieComposition(LottieCompositionSpec.Asset(shortcut.icon.fileName))
                        val progress by animateLottieCompositionAsState(
                            composition = composition,
                            isPlaying = isFocused,
                            restartOnPlay = true,
                            iterations = if (isFocused) 1 else 1
                        )

                        LottieAnimation(
                            composition = composition,
                            progress = { if (isFocused) progress else 1f },
                            modifier = Modifier.fillMaxSize()
                        )
                    }
                    is ShortcutIcon.MaterialIcon -> {
                        val materialIcon = when (shortcut.icon.iconName) {
                            "add" -> Icons.Default.Add
                            "star" -> Icons.Default.Star
                            "search" -> Icons.Default.Search
                            "person" -> Icons.Default.Person
                            "settings" -> Icons.Default.Settings
                            "video_library" -> Icons.Default.PlayArrow
                            "live_tv" -> Icons.Default.PlayArrow  // Using PlayArrow as fallback for live_tv
                            "schedule" -> Icons.Default.DateRange  // Using DateRange as fallback for schedule
                            "favorite" -> Icons.Default.Star  // Using Star as fallback for favorite
                            else -> Icons.Default.Star
                        }
                        Icon(
                            imageVector = materialIcon,
                            contentDescription = shortcut.title,
                            modifier = Modifier.fillMaxSize(),
                            tint = Color(0xFFEEEEEE)
                        )
                    }
                }
            }
        }
    }
}

/**
 * ShortcutCardV4 - Quick link card from Figma design (222×244px)
 * Design: Icon at TOP (96px), text at BOTTOM (max 2 lines)
 * Used in ODKRYWAJ section when sliderVersion == 3
 *
 * Layout:
 * ┌─────────────────────────┐
 * │      padding 32px       │
 * │    ┌──────────────┐     │
 * │    │   Icon 96px  │     │
 * │    └──────────────┘     │
 * │       gap 24px          │
 * │    Text (max 2 lines)   │
 * │      padding 40px       │
 * └─────────────────────────┘
 */
@Composable
private fun ShortcutCardV4(
    shortcut: ShortcutItem,
    isFocused: Boolean,
    focusRequester: FocusRequester,
    onNavigateToChannelGrid: (title: String, category: String, filter: ((TvChannel) -> Boolean)?, channelList: List<TvChannel>?) -> Unit = { _, _, _, _ -> },
    onNavigateToVodGrid: (title: String, prefiltered: List<VodContent>?, sourceSection: String) -> Unit = { _, _, _ -> },
    onNavigateToKinoGrid: (title: String, prefiltered: List<VodContent>?, sourceSection: String) -> Unit = { _, _, _ -> },
    onNavigateToRecordingsGrid: (title: String, sourceSection: String) -> Unit = { _, _ -> },
    onNavigateToEpgDay: (channelId: String, itemId: String?, scrollPosition: Int, sectionId: String) -> Unit = { _, _, _, _ -> },
    onNavigateToOlympics: () -> Unit = { },
    onToggleMyList: () -> Unit = { },  // NEW: Callback for "Utwórz/Edytuj Moją listę kanałów"
    appIconsData: Map<String, List<TvChannel>> = emptyMap(),
    sx: (Int) -> androidx.compose.ui.unit.Dp,
    sy: (Int) -> androidx.compose.ui.unit.Dp,
    onFocusChange: (Boolean) -> Unit
) {
    // Figma specs: 222x244px card
    val cardWidth = sx(222)
    val cardHeight = sy(244)

    // Border: 8px aqua when focused, 2px gray when not
    val borderWidth = if (isFocused) sx(8) else sx(2)
    val borderColor = if (isFocused) Color(0xFF5FEDD4) else Color(0x33EEEEEE) // 20% white

    Box(
        modifier = Modifier
            .width(cardWidth)
            .height(cardHeight)
            .border(
                width = borderWidth,
                color = borderColor,
                shape = RoundedCornerShape(sx(16))
            )
            .clip(RoundedCornerShape(sx(16)))
            .background(Color(0x66000000)) // 40% black
            .focusRequester(focusRequester)
            .onPreviewKeyEvent { event ->
                if (event.type == KeyEventType.KeyDown &&
                    (event.key == Key.Enter || event.key == Key.DirectionCenter)) {
                    android.util.Log.d("SHORTCUT_V4", "=== Enter/OK pressed for: ${shortcut.title} ===")
                    val plainTitle = shortcut.title.replace("\n", " ")
                    when {
                        // TELEWIZJA: Program telewizyjny -> EPG
                        plainTitle.contains("Program", ignoreCase = true) && plainTitle.contains("telewizyjny", ignoreCase = true) -> {
                            android.util.Log.d("SHORTCUT_V4", "Nawigacja do EpgDay - Program telewizyjny")
                            onNavigateToEpgDay("", null, 0, "TELEWIZJA")
                        }
                        // ODKRYWAJ: Oglądaj telewizję -> EPG
                        plainTitle.contains("telewizję", ignoreCase = true) -> {
                            android.util.Log.d("SHORTCUT_V4", "Nawigacja do EpgDay - Oglądaj telewizję")
                            onNavigateToEpgDay("", null, 0, "ODKRYWAJ")
                        }
                        // TELEWIZJA: Widok listy kanałów -> Lista kanałów
                        plainTitle.contains("Widok listy", ignoreCase = true) -> {
                            android.util.Log.d("SHORTCUT_V4", "Nawigacja do listy kanałów")
                            onNavigateToChannelGrid(
                                "Lista kanałów TV",
                                "Wszystkie",
                                null,
                                appIconsData["Wszystkie kanały"]
                            )
                        }
                        // Nagrania
                        plainTitle.contains("Nagrania", ignoreCase = true) -> {
                            onNavigateToRecordingsGrid("Zarządzaj nagraniami", "TELEWIZJA")
                        }
                        // TELEWIZJA: Pakiety telewizyjne
                        plainTitle.contains("Pakiety", ignoreCase = true) && plainTitle.contains("telewizyjne", ignoreCase = true) -> {
                            android.util.Log.d("SHORTCUT_V4", "Nawigacja do pakietów TV")
                            // TODO: Navigate to TV packages screen
                        }
                        // Utwórz/Edytuj Moją listę kanałów (toggle state)
                        plainTitle.contains("listę kanałów", ignoreCase = true) &&
                        (plainTitle.contains("Utwórz", ignoreCase = true) || plainTitle.contains("Edytuj", ignoreCase = true)) -> {
                            android.util.Log.d("SHORTCUT_V4", "Toggle My List clicked: $plainTitle")
                            onToggleMyList()
                        }
                        // Moja lista kanałów (navigate to channel grid)
                        plainTitle.contains("lista kanałów", ignoreCase = true) -> {
                            onNavigateToChannelGrid(
                                "Moja lista kanałów",
                                "Wszystkie",
                                null,
                                appIconsData["Moja lista kanałów"]
                            )
                        }
                        // Do obejrzenia
                        plainTitle.contains("obejrzenia", ignoreCase = true) -> {
                            val vodList = VodDataCache.getVodContentList()
                            val randomFilms = vodList.shuffled().take(20)
                            onNavigateToVodGrid("Do obejrzenia", randomFilms, "ODKRYWAJ")
                        }
                        // Netflix
                        plainTitle.contains("Netflix", ignoreCase = true) -> {
                            android.util.Log.d("SHORTCUT_V4", "Launching Netflix...")
                        }
                        // Disney+
                        plainTitle.contains("Disney", ignoreCase = true) -> {
                            android.util.Log.d("SHORTCUT_V4", "Launching Disney+...")
                        }
                        // Igrzyska Olimpijskie
                        plainTitle.contains("Igrzyska", ignoreCase = true) ||
                        plainTitle.contains("Olimpijskie", ignoreCase = true) ||
                        plainTitle.contains("Olimpiada", ignoreCase = true) ||
                        plainTitle.contains("zimowa", ignoreCase = true) -> {
                            android.util.Log.d("SHORTCUT_V4", "Navigating to Olympics page...")
                            onNavigateToOlympics()
                        }
                        // Polsat Viasat Nature
                        plainTitle.contains("Viasat", ignoreCase = true) ||
                        plainTitle.contains("Nature", ignoreCase = true) -> {
                            android.util.Log.d("SHORTCUT_V4", "Navigating to Viasat Nature channel...")
                            // TODO: Navigate to Viasat Nature channel
                        }
                    }
                    true
                } else {
                    false
                }
            }
            .focusable()
            .onFocusChanged { focusState ->
                onFocusChange(focusState.isFocused)
            }
    ) {
        // Check if this is Polsat Viasat Nature - show "Nowy kanał" label
        val showNowyKanalLabel = shortcut.title.contains("Viasat", ignoreCase = true) ||
                                  shortcut.title.contains("Nature", ignoreCase = true)

        Column(
            modifier = Modifier
                .fillMaxSize()
                .padding(
                    top = if (showNowyKanalLabel) sy(32) else sy(24), // Extra top padding when label present
                    bottom = sy(16),
                    start = sx(12),
                    end = sx(12)
                ),
            horizontalAlignment = Alignment.CenterHorizontally,
            verticalArrangement = Arrangement.SpaceBetween
        ) {
            // Icon (96x96px)
            Box(
                modifier = Modifier.size(sx(96)),
                contentAlignment = Alignment.Center
            ) {
                when (shortcut.icon) {
                    is ShortcutIcon.VectorIcon -> {
                        Image(
                            painter = painterResource(shortcut.icon.iconRes),
                            contentDescription = shortcut.title,
                            modifier = Modifier.fillMaxSize(),
                            contentScale = ContentScale.Fit
                        )
                    }
                    is ShortcutIcon.LottieIcon -> {
                        val composition by rememberLottieComposition(LottieCompositionSpec.Asset(shortcut.icon.fileName))
                        val progress by animateLottieCompositionAsState(
                            composition = composition,
                            isPlaying = isFocused,
                            restartOnPlay = true,
                            iterations = 1
                        )

                        LottieAnimation(
                            composition = composition,
                            progress = { if (isFocused) progress else 1f },
                            modifier = Modifier.fillMaxSize()
                        )
                    }
                    is ShortcutIcon.MaterialIcon -> {
                        val materialIcon = when (shortcut.icon.iconName) {
                            "add" -> Icons.Default.Add
                            "star" -> Icons.Default.Star
                            "search" -> Icons.Default.Search
                            "person" -> Icons.Default.Person
                            "settings" -> Icons.Default.Settings
                            else -> Icons.Default.Star
                        }
                        Icon(
                            imageVector = materialIcon,
                            contentDescription = shortcut.title,
                            modifier = Modifier.fillMaxSize(),
                            tint = Color(0xFFEEEEEE)
                        )
                    }
                }
            }

            // Text (24sp, max 2 lines, centered horizontally, aligned to TOP)
            // Fixed height for 2 lines so all texts start at same Y position
            Box(
                modifier = Modifier
                    .fillMaxWidth()
                    .height(sy(64)), // Height for 2 lines (32sp line height × 2)
                contentAlignment = Alignment.TopCenter // Align text to top
            ) {
                Text(
                    text = shortcut.title,
                    color = Color(0xFFEEEEEE),
                    fontSize = (24 * sx(1).value / 1.dp.value).sp,
                    fontWeight = FontWeight.Medium,
                    textAlign = TextAlign.Center,
                    lineHeight = (32 * sy(1).value / 1.dp.value).sp,
                    maxLines = 2,
                    overflow = TextOverflow.Visible,
                    letterSpacing = 0.48.sp
                )
            }
        }

        // "Nowy kanał" label - full width at top (only for Polsat Viasat Nature)
        if (showNowyKanalLabel) {
            Box(
                modifier = Modifier
                    .align(Alignment.TopCenter)
                    .fillMaxWidth()
                    .background(
                        color = Color(0xFF5F2DA4), // Purple background
                        shape = RoundedCornerShape(
                            topStart = sx(16),
                            topEnd = sx(16),
                            bottomStart = 0.dp,
                            bottomEnd = 0.dp
                        )
                    )
                    .padding(vertical = sy(4)),
                contentAlignment = Alignment.Center
            ) {
                Text(
                    text = "Nowy kanał",
                    color = Color(0xFFEEEEEE),
                    fontSize = (14 * sx(1).value / 1.dp.value).sp,
                    fontWeight = FontWeight.Medium,
                    letterSpacing = 0.7.sp,
                    lineHeight = (16 * sy(1).value / 1.dp.value).sp
                )
            }
        }
    }
}

/**
 * ShortcutAddButtonV3 - Plus button for V3 shortcuts row (matching 300×314px height)
 */
@Composable
private fun ShortcutAddButtonV3(
    isFocused: Boolean,
    focusRequester: FocusRequester,
    onFocusChange: (Boolean) -> Unit,
    sx: (Int) -> androidx.compose.ui.unit.Dp,
    sy: (Int) -> androidx.compose.ui.unit.Dp
) {
    val cardWidth = sx(300)  // Match V3 card width
    val cardHeight = sy(314)  // Match V3 card height

    // Container Box (transparent, no border, no background)
    Box(
        modifier = Modifier
            .width(cardWidth)
            .height(cardHeight)
    ) {
        // Plus icon in circle (centered) - ONLY THIS is focusable
        Box(
            modifier = Modifier
                .align(Alignment.Center)
                .size(sx(144), sy(144))  // Bigger circle for V3
                .background(
                    color = if (isFocused) Color(0xFF5FEDD4) else Color(0x1AEEEEEE),
                    shape = CircleShape
                )
                .focusRequester(focusRequester)
                .focusable()
                .onFocusChanged { focusState ->
                    onFocusChange(focusState.isFocused)
                },
            contentAlignment = Alignment.Center
        ) {
            Icon(
                imageVector = Icons.Default.Add,
                contentDescription = "Add Shortcut",
                tint = if (isFocused) Color(0xFF48227C) else Color(0xFFEEEEEE),
                modifier = Modifier.size(sx(72), sy(72))  // Bigger icon for V3
            )
        }
    }
}

