// Pre-computed lowercase HashSets — O(1) lookup zamiast O(n) iteration przez listę
private val POLISH_TITLES_SET = POLISH_TITLES.map { it.trim().lowercase() }.toHashSet()
private val UNIVERSAL_TITLES_SET = UNIVERSAL_TITLES.map { it.trim().lowercase() }.toHashSet()
private val DISNEY_TITLES_SET = DISNEY_TITLES.map { it.trim().lowercase() }.toHashSet()
private val WARNER_BROS_TITLES_SET = WARNER_BROS_TITLES.map { it.trim().lowercase() }.toHashSet()
private val SONY_PICTURES_TITLES_SET = SONY_PICTURES_TITLES.map { it.trim().lowercase() }.toHashSet()

/** Helper: O(1) lookup w pre-computed HashSet (lowercase). */
private fun matchesAnyTitle(movieTitle: String, targetsSet: Set<String>): Boolean =
    movieTitle.trim().lowercase() in targetsSet

/** Legacy overload (List) — utrzymane dla kompatybilności, ale zalecane: użyj wersji z Set. */
@Suppress("unused")
private fun matchesAnyTitle(movieTitle: String, targets: List<String>): Boolean {
    val trimmed = movieTitle.trim()
    return targets.any { it.trim().equals(trimmed, ignoreCase = true) }
}

/**
 * Filter movies by category supporting multiple category names (e.g., "Akcja|Action")
 */
private fun filterMoviesByCategory(movies: List<VodContent>, categoryFilter: String): List<VodContent> {
    val categories = categoryFilter.split("|").map { it.lowercase().trim() }
    return movies.filter { movie ->
        categories.any { category ->
            movie.category.lowercase().contains(category)
        }
    } // Returns all matching movies (full catalog for KinoGridScreen)
}

@OptIn(ExperimentalComposeUiApi::class)
@Composable
private fun VodWithChannels(
    onReturnToMenu: () -> Unit = {},
    shouldAutoFocus: Boolean = false,
    onNavigateToVodGrid: (title: String, prefiltered: List<VodContent>?, sourceSection: String) -> Unit = { _, _, _ -> },
    onNavigateToKinoGrid: (title: String, prefiltered: List<VodContent>?, sourceSection: String) -> Unit = { _, _, _ -> },
    onNavigateToMovieDetail: (VodSlideData) -> Unit = {},  // Navigate to MovieDetailScreen from KINO PLAY slider
    onNavigateToPurchase: (VodSlideData) -> Unit = {},  // Navigate directly to PurchaseScreen (quick mode)
    onNavigateToVodPlayer: (url: String, title: String) -> Unit = { _, _ -> },  // Navigate to VOD player
    quickPurchaseMode: Boolean = false,  // When true, skip MovieDetail and go directly to Purchase
    sx: (Int) -> androidx.compose.ui.unit.Dp,
    sy: (Int) -> androidx.compose.ui.unit.Dp,
    resetTrigger: Int = 0,
    globalFocusState: MutableState<GlobalFocusState>,
    sliderVersion: Int = 1,
    vodWypozyczoneVariant: Int = 1,  // 0 = above slider (TODO), 1 = below slider/above Polecane (DEFAULT)
    onFocusedChannelChange: (String) -> Unit = {}  // Callback for top gradient
) {
    val context = LocalContext.current
    // Figma "Sekcje redakcyjne" — 26 channels w nowej kolejności.
    // "Wypożyczone Kino" jest dynamicznie wstawiany jako pierwszy channel gdy użytkownik
    // ma wypożyczone filmy AND vodWypozyczoneVariant != skip (read RentalManager state).
    val rentalsSnapshot = com.uxellence.tv.v3.rental.RentalManager.rentals.value
    val hasRentals = rentalsSnapshot.values.any { it > System.currentTimeMillis() }
    val channels = remember(hasRentals, vodWypozyczoneVariant) {
        val base = listOf(
            "Polecane",
            "Top 10",
            "Wszystkie",                          // CategoryIcon (no icon) + chipy 0..10
            "Ostatnio dodane",
            "Jason Statham",
            "Obcy kontra Predator",
            "Polskie filmy",
            "Polskie komedie",
            "Universal",
            "Disney",
            "Warner Bros",
            "Sony Pictures",
            "MAGICZNY ŚWIAT HARRY'EGO POTTERA",
            "GWIEZDNE WOJNY",
            "SCI-FI",
            "ROMANS",
            "KOMEDIA ROMANTYCZNA",
            "NA POPRAWĘ HUMORU",
            "FAMILIJNE",
            "ANIMOWANE",
            "PORUSZAJĄCE HISTORIE",
            "FILMY GROZY",
            "DRESZCZOWCE",
            "HISTORIE NA FAKTACH",
            "DOKUMENT",
            "Więcej"                              // ENTER → grid wszystkich filmów
        )
        if (hasRentals) listOf("Wypożyczone Kino") + base else base
    }

    // V1 layout (Wypożyczone above slider) is only meaningful when there ARE rentals;
    // otherwise the channel doesn't exist and the layout collapses to V2.
    val isV1 = vodWypozyczoneVariant == 0 && hasRentals
    // In V1 the slider is pushed down by one row so Wypożyczone Kino can sit above it.
    val sliderRowIndex = if (isV1) 2 else 1

    // State to track Supabase initialization for recomposition
    var supabaseInitialized by remember { mutableStateOf(VodDataCache.isSupabaseInitialized()) }

    // Initialize Supabase data when VOD section is loaded
    LaunchedEffect(Unit) {
        if (!VodDataCache.isSupabaseInitialized()) {
            VodDataCache.initializeFromSupabase(context)
            supabaseInitialized = VodDataCache.isSupabaseInitialized()
        }
    }

    // Grid content — zbudowane jednym przejściem przez listę filmów na background thread.
    // Każdy film klasyfikowany do wszystkich pasujących channels w jednym lookup'ie.
    // Optymalizacja: O(N filmów) zamiast O(N × 26 channels). Plus async (Dispatchers.Default)
    // żeby nie blokować main thread podczas pierwszego renderu Kino Play.
    // Re-build whenever rentals change so "Wypożyczone Kino" channel reflects new
    // rentals immediately (without leaving and returning to KINO_PLAY tab).
    val gridContent by produceState<Map<String, List<VodContent>>>(
        initialValue = emptyMap(),
        supabaseInitialized,
        rentalsSnapshot
    ) {
        value = withContext(kotlinx.coroutines.Dispatchers.Default) {
            val allMovies = VodDataCache.getKinoPlayMovies()
            val byChannel = LinkedHashMap<String, MutableList<VodContent>>()
            channels.forEach { byChannel[it] = mutableListOf() }

            // Pre-fetched curated lists (już zoptymalizowane w VodDataCache)
            byChannel["Polecane"]?.addAll(VodDataCache.getNewest())
            byChannel["Top 10"]?.addAll(VodDataCache.getTop10())
            byChannel["Ostatnio dodane"]?.addAll(VodDataCache.getNewest())

            // "Wypożyczone Kino" — populated from RentalManager (only present in `channels`
            // when the user has active rentals; otherwise the key doesn't exist in byChannel).
            val rentedTitles = com.uxellence.tv.v3.rental.RentalManager.rentedMovieIds().toSet()
            if (rentedTitles.isNotEmpty()) {
                byChannel["Wypożyczone Kino"]?.addAll(allMovies.filter { it.title in rentedTitles })
            }

            // Single-pass classification — każdy film przeglądany RAZ, klasyfikowany do wielu channels
            allMovies.forEach { movie ->
                val titleLower = movie.title.trim().lowercase()
                val titleRaw = movie.title  // dla contains (Harry Potter, Gwiezdne wojny, Obcy/Predator)
                val genreLower = movie.category.lowercase()
                val isPolish = titleLower in POLISH_TITLES_SET

                // Title-based curated lists (HashSet O(1) lookup)
                if (isPolish) byChannel["Polskie filmy"]?.add(movie)
                if (isPolish && genreLower.contains("komedia")) byChannel["Polskie komedie"]?.add(movie)
                if (titleLower in UNIVERSAL_TITLES_SET) byChannel["Universal"]?.add(movie)
                if (titleLower in DISNEY_TITLES_SET) byChannel["Disney"]?.add(movie)
                if (titleLower in WARNER_BROS_TITLES_SET) byChannel["Warner Bros"]?.add(movie)
                if (titleLower in SONY_PICTURES_TITLES_SET) byChannel["Sony Pictures"]?.add(movie)

                // Title contains (franchise/saga)
                if (titleRaw.contains("Harry Potter", ignoreCase = true) ||
                    titleRaw.contains("Fantastyczne zwierzęta", ignoreCase = true))
                    byChannel["MAGICZNY ŚWIAT HARRY'EGO POTTERA"]?.add(movie)
                if (titleRaw.contains("Gwiezdne wojny", ignoreCase = true))
                    byChannel["GWIEZDNE WOJNY"]?.add(movie)
                if (titleRaw.contains("Obcy", ignoreCase = true) || titleRaw.contains("Predator", ignoreCase = true))
                    byChannel["Obcy kontra Predator"]?.add(movie)

                // Jason Statham — cast field + title fallbacks
                if (movie.cast?.contains("Statham", ignoreCase = true) == true ||
                    movie.description.contains("Statham", ignoreCase = true) ||
                    titleRaw.contains("Niezniszczalni", ignoreCase = true) ||
                    titleRaw.contains("Pszczelarz", ignoreCase = true) ||
                    titleRaw.contains("Transporter", ignoreCase = true))
                    byChannel["Jason Statham"]?.add(movie)

                // Genre-based filters (raw contains — szybkie dla single keyword)
                if (genreLower.contains("sci-fi") || genreLower.contains("science fiction"))
                    byChannel["SCI-FI"]?.add(movie)
                if (genreLower.contains("romans") || genreLower.contains("romance"))
                    byChannel["ROMANS"]?.add(movie)
                if (genreLower.contains("romantic") || genreLower.contains("romance") || genreLower.contains("komedia"))
                    byChannel["KOMEDIA ROMANTYCZNA"]?.add(movie)
                if (genreLower.contains("komedia") || genreLower.contains("comedy"))
                    byChannel["NA POPRAWĘ HUMORU"]?.add(movie)
                if (genreLower.contains("familijny") || genreLower.contains("family"))
                    byChannel["FAMILIJNE"]?.add(movie)
                if (genreLower.contains("animacja") || genreLower.contains("animation"))
                    byChannel["ANIMOWANE"]?.add(movie)
                if (genreLower.contains("dramat") || genreLower.contains("drama"))
                    byChannel["PORUSZAJĄCE HISTORIE"]?.add(movie)
                if (genreLower.contains("horror"))
                    byChannel["FILMY GROZY"]?.add(movie)
                if (genreLower.contains("thriller") || genreLower.contains("suspense"))
                    byChannel["DRESZCZOWCE"]?.add(movie)
                if (genreLower.contains("biograficzny") || genreLower.contains("biography") || genreLower.contains("historical"))
                    byChannel["HISTORIE NA FAKTACH"]?.add(movie)
                if (genreLower.contains("dokumentalny") || genreLower.contains("documentary"))
                    byChannel["DOKUMENT"]?.add(movie)
            }

            byChannel
        }
    }

    // Expose grid content to VodDataCache so KinoGridScreen can offer the same
    // collections (Gwiezdne Wojny, Harry Potter, Disney, ...) as filterable categories.
    LaunchedEffect(gridContent) {
        if (gridContent.isNotEmpty()) {
            VodDataCache.kinoChannelMap = gridContent
        }
    }

    // Row 0 = menu, Row 1 = slider, Row 2+ = channels.
    // Restore previously-saved focus when returning from MovieDetail (consumed once).
    // For regular channels we only restore the CHANNEL (focusedColIndex=0) — exact-poster
    // restore turned out to fight too many internal mechanisms (LazyRow lazy composition,
    // miniaturesYOffset 350ms animation, transient FocusRequester rebinding) and made
    // navigation unstable. For "Wszystkie" we restore col directly (it has stable FRs 0..10).
    val initialFocusRestore = remember { VodDataCache.savedKinoPlayFocus.also { VodDataCache.savedKinoPlayFocus = null } }
    var focusedRowIndex by remember { mutableStateOf(initialFocusRestore?.row ?: 1) }
    var focusedColIndex by remember { mutableStateOf(initialFocusRestore?.col ?: -2) }

    // V4 slider button index (0 = Wypożycz, 1 = Dowiedz się więcej)
    var v4ButtonIndex by remember { mutableStateOf(0) }

    // Reset focus state when returning to menu (like MOJE)
    LaunchedEffect(resetTrigger) {
        if (resetTrigger > 0) {
            focusedRowIndex = 1 // Back to slider
            focusedColIndex = -2
        }
    }

    // Notify parent when focused row changes (for top gradient visibility)
    LaunchedEffect(focusedRowIndex) {
        val showGradient = focusedRowIndex > sliderRowIndex
        onFocusedChannelChange(if (showGradient) "SHOW_GRADIENT" else "")
    }

    val channelFocusRequesters = remember(channels.size, sliderRowIndex) {
        mutableMapOf<Pair<Int, Int>, FocusRequester>().apply {
            repeat(channels.size) { rowIndex ->
                // Match VodChannelRows row mapping (slider sits at sliderRowIndex):
                //   V2 (sliderRowIndex=1): channelIndex N → actualRowIndex N+2
                //   V1 (sliderRowIndex=2): channelIndex 0 → row 1, channelIndex 1+ → row N+2
                val adjustedRowIndex = if (sliderRowIndex == 2 && rowIndex == 0) 1 else rowIndex + 2
                val channelName = channels[rowIndex]

                when (channelName) {
                    "Wszystkie" -> {
                        // Wszystkie: same chipy 0..10 (NO CategoryIcon, jak poprzednie Skróty v3)
                        repeat(11) { colIndex ->
                            put(Pair(adjustedRowIndex, colIndex), FocusRequester())
                        }
                    }
                    "Więcej" -> {
                        // Więcej: tylko CategoryIcon (ENTER → grid wszystkich)
                        put(Pair(adjustedRowIndex, -1), FocusRequester())
                    }
                    else -> {
                        // Regular channels: CategoryIcon + content
                        put(Pair(adjustedRowIndex, -1), FocusRequester())
                        put(Pair(adjustedRowIndex, 0), FocusRequester())
                    }
                }
            }
        }
    }

    val lazyListStates = remember(channels.size) {
        mutableMapOf<Int, LazyListState>().apply {
            repeat(channels.size) { rowIndex ->
                put(rowIndex, LazyListState())
            }
        }
    }

    val coroutineScope = rememberCoroutineScope()
    var isInitialized by remember { mutableStateOf(false) }

    // Track whether we already consumed the restored focus, so the shouldAutoFocus effect
    // (which can fire AGAIN later when currentRow flips 0→>0) doesn't reset us back to slider.
    var hasRestoredKinoPlayFocus by remember { mutableStateOf(false) }

    // One-shot restoration when returning from MovieDetail.
    // focusedRowIndex/focusedColIndex are seeded from frame 1 above. Here we just push
    // currentRow > 0 into the parent globalFocusState (so the menu's currentRow==0 effect
    // doesn't hijack focus to the menu tab) and request focus once the item is laid out.
    //
    // Defensive guard: skip when the user is on the top menu (currentRow == 0). Without
    // this, a stale `savedKinoPlayFocus` (e.g., user previously rented from Kino Play,
    // navigated away, came back via top menu) would wake restoration and steal focus
    // from the highlighted tab.
    LaunchedEffect(Unit) {
        if (initialFocusRestore != null && globalFocusState.value.currentRow > 0) {
            globalFocusState.value = globalFocusState.value.copy(currentRow = focusedRowIndex)
            kotlinx.coroutines.delay(150) // let LazyRow attach modifiers
            val target = Pair(focusedRowIndex, focusedColIndex)
            val requester = channelFocusRequesters[target]
                ?: channelFocusRequesters[Pair(focusedRowIndex, 0)]
            try { requester?.requestFocus() } catch (_: Exception) {}
            hasRestoredKinoPlayFocus = true
        }
        isInitialized = true
    }

    // Outer-Box FocusRequester — needs to be declared before the LaunchedEffect that
    // uses it (Kotlin local vals don't have forward references). Bound at the Box modifier
    // chain below.
    val rootBoxFocusRequester = remember { FocusRequester() }

    // OVERLAY-MODE refocus: fired by MainActivity when MovieDetail closes back onto a
    // still-mounted KINO_PLAY tab. focusedRowIndex/focusedColIndex AND lazyListStates
    // (=channel scroll positions) are still intact — what we lost is Compose's actual
    // keyboard-focus owner (MovieDetail captured it). Instead of trying to re-target a
    // specific LazyRow item (which may be off-screen / unmounted after scroll), we just
    // refocus the outer Box. Box.onPreviewKeyEvent (handleVodNavigation) then gets keys
    // again, and the visual focus indicator on the saved poster keeps working through
    // the existing isItemFocused == firstVisibleItemIndex pattern.
    // Skip the very first fire of this LaunchedEffect — `kinoPlayRefocusTrigger` is a
    // session-wide counter, so on EVERY remount of VodWithChannels (e.g. user navigating
    // through the top menu and landing back on KINO_PLAY) the initial fire would
    // re-trigger refocus + bump currentRow > 0, auto-focusing the slider as soon as the
    // tab is highlighted. We only want to act on actual increments after mount.
    var didKinoRefocusInitialFire by remember { mutableStateOf(false) }
    LaunchedEffect(VodDataCache.kinoPlayRefocusTrigger.value) {
        if (!didKinoRefocusInitialFire) {
            didKinoRefocusInitialFire = true
            return@LaunchedEffect
        }
        if (VodDataCache.kinoPlayRefocusTrigger.value > 0 && focusedRowIndex >= 1) {
            // Re-assert "inside section" so the menu hijack effect doesn't snatch focus.
            globalFocusState.value = globalFocusState.value.copy(currentRow = focusedRowIndex)
            kotlinx.coroutines.delay(50)
            if (focusedRowIndex >= 2) {
                try { rootBoxFocusRequester.requestFocus() } catch (_: Exception) {}
            }
            // Slider (focusedRowIndex == 1): VodHeroSliderV4's own LaunchedEffect on
            // refocusTriggerKey takes care of requestFocus on its internal FR.
        }
    }

    LaunchedEffect(shouldAutoFocus) {
        // Don't reset focus if we just restored from MovieDetail — we want to stay on
        // the channel/poster the user was on, not jump back to the slider.
        if (shouldAutoFocus && initialFocusRestore == null && !hasRestoredKinoPlayFocus) {
            focusedRowIndex = 1 // Start at slider
            focusedColIndex = 0 // Focus on rent button
        }
    }

    // Auto-reset LazyListState for unfocused rows (like MOJE)
    LaunchedEffect(focusedRowIndex, focusedColIndex, isInitialized) {
        if (isInitialized) {
            // Reduced from 150ms to 0ms for instant tab switching
            kotlinx.coroutines.delay(0)
            repeat(channels.size) { channelIndex ->
                val channelRowIndex = channelIndex + 2 // Channels start at row 2
                if (channelRowIndex != focusedRowIndex) {
                    val lazyListState = lazyListStates[channelIndex]
                    if (lazyListState != null && lazyListState.firstVisibleItemIndex > 0) {
                        lazyListState.animateScrollToItem(index = 0, scrollOffset = 0)
                    }
                }
            }
        }
    }

    Box(
        modifier = Modifier
            .fillMaxSize()
            .background(Color(0xFF281443))
            .focusRequester(rootBoxFocusRequester)
            .onPreviewKeyEvent { event ->
                handleVodNavigation(
                    event = event,
                    focusedRowIndex = focusedRowIndex,
                    focusedColIndex = focusedColIndex,
                    onFocusChange = { row, col ->
                        focusedRowIndex = row
                        focusedColIndex = col
                    },
                    channelFocusRequesters = channelFocusRequesters,
                    channels = channels,
                    lazyListStates = lazyListStates,
                    coroutineScope = coroutineScope,
                    gridContent = gridContent,
                    onReturnToMenu = onReturnToMenu,
                    sliderRowIndex = sliderRowIndex,
                    // KINO_PLAY: Always V4 slider with 2 buttons navigation
                    sliderVersion = 4,
                    v4ButtonIndex = v4ButtonIndex,
                    onV4ButtonIndexChange = { v4ButtonIndex = it },
                    // VOD Player navigation
                    onNavigateToVodPlayer = onNavigateToVodPlayer,
                    // Klik na CategoryIcon dowolnego channela → grid z filmami tego channela
                    // (używamy już pre-zbudowanego gridContent — single source of truth)
                    onCategoryEnter = { channelName ->
                        val filtered = gridContent[channelName] ?: emptyList()
                        if (filtered.isNotEmpty()) {
                            onNavigateToKinoGrid(channelName, filtered, "KINO_PLAY")
                        }
                    },
                    // ENTER na plakacie → MovieDetailScreen (zamiast VOD player)
                    onMovieClicked = { vodContent ->
                        // Save focus AND the channel's LazyRow scroll position so BACK
                        // from MovieDetail returns to exactly the same poster (regular
                        // channels show visual focus on whichever item is firstVisible).
                        // V1 maps Wypożyczone (row 1) → channelIdx 0, others row N → N-2.
                        val channelIdx = if (sliderRowIndex == 2 && focusedRowIndex == 1) 0 else focusedRowIndex - 2
                        val firstVisible = lazyListStates[channelIdx]?.firstVisibleItemIndex ?: 0
                        VodDataCache.savedKinoPlayFocus = VodDataCache.SavedKinoFocus(
                            row = focusedRowIndex,
                            col = focusedColIndex,
                            listFirstVisible = firstVisible
                        )
                        val slideData = VodSlideData(
                            title = vodContent.title,
                            genre = vodContent.category,
                            duration = "",
                            year = "",
                            country = "Polska",
                            ageRating = "13 lat",
                            description = vodContent.description,
                            price = vodContent.price ?: "19 zł/48h",
                            backgroundUrl = vodContent.backdropUrl ?: "",  // backdrop, NIE poster — pusty gdy brak
                            posterUrl = vodContent.imageUrl,
                            youtubeUrl = vodContent.youtubeUrl,
                            isKinoPlay = true,
                            cast = vodContent.cast
                        )
                        onNavigateToMovieDetail(slideData)
                    }
                )
            }
            .focusable()
    ) {
        VodLayoutWithSlider(
            focusedRowIndex = focusedRowIndex,
            focusedColIndex = focusedColIndex,
            channels = channels,
            gridContent = gridContent,
            channelFocusRequesters = channelFocusRequesters,
            onChannelContentFocusChange = { row, col ->
                Log.d("VOD_DEBUG", "Focus changed to row $row, col $col")
                focusedRowIndex = row
                focusedColIndex = col
            },
            onNavigateToVodGrid = onNavigateToVodGrid,
            onNavigateToKinoGrid = onNavigateToKinoGrid,
            onNavigateToMovieDetail = onNavigateToMovieDetail,
            onNavigateToPurchase = onNavigateToPurchase,
            quickPurchaseMode = quickPurchaseMode,
            lazyListStates = lazyListStates,
            globalFocusState = globalFocusState,
            sx = sx,
            sy = sy,
            sliderVersion = sliderVersion,
            v4ButtonIndex = v4ButtonIndex,
            sliderRowIndex = sliderRowIndex
        )
    }
}

@Composable
private fun VodLayoutWithSlider(
    focusedRowIndex: Int,
    focusedColIndex: Int,
    channels: List<String>,
    gridContent: Map<String, List<VodContent>>,
    channelFocusRequesters: Map<Pair<Int, Int>, FocusRequester>,
    onChannelContentFocusChange: (Int, Int) -> Unit,
    onNavigateToVodGrid: (title: String, prefiltered: List<VodContent>?, sourceSection: String) -> Unit = { _, _, _ -> },
    onNavigateToKinoGrid: (title: String, prefiltered: List<VodContent>?, sourceSection: String) -> Unit = { _, _, _ -> },
    onNavigateToMovieDetail: (VodSlideData) -> Unit = {},  // Navigate to MovieDetailScreen from KINO PLAY slider
    onNavigateToPurchase: (VodSlideData) -> Unit = {},  // Navigate directly to PurchaseScreen (quick mode)
    quickPurchaseMode: Boolean = false,  // When true, skip MovieDetail and go directly to Purchase
    lazyListStates: Map<Int, LazyListState>,
    globalFocusState: MutableState<GlobalFocusState>,
    sx: (Int) -> androidx.compose.ui.unit.Dp,
    sy: (Int) -> androidx.compose.ui.unit.Dp,
    sliderVersion: Int = 1,
    v4ButtonIndex: Int = 0,  // V4 slider button index (0 = Wypożycz, 1 = Dowiedz się więcej)
    sliderRowIndex: Int = 1  // V1 (Wypożyczone above slider) shifts slider to row 2
) {
    // Load KINO_PLAY slider items from Supabase
    val supabaseReady = VodDataCache.isSupabaseInitialized()
    val kinoPlaySliderItems = remember(supabaseReady) {
        VodDataCache.getSliderMovies()
    }

    Box(modifier = Modifier.fillMaxSize()) {
        // V1 pushes the slider down by the height of the Wypożyczone row above it so
        // there's room for the channel to render above it. V2 (default) keeps slider at top.
        val sliderTopOffset = if (sliderRowIndex == 2) 280 else 0
        val isFirstChannelBelowSliderFocused = focusedRowIndex == sliderRowIndex + 1
        val isLowerChannelsFocused = focusedRowIndex >= sliderRowIndex + 2
        val sliderYOffset by animateDpAsState(
            targetValue = when {
                isLowerChannelsFocused -> sy(-1200 + sliderTopOffset)
                isFirstChannelBelowSliderFocused -> sy(-640 + sliderTopOffset)
                // Wypożyczone (above slider) is focused in V1 — slider tucks slightly under it
                sliderRowIndex == 2 && focusedRowIndex == 1 -> sy(sliderTopOffset)
                else -> sy(sliderTopOffset)
            },
            animationSpec = tween(durationMillis = 500),
            label = "vod_slider_y_offset"
        )

        Box(
            modifier = Modifier
                .fillMaxSize()
                .offset(y = sliderYOffset)
                .zIndex(1f)
        ) {
            // KINO_PLAY: Always use V4 slider with 2 focusable buttons (Wypożycz + Więcej info)
            // Key.Nine cycling does NOT affect KINO_PLAY - always V4
            VodHeroSliderV4(
                isFocused = focusedRowIndex == sliderRowIndex && globalFocusState.value.currentRow > 0,
                items = kinoPlaySliderItems,
                sectionType = "KINO_PLAY",
                sx = sx,
                sy = sy,
                externalButtonIndex = v4ButtonIndex,
                onRentClicked = { item -> onNavigateToPurchase(item) },
                onMoreInfoClicked = { item -> onNavigateToMovieDetail(item) },
                onReturnToMenu = { /* callback do menu */ },
                showBullets = focusedRowIndex <= sliderRowIndex,
                isOnChannelsBelow = focusedRowIndex > sliderRowIndex,
                refocusTriggerKey = VodDataCache.kinoPlayRefocusTrigger.value
            )
        }

        // Gradient pod menu — widoczny gdy fokus jest na channelu poniżej slidera.
        val gradientAlpha by animateFloatAsState(
            targetValue = if (focusedRowIndex > sliderRowIndex) 1f else 0f,
            animationSpec = tween(durationMillis = 350),
            label = "vod_gradient_alpha"
        )

        if (gradientAlpha > 0f) {
            Box(
                modifier = Modifier
                    .fillMaxWidth()
                    .height(sy(300))
                    .zIndex(5f)
                    .alpha(gradientAlpha)
                    .background(
                        brush = Brush.verticalGradient(
                            colors = listOf(
                                Color(0xE6281443), // Dark purple 90%
                                Color(0x99281443), // Dark purple 60%
                                Color.Transparent
                            )
                        )
                    )
            )
        }

        // Channele (Row 2+) - z-index 10 (nad sliderem)
        // Pierwszy channel wystawający 40px od dołu
        Box(
            modifier = Modifier
                .fillMaxSize()
                .zIndex(10f)
        ) {
            VodChannelRows(
                channels = channels,
                gridContent = gridContent,
                focusedRowIndex = focusedRowIndex,
                focusedColIndex = focusedColIndex,
                channelFocusRequesters = channelFocusRequesters,
                onChannelContentFocusChange = onChannelContentFocusChange,
                onNavigateToVodGrid = onNavigateToVodGrid,
                onNavigateToKinoGrid = onNavigateToKinoGrid,
                lazyListStates = lazyListStates,
                sx = sx,
                sy = sy,
                sliderRowIndex = sliderRowIndex
            )
        }
    }
}

@OptIn(ExperimentalComposeUiApi::class)
@Composable
private fun VodHeroSlider(
    isFocused: Boolean,
    sx: (Int) -> androidx.compose.ui.unit.Dp,
    sy: (Int) -> androidx.compose.ui.unit.Dp
) {
    var currentSlide by remember { mutableStateOf(0) }
    val focusRequester = remember { FocusRequester() }
    val posterListState = rememberLazyListState()
    val coroutineScope = rememberCoroutineScope()

    // Check if Supabase is initialized (for recomposition when data loads)
    val supabaseReady = VodDataCache.isSupabaseInitialized()

    // Slider movies from Supabase (no fallback - shows preloader until data loads)
    val sliderItems = remember(supabaseReady) {
        VodDataCache.getSliderMovies()
    }

    // Reset currentSlide if it's out of bounds after data loads
    LaunchedEffect(sliderItems.size) {
        if (currentSlide >= sliderItems.size && sliderItems.isNotEmpty()) {
            currentSlide = 0
        }
    }

    LaunchedEffect(isFocused) {
        if (isFocused) {
            kotlinx.coroutines.delay(0)
            focusRequester.requestFocus()
        }
    }

    // Auto-scroll to center selected poster when it changes
    LaunchedEffect(currentSlide) {
        if (sliderItems.isNotEmpty()) {
            // Scroll to center the selected item
            // Calculate offset to center: (screenWidth/2) - (posterWidth/2) - (itemIndex * (posterWidth + spacing))
            val posterWidth = 200 // px (będzie przeskalowane przez LazyRow)
            val spacing = 16
            val itemWidth = posterWidth + spacing

            // Centrowanie - scrollujemy tak aby wybrany item był na środku
            // Używamy animateScrollToItem z offset dla centrowania
            posterListState.animateScrollToItem(
                index = currentSlide,
                scrollOffset = -(960 - posterWidth / 2) // ~środek ekranu minus połowa plakatu
            )
        }
    }

    Box(
        modifier = Modifier
            .fillMaxSize()
            .background(Color(0xFF281443)) // Dark purple background
            .focusRequester(focusRequester)
            .focusable()
            .onPreviewKeyEvent { event ->
                if (!isFocused) return@onPreviewKeyEvent false
                if (event.type != KeyEventType.KeyDown) return@onPreviewKeyEvent false
                if (sliderItems.isEmpty()) return@onPreviewKeyEvent false

                when (event.key) {
                    Key.DirectionLeft -> {
                        if (currentSlide > 0) {
                            currentSlide--
                        }
                        true
                    }
                    Key.DirectionRight -> {
                        if (currentSlide < sliderItems.size - 1) {
                            currentSlide++
                        }
                        true
                    }
                    else -> false
                }
            }
    ) {
        // Show preloader while loading from Supabase
        if (sliderItems.isEmpty()) {
            Box(
                modifier = Modifier.fillMaxSize(),
                contentAlignment = Alignment.Center
            ) {
                CircularProgressIndicator(
                    color = Color(0xFF5AECD3), // Aqua
                    modifier = Modifier.size(56.dp),
                    strokeWidth = 4.dp
                )
            }
        } else {
            // Capture STABLE item at slide change - prevents flickering when sliderItems reloads
            // This ensures trailer URL and all data remain consistent for the current slide
            val stableItem = remember(currentSlide) { sliderItems.getOrNull(currentSlide) ?: sliderItems[0] }
            // Trailer URL from database (youtube_url field in Supabase movies table)
            // Supports: direct MP4/M3U8 URLs (Supabase Storage), YouTube URLs (via extraction API)
            val trailerUrl = stableItem.youtubeUrl

            // Use stableItem for display, fallback to currentItem for fresh data when needed
            val displayItem = sliderItems.getOrNull(currentSlide) ?: stableItem

            // Trailer auto-play state - key by stableItem.title to be extra stable
            var showTrailer by remember(stableItem.title) { mutableStateOf(false) }

            // STABLE EFFECT: Only restarts when slide changes, not when focus flickers
            // isFocused is checked inside the loop to handle focus changes gracefully
            LaunchedEffect(stableItem.title) {
                android.util.Log.d("VodHeroSlider", "LaunchedEffect started for: ${stableItem.title}")

                // Continuous loop that checks focus state
                while (true) {
                    if (isFocused && !trailerUrl.isNullOrBlank() && !showTrailer) {
                        // Wait 2 seconds before showing trailer
                        kotlinx.coroutines.delay(2000)
                        // Double-check focus is still active after delay
                        if (isFocused && !trailerUrl.isNullOrBlank()) {
                            showTrailer = true
                            android.util.Log.d("VodHeroSlider", "Trailer START for: ${stableItem.title}, url=$trailerUrl")
                        }
                    } else if (!isFocused && showTrailer) {
                        // Hide trailer when focus is lost
                        showTrailer = false
                        android.util.Log.d("VodHeroSlider", "Trailer STOP (focus lost) for: ${stableItem.title}")
                    }
                    // Small delay to prevent busy-waiting
                    kotlinx.coroutines.delay(100)
                }
            }

            // LAYER 0 (BOTTOM): Trailer video - UNDER backdrop, fills entire screen
            // RESIZE_MODE_ZOOM in StyledPlayerView handles fullscreen filling
            key(currentSlide) {
                if (showTrailer && !trailerUrl.isNullOrBlank()) {
                    trailerUrl?.let { url ->
                        android.util.Log.d("VodHeroSlider", "YouTubeTrailerPlayer rendering for slide $currentSlide: ${url.take(60)}...")
                        Box(
                            modifier = Modifier
                                .fillMaxSize()
                                .zIndex(-1f)  // UNDER backdrop (lowest layer)
                        ) {
                            com.uxellence.tv.v3.components.YouTubeTrailerPlayer(
                                youtubeUrl = url,
                                modifier = Modifier
                                    .fillMaxSize()
                                    .scale(1.1f),  // hero slider: lekkie powiększenie video
                                startPositionMs = 2_000L
                            )
                        }
                    }
                }
            }

            // LAYER 1: Backdrop image (fades out when trailer plays to reveal video underneath)
            androidx.compose.animation.AnimatedVisibility(
                visible = !showTrailer,
                enter = androidx.compose.animation.fadeIn(animationSpec = androidx.compose.animation.core.tween(300)),
                exit = androidx.compose.animation.fadeOut(animationSpec = androidx.compose.animation.core.tween(300))
            ) {
                AsyncImage(
                    model = displayItem.backgroundUrl,
                    contentDescription = null,
                    modifier = Modifier.fillMaxSize(),
                    contentScale = ContentScale.Crop
                )
            }

            // LAYER 2: 20% black overlay - ONLY when backdrop is visible (trailer not playing)
            if (!showTrailer) {
                Box(
                    modifier = Modifier
                        .fillMaxSize()
                        .background(Color(0x33000000)) // 20% black
                )
            }

            // Left gradient for text readability - lighter when trailer is playing
            Box(
                modifier = Modifier
                    .fillMaxSize()
                    .zIndex(6f)  // On top of trailer for text readability
                    .background(
                        brush = Brush.horizontalGradient(
                            colors = if (showTrailer) {
                                // Lighter gradient when trailer plays (trailer has contrast)
                                listOf(
                                    Color(0x66000000),  // 40% black
                                    Color.Transparent
                                )
                            } else {
                                // Normal gradient for backdrop image
                                listOf(
                                    Color(0xAA000000),
                                    Color(0x33000000),
                                    Color.Transparent
                                )
                            },
                            endX = sx(960).value
                        )
                    )
            )

        Column(
            modifier = Modifier
                .align(Alignment.CenterStart)
                .width(sx(800))
                .padding(start = sx(80))
                .offset(y = -sy(100)) // Move everything up by 100px
                .zIndex(1f),
            verticalArrangement = Arrangement.spacedBy(sy(24))
        ) {
            // Title - up to half screen width (960px), single line unless longer
            Text(
                text = displayItem.title,
                color = Color.White,
                fontSize = sy(64).value.sp,
                fontWeight = FontWeight.Bold,
                maxLines = 2,
                overflow = TextOverflow.Ellipsis,
                modifier = Modifier.widthIn(max = sx(960))
            )

            Row(
                verticalAlignment = Alignment.CenterVertically,
                horizontalArrangement = Arrangement.spacedBy(sx(16))
            ) {
                Text(displayItem.genre, style = vodMetadataStyle(sy))
                VodMetadataSeparator(sy)
                Text(displayItem.duration, style = vodMetadataStyle(sy))
                VodMetadataSeparator(sy)
                Text(displayItem.year, style = vodMetadataStyle(sy))
                VodMetadataSeparator(sy)
                Text(displayItem.country, style = vodMetadataStyle(sy))
                VodMetadataSeparator(sy)
                Text(displayItem.ageRating, style = vodMetadataStyle(sy))
            }

            Text(
                text = displayItem.description,
                color = Color(0xFFEEEEEE),
                fontSize = sy(24).value.sp,
                fontWeight = FontWeight.W400,
                maxLines = 4,
                overflow = TextOverflow.Ellipsis,
                lineHeight = (sy(24).value * 1.4).sp
            )

        }

        // Poster row at bottom - edge-to-edge scrolling, centers on selected
        // zIndex(10f) ensures posters are ABOVE the trailer video
        LazyRow(
            state = posterListState,
            modifier = Modifier
                .align(Alignment.BottomStart)
                .fillMaxWidth()
                .zIndex(10f)  // ABOVE video layer
                .padding(bottom = sy(120)),
            horizontalArrangement = Arrangement.spacedBy(sx(16)),
            contentPadding = PaddingValues(horizontal = sx(80)) // Padding na krawędziach, scroll edge-to-edge
        ) {
            itemsIndexed(sliderItems) { index, item ->
                val isSelected = index == currentSlide
                val isSliderFocused = isFocused

                // Animowana skala (110% gdy selected + focused)
                val posterScale by animateFloatAsState(
                    targetValue = if (isSelected && isSliderFocused) 1.1f else 1f,
                    animationSpec = tween(200),
                    label = "poster_scale_$index"
                )

                Column(
                    horizontalAlignment = Alignment.CenterHorizontally
                ) {
                    // Poster - same size as channel posters (200x280)
                    Card(
                        modifier = Modifier
                            .width(sx(200))
                            .height(sy(280))
                            .graphicsLayer {
                                scaleX = posterScale
                                scaleY = posterScale
                            }
                            .then(
                                when {
                                    // Focused: aqua border + shadow
                                    isSelected && isSliderFocused -> Modifier
                                        .shadow(16.dp, RoundedCornerShape(sx(12)))
                                        .border(4.dp, Color(0xFF5AECD3), RoundedCornerShape(sx(12)))
                                    // Selected (not focused): white border (thinner)
                                    isSelected -> Modifier
                                        .border(2.dp, Color.White, RoundedCornerShape(sx(12)))
                                    // Other posters: no border
                                    else -> Modifier
                                }
                            ),
                        shape = RoundedCornerShape(sx(12)),
                        colors = CardDefaults.cardColors(containerColor = Color.Transparent)
                    ) {
                        AsyncImage(
                            model = item.posterUrl.ifEmpty { item.backgroundUrl },
                            contentDescription = item.title,
                            modifier = Modifier.fillMaxSize(),
                            contentScale = ContentScale.Crop
                        )
                    }

                    Spacer(modifier = Modifier.height(sy(8)))

                    // Price under poster (from Supabase)
                    Text(
                        text = item.price,
                        color = if (isSelected && isSliderFocused) Color(0xFF5AECD3)
                               else if (isSelected) Color.White
                               else Color(0xCCEEEEEE),
                        fontSize = sy(18).value.sp,
                        fontWeight = if (isSelected) FontWeight.W700 else FontWeight.W400
                    )
                }
            }
        }
        } // Close else block
    }
}

