/**
 * VodHeroSlider V2 - Carousel with V2 visual style (like V1 but with new card design)
 * Toggled with Key.Nine
 *
 * Uses STATE-BASED navigation (like V1) with LazyRow + animateScrollToItem.
 * This avoids Compose's "bring into view" auto-scroll by using a single FocusRequester
 * for the entire slider, not per-card FocusRequesters.
 *
 * @param items List of VodSlideData to display (passed from parent for section-specific content)
 */
@Composable
private fun VodHeroSliderV2(
    isFocused: Boolean,
    items: List<VodSlideData>, // Content items passed from parent (section-specific)
    sectionType: String, // "KINO_PLAY", "START", "WIDEO", "ODKRYWAJ"
    sx: (Int) -> androidx.compose.ui.unit.Dp,
    sy: (Int) -> androidx.compose.ui.unit.Dp,
    topPadding: Int = 200, // Default 200px, ODKRYWAJ uses 0 (parent handles positioning)
    onSlideChanged: (Int) -> Unit = {},
    onSlideClicked: ((VodSlideData) -> Unit)? = null,  // Callback when OK/Enter pressed on slide (KINO_PLAY)
    // Auto-rotation parameters (only for ODKRYWAJ)
    enableAutoRotate: Boolean = false,
    autoRotateIntervalMs: Long = 8000L,
    pauseAfterInteractionMs: Long = 10000L,
    // For detecting if user went to channels below (to start pause) vs menu (to reset pause)
    isOnChannelsBelow: Boolean = false,
    // Show/hide bullets (hide when focused on shortcuts or below in ODKRYWAJ)
    showBullets: Boolean = true,
    // === External state synchronization for ghost slider (infinity loop) ===
    externalCurrentSlide: Int? = null,  // When provided, use this instead of internal state
    onCurrentSlideChange: ((Int) -> Unit)? = null,  // Notify parent of slide changes
    externalProgress: Float? = null,  // When provided, use this for progress indicator
    // === Button navigation for KINO PLAY content (like V4 slider) ===
    externalButtonIndex: Int = 0,  // Button index controlled by parent (0=rent, 1=info)
    onButtonIndexChange: ((Int) -> Unit)? = null,  // Notify parent of button index changes
    // === Navigation callback when DOWN goes past slider (to next row) ===
    onNavigateDown: (() -> Unit)? = null,  // Called when DOWN should go to next row (not KINO PLAY or already on button 1)
    // === Navigation callback when UP goes past slider (to menu) ===
    onReturnToMenu: (() -> Unit)? = null  // Called when UP should go to menu (not KINO PLAY or already on button 0)
) {
    val sliderItems = items

    // Use external state if provided (for ghost slider synchronization), otherwise internal state
    var internalCurrentSlide by remember { mutableStateOf(0) }
    val currentSlide = externalCurrentSlide ?: internalCurrentSlide

    // Internal button index state (used when onButtonIndexChange is provided, otherwise just for display)
    var internalButtonIndex by remember { mutableIntStateOf(externalButtonIndex) }
    val buttonIndex = if (onButtonIndexChange != null) externalButtonIndex else internalButtonIndex

    val focusRequester = remember { FocusRequester() } // JEDEN dla całego slidera
    val listState = rememberLazyListState()

    // Auto-rotation states - using timestamp to prevent reset on recomposition
    var pauseUntilTime by remember { mutableLongStateOf(0L) }
    var internalProgress by remember { mutableFloatStateOf(0f) }
    val progress = externalProgress ?: internalProgress

    // Derived pause state for UI
    val isPaused = pauseUntilTime > System.currentTimeMillis()

    // Reset currentSlide if out of bounds after data loads
    LaunchedEffect(sliderItems.size) {
        if (currentSlide >= sliderItems.size && sliderItems.isNotEmpty()) {
            internalCurrentSlide = 0
            onCurrentSlideChange?.invoke(0)
        }
    }

    // Focus restoration when slider becomes focused
    // Handle pause based on where user navigated
    LaunchedEffect(isFocused, isOnChannelsBelow) {
        if (isFocused) {
            focusRequester.requestFocus()
        } else if (enableAutoRotate) {
            if (isOnChannelsBelow) {
                // User went DOWN to channels below - START pause
                pauseUntilTime = System.currentTimeMillis() + pauseAfterInteractionMs
            } else {
                // User went UP to top menu - RESET pause, resume auto-rotation
                pauseUntilTime = 0L
            }
        }
    }

    // Scroll to current slide (60px from left edge via contentPadding)
    // Only notify focus change when user is actually focused on slider (not during auto-rotation on top menu)
    LaunchedEffect(currentSlide) {
        if (sliderItems.isNotEmpty()) {
            listState.animateScrollToItem(
                index = currentSlide,
                scrollOffset = 0 // contentPadding handles 60px positioning
            )
            // Only update focus state when slider is focused (one focus rule)
            if (isFocused) {
                onSlideChanged(currentSlide)
            }
        }
    }

    // Auto-rotation - only when enableAutoRotate = true
    // Runs always (even when on top menu), pause persists through navigation
    if (enableAutoRotate && sliderItems.isNotEmpty()) {
        LaunchedEffect(currentSlide) {
            // Main animation loop
            while (true) {
                val now = System.currentTimeMillis()

                // Check if still in pause period
                if (now < pauseUntilTime) {
                    internalProgress = 0f
                    kotlinx.coroutines.delay(100) // Check pause status every 100ms
                    continue
                }

                // Animate progress bar
                val startTime = System.currentTimeMillis()
                var interrupted = false

                while (!interrupted) {
                    val currentTime = System.currentTimeMillis()

                    // Check if pause was triggered during animation
                    if (currentTime < pauseUntilTime) {
                        internalProgress = 0f
                        interrupted = true
                        continue
                    }

                    val elapsed = currentTime - startTime
                    internalProgress = (elapsed.toFloat() / autoRotateIntervalMs).coerceIn(0f, 1f)

                    if (elapsed >= autoRotateIntervalMs) {
                        // Go to next slide (or back to first)
                        val nextSlide = (currentSlide + 1) % sliderItems.size
                        internalCurrentSlide = nextSlide
                        onCurrentSlideChange?.invoke(nextSlide)
                        return@LaunchedEffect // Exit to restart with new currentSlide
                    }
                    kotlinx.coroutines.delay(16) // ~60 FPS
                }
            }
        }
    }

    Box(
        modifier = Modifier
            .fillMaxSize()
            .padding(top = sy(topPadding)) // Configurable top padding (200px default, 0 for ODKRYWAJ)
            .focusRequester(focusRequester)
            .focusable()
            .onPreviewKeyEvent { event ->
                if (!isFocused) return@onPreviewKeyEvent false
                if (event.type != androidx.compose.ui.input.key.KeyEventType.KeyDown) return@onPreviewKeyEvent false
                if (sliderItems.isEmpty()) return@onPreviewKeyEvent false

                // Check if current slide is KINO PLAY content (for button navigation)
                // Must match SliderV2CardStateBased logic: item.isKinoPlay OR sectionType == "KINO_PLAY"
                val currentItem = sliderItems.getOrNull(currentSlide)
                val isKinoPlayContent = currentItem?.isKinoPlay == true || sectionType == "KINO_PLAY"
                // KINO PLAY layout is used in KINO_PLAY and ODKRYWAJ sections
                val isKinoPlaySlide = isKinoPlayContent && sectionType in listOf("KINO_PLAY", "ODKRYWAJ")

                when (event.key) {
                    androidx.compose.ui.input.key.Key.DirectionLeft -> {
                        if (currentSlide > 0) {
                            val newSlide = currentSlide - 1
                            internalCurrentSlide = newSlide
                            onCurrentSlideChange?.invoke(newSlide)
                            if (enableAutoRotate) {
                                pauseUntilTime = System.currentTimeMillis() + pauseAfterInteractionMs
                                internalProgress = 0f
                            }
                            // Reset button index when changing slides
                            internalButtonIndex = 0
                            onButtonIndexChange?.invoke(0)
                        }
                        true
                    }
                    androidx.compose.ui.input.key.Key.DirectionRight -> {
                        if (currentSlide < sliderItems.size - 1) {
                            val newSlide = currentSlide + 1
                            internalCurrentSlide = newSlide
                            onCurrentSlideChange?.invoke(newSlide)
                            if (enableAutoRotate) {
                                pauseUntilTime = System.currentTimeMillis() + pauseAfterInteractionMs
                                internalProgress = 0f
                            }
                            // Reset button index when changing slides
                            internalButtonIndex = 0
                            onButtonIndexChange?.invoke(0)
                        }
                        true
                    }
                    androidx.compose.ui.input.key.Key.DirectionUp -> {
                        // For KINO PLAY content: navigate between buttons
                        if (isKinoPlaySlide && buttonIndex > 0) {
                            internalButtonIndex = buttonIndex - 1
                            onButtonIndexChange?.invoke(buttonIndex - 1)
                            true
                        } else {
                            // Not KINO PLAY or already on button 0 - return to menu
                            onReturnToMenu?.invoke()
                            onReturnToMenu != null // Consume if callback provided, else let parent handle
                        }
                    }
                    androidx.compose.ui.input.key.Key.DirectionDown -> {
                        // For KINO PLAY content: navigate between buttons (max 2 buttons: 0, 1)
                        if (isKinoPlaySlide && buttonIndex < 1) {
                            internalButtonIndex = buttonIndex + 1
                            onButtonIndexChange?.invoke(buttonIndex + 1)
                            true
                        } else {
                            // Not KINO PLAY or already on button 1 - navigate to next row
                            onNavigateDown?.invoke()
                            onNavigateDown != null // Consume if callback provided, else let parent handle
                        }
                    }
                    androidx.compose.ui.input.key.Key.Enter,
                    androidx.compose.ui.input.key.Key.DirectionCenter -> {
                        // Handle OK/Enter press
                        if (isKinoPlaySlide) {
                            sliderItems.getOrNull(currentSlide)?.let { item ->
                                when (buttonIndex) {
                                    0 -> onSlideClicked?.invoke(item)  // Wypożycz
                                    1 -> { /* TODO: More info action */ }
                                }
                            }
                            true
                        } else if (onSlideClicked != null) {
                            sliderItems.getOrNull(currentSlide)?.let { item ->
                                onSlideClicked.invoke(item)
                            }
                            true
                        } else {
                            false
                        }
                    }
                    else -> false
                }
            }
    ) {
        if (sliderItems.isEmpty()) {
            // Loading state
            Box(
                modifier = Modifier.fillMaxSize(),
                contentAlignment = Alignment.Center
            ) {
                CircularProgressIndicator(
                    color = Color(0xFF5AECD3),
                    modifier = Modifier.size(56.dp),
                    strokeWidth = 4.dp
                )
            }
        } else {
            // LazyRow with contentPadding for 60px left edge positioning
            LazyRow(
                state = listState,
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.spacedBy(sx(20)),
                contentPadding = PaddingValues(start = sx(60), end = sx(400))
            ) {
                itemsIndexed(sliderItems) { index, item ->
                    val isSelected = index == currentSlide

                    SliderV2CardStateBased(
                        item = item,
                        sectionType = sectionType,
                        slideIndex = index,
                        currentSlide = currentSlide,
                        isSelected = isSelected,
                        isSliderFocused = isFocused,
                        focusedButtonIndex = buttonIndex,  // Pass button index for KINO PLAY content
                        sx = sx,
                        sy = sy
                    )
                }
            }

            // Bullet indicators with progress bar for active slide (20px below slider)
            // Only show when showBullets = true (hidden when focused on shortcuts or below in ODKRYWAJ)
            if (showBullets) {
                Row(
                    modifier = Modifier
                        .align(Alignment.TopCenter)
                        .offset(y = sy(695)),
                    horizontalArrangement = Arrangement.spacedBy(sx(12)),
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    sliderItems.forEachIndexed { index, _ ->
                        val isActive = index == currentSlide

                        if (isActive && enableAutoRotate && !isPaused) {
                            // Progress bar for active slide (45px × 8px) - only when not paused
                            Box(
                                modifier = Modifier
                                    .width(sx(45))
                                    .height(sy(8))
                                    .clip(RoundedCornerShape(sy(4)))
                                    .background(Color(0x80EEEEEE)) // Background
                            ) {
                                Box(
                                    modifier = Modifier
                                        .fillMaxHeight()
                                        .fillMaxWidth(progress)
                                        .background(Color.White)
                                )
                            }
                        } else {
                            // Standard bullet for inactive slides OR when paused (dot replaces progress bar)
                            Box(
                                modifier = Modifier
                                    .size(if (isActive) sx(12) else sx(8))
                                    .background(
                                        color = if (isActive) Color.White else Color(0x80EEEEEE),
                                        shape = CircleShape
                                    )
                            )
                        }
                    }
                }
            }
        }
    }
}

/**
 * VodHeroSlider V3 - Simplified version with optional bullets and auto-rotation
 * Based on V2 but with:
 * - 🔀 Shuffled slide order (randomized on each session)
 * - 📍 Optional bullets and auto-rotation (toggled with Key.Eight)
 *
 * Toggled with Key.Nine (V2 ↔ V3)
 * Auto-slide toggled with Key.Eight (bullets + auto-rotation ON/OFF)
 *
 * @param items List of VodSlideData to display (will be shuffled internally)
 * @param enableAutoRotate When true, shows bullets with progress bar and auto-slides
 * @param autoRotateIntervalMs Time between auto-slides (default 8000ms)
 * @param pauseAfterInteractionMs Pause duration after user interaction (default 10000ms)
 */
@Composable
private fun VodHeroSliderV3(
    isFocused: Boolean,
    items: List<VodSlideData>,
    sectionType: String, // "KINO_PLAY", "WIDEO", "ODKRYWAJ"
    sx: (Int) -> androidx.compose.ui.unit.Dp,
    sy: (Int) -> androidx.compose.ui.unit.Dp,
    topPadding: Int = 200,
    onSlideChanged: (Int) -> Unit = {},
    onSlideClicked: ((VodSlideData) -> Unit)? = null,
    // External state synchronization (for ghost slider if needed)
    externalCurrentSlide: Int? = null,
    onCurrentSlideChange: ((Int) -> Unit)? = null,
    // When false, use items in original order (for synchronized ghost slider)
    shouldShuffle: Boolean = true,
    // Auto-rotation parameters (optional, enabled with Key.Eight)
    enableAutoRotate: Boolean = false,
    autoRotateIntervalMs: Long = 8000L,
    pauseAfterInteractionMs: Long = 10000L
) {
    // Shuffle items once on first composition (randomize order for this session)
    // When shouldShuffle = false, use items as-is (for ghost slider sync)
    val sliderItems = remember(items, shouldShuffle) {
        if (shouldShuffle) items.shuffled() else items
    }

    // Use external state if provided, otherwise internal state
    var internalCurrentSlide by remember { mutableStateOf(0) }
    val currentSlide = externalCurrentSlide ?: internalCurrentSlide

    val focusRequester = remember { FocusRequester() }
    val listState = rememberLazyListState()

    // Auto-rotation states - using timestamp to prevent reset on recomposition
    var pauseUntilTime by remember { mutableLongStateOf(0L) }
    var internalProgress by remember { mutableFloatStateOf(0f) }
    val progress = internalProgress

    // Derived pause state for UI
    val isPaused = pauseUntilTime > System.currentTimeMillis()

    // Reset currentSlide if out of bounds after data loads
    LaunchedEffect(sliderItems.size) {
        if (currentSlide >= sliderItems.size && sliderItems.isNotEmpty()) {
            internalCurrentSlide = 0
            onCurrentSlideChange?.invoke(0)
        }
    }

    // Focus restoration when slider becomes focused
    LaunchedEffect(isFocused) {
        if (isFocused) {
            focusRequester.requestFocus()
        }
    }

    // Scroll to current slide
    LaunchedEffect(currentSlide) {
        if (sliderItems.isNotEmpty()) {
            listState.animateScrollToItem(
                index = currentSlide,
                scrollOffset = 0
            )
            if (isFocused) {
                onSlideChanged(currentSlide)
            }
        }
    }

    // Auto-rotation - only when enableAutoRotate = true (toggled with Key.Eight)
    if (enableAutoRotate && sliderItems.isNotEmpty()) {
        LaunchedEffect(currentSlide, autoRotateIntervalMs) {
            // Main animation loop
            while (true) {
                val now = System.currentTimeMillis()

                // Check if still in pause period
                if (now < pauseUntilTime) {
                    internalProgress = 0f
                    kotlinx.coroutines.delay(100) // Check pause status every 100ms
                    continue
                }

                // Animate progress bar
                val startTime = System.currentTimeMillis()
                var interrupted = false

                while (!interrupted) {
                    val currentTime = System.currentTimeMillis()

                    // Check if pause was triggered during animation
                    if (currentTime < pauseUntilTime) {
                        internalProgress = 0f
                        interrupted = true
                        continue
                    }

                    val elapsed = currentTime - startTime
                    internalProgress = (elapsed.toFloat() / autoRotateIntervalMs).coerceIn(0f, 1f)

                    if (elapsed >= autoRotateIntervalMs) {
                        // Go to next slide (or back to first)
                        val nextSlide = (currentSlide + 1) % sliderItems.size
                        internalCurrentSlide = nextSlide
                        onCurrentSlideChange?.invoke(nextSlide)
                        return@LaunchedEffect // Exit to restart with new currentSlide
                    }
                    kotlinx.coroutines.delay(16) // ~60 FPS
                }
            }
        }
    }

    Box(
        modifier = Modifier
            .fillMaxSize()
            .padding(top = sy(topPadding))
            .focusRequester(focusRequester)
            .focusable()
            .onPreviewKeyEvent { event ->
                if (!isFocused) return@onPreviewKeyEvent false
                if (event.type != androidx.compose.ui.input.key.KeyEventType.KeyDown) return@onPreviewKeyEvent false
                if (sliderItems.isEmpty()) return@onPreviewKeyEvent false

                when (event.key) {
                    androidx.compose.ui.input.key.Key.DirectionLeft -> {
                        if (currentSlide > 0) {
                            val newSlide = currentSlide - 1
                            internalCurrentSlide = newSlide
                            onCurrentSlideChange?.invoke(newSlide)
                            // Pause auto-rotation after user interaction
                            if (enableAutoRotate) {
                                pauseUntilTime = System.currentTimeMillis() + pauseAfterInteractionMs
                                internalProgress = 0f
                            }
                        }
                        true
                    }
                    androidx.compose.ui.input.key.Key.DirectionRight -> {
                        if (currentSlide < sliderItems.size - 1) {
                            val newSlide = currentSlide + 1
                            internalCurrentSlide = newSlide
                            onCurrentSlideChange?.invoke(newSlide)
                            // Pause auto-rotation after user interaction
                            if (enableAutoRotate) {
                                pauseUntilTime = System.currentTimeMillis() + pauseAfterInteractionMs
                                internalProgress = 0f
                            }
                        }
                        true
                    }
                    androidx.compose.ui.input.key.Key.Enter,
                    androidx.compose.ui.input.key.Key.DirectionCenter -> {
                        if (onSlideClicked != null && sectionType == "KINO_PLAY") {
                            sliderItems.getOrNull(currentSlide)?.let { item ->
                                onSlideClicked.invoke(item)
                            }
                            true
                        } else {
                            false
                        }
                    }
                    else -> false
                }
            }
    ) {
        if (sliderItems.isEmpty()) {
            // Loading state
            Box(
                modifier = Modifier.fillMaxSize(),
                contentAlignment = Alignment.Center
            ) {
                CircularProgressIndicator(
                    color = Color(0xFF5AECD3),
                    modifier = Modifier.size(56.dp),
                    strokeWidth = 4.dp
                )
            }
        } else {
            // LazyRow with cards - NO bullets at bottom in V3
            LazyRow(
                state = listState,
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.spacedBy(sx(20)),
                contentPadding = PaddingValues(start = sx(60), end = sx(400))
            ) {
                itemsIndexed(sliderItems) { index, item ->
                    val isSelected = index == currentSlide

                    SliderV2CardStateBased(
                        item = item,
                        sectionType = sectionType,
                        slideIndex = index,
                        currentSlide = currentSlide,
                        isSelected = isSelected,
                        isSliderFocused = isFocused,
                        sx = sx,
                        sy = sy
                    )
                }
            }

            // Bullet indicators with progress bar for active slide (only when enableAutoRotate = true)
            if (enableAutoRotate && sliderItems.size > 1) {
                Row(
                    modifier = Modifier
                        .align(Alignment.TopCenter)
                        .offset(y = sy(695)),
                    horizontalArrangement = Arrangement.spacedBy(sx(12)),
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    sliderItems.forEachIndexed { index, _ ->
                        val isActive = index == currentSlide

                        if (isActive && !isPaused) {
                            // Progress bar for active slide (45px × 8px) - only when not paused
                            Box(
                                modifier = Modifier
                                    .width(sx(45))
                                    .height(sy(8))
                                    .clip(RoundedCornerShape(sy(4)))
                                    .background(Color(0x80EEEEEE)) // Background
                            ) {
                                Box(
                                    modifier = Modifier
                                        .fillMaxHeight()
                                        .fillMaxWidth(progress)
                                        .background(Color.White)
                                )
                            }
                        } else {
                            // Standard bullet for inactive slides OR when paused (dot replaces progress bar)
                            Box(
                                modifier = Modifier
                                    .size(if (isActive) sx(12) else sx(8))
                                    .background(
                                        color = if (isActive) Color.White else Color(0x80EEEEEE),
                                        shape = CircleShape
                                    )
                            )
                        }
                    }
                }
            }
        }
    }
}

/**
 * VodHeroSliderV4 - Slider with 2 focusable buttons on slide (LazyRow + Card based)
 *
 * Figma specs (node 1073:10931):
 * - Card: 1468×675px, border 2px, radius 16px
 * - Button position: X=40px, Y=452px
 * - Button size: max 472px × 72px
 * - Button gap: 16px
 * - Button radius: 8px
 * - Focused: bg=#5FEDD4, text=#48227C
 * - Unfocused: bg=rgba(238,238,238,0.2), text=#EEEEEE
 *
 * Navigation:
 * - LEFT/RIGHT: Change slide (preserve button position)
 * - UP/DOWN: Switch between buttons on same slide
 * - ENTER: Execute action (rent or more info)
 */
@Composable
private fun VodHeroSliderV4(
    isFocused: Boolean,
    items: List<VodSlideData>,
    sectionType: String,
    sx: (Int) -> androidx.compose.ui.unit.Dp,
    sy: (Int) -> androidx.compose.ui.unit.Dp,
    topPadding: Int = 200,
    externalButtonIndex: Int = 0,  // Button index controlled by parent (0=rent, 1=info)
    onRentClicked: ((VodSlideData) -> Unit)? = null,
    onMoreInfoClicked: ((VodSlideData) -> Unit)? = null,
    onReturnToMenu: () -> Unit = {},
    showBullets: Boolean = true,  // Hide bullets when focused below slider (KINO PLAY, WIDEO)
    isOnChannelsBelow: Boolean = false,  // gdy true (fokus na channels pod sliderem) — zatrzymaj trailer
    refocusTriggerKey: Int = 0  // Increment from outside to force re-requestFocus (e.g., after MovieDetail overlay closes)
) {
    // Shuffle items once on first composition
    val sliderItems = remember(items) { items.shuffled() }

    // State
    var currentSlide by remember { mutableStateOf(0) }
    // Use external button index from parent (navigation handled by handleVodNavigation)
    val focusedButtonIndex = externalButtonIndex

    val focusRequester = remember { FocusRequester() }
    val listState = rememberLazyListState()

    // === TRAILER AUTO-PLAY ===
    // Capture stable item at slide change (prevents flickering when sliderItems reloads)
    val stableItem = remember(currentSlide) { sliderItems.getOrNull(currentSlide) }
    val trailerUrl = stableItem?.youtubeUrl

    // Trailer auto-play state - key by stableItem.title to be extra stable
    var showTrailer by remember(stableItem?.title ?: "") { mutableStateOf(false) }
    // Suppress trailer auto-restart after the user comes back from MovieDetail overlay.
    // Set true by the refocusTriggerKey effect below; cleared on first user interaction.
    var suppressTrailerAfterOverlayBack by remember { mutableStateOf(false) }

    // Auto-play trailer: 2s after slider focus, 3s after menu idle (slider visible but not focused).
    // STOP gdy isOnChannelsBelow=true (user zszedł na channels pod sliderem) lub gdy overlay
    // (MovieDetail / Purchase / RentalProcessing) jest aktywne — wtedy nikt slidera i tak nie widzi,
    // a w tle ExoPlayer trailera spowalnia obsługę klawiszy w overlay'u.
    val isOverlayActive = com.uxellence.tv.v3.VodDataCache.overlayActive.value
    LaunchedEffect(stableItem?.title, isOnChannelsBelow, suppressTrailerAfterOverlayBack, isOverlayActive) {
        if (stableItem == null) return@LaunchedEffect
        android.util.Log.d("VodHeroSliderV4", "LaunchedEffect started for: ${stableItem.title}")

        // Wymuś stop trailer'a gdy zszedł na channels lub gdy overlay aktywne
        if ((isOnChannelsBelow || isOverlayActive) && showTrailer) {
            showTrailer = false
            android.util.Log.d("VodHeroSliderV4", "Trailer STOP (channels below or overlay) for: ${stableItem.title}")
        }

        while (!isOnChannelsBelow && !isOverlayActive) {
            if (!showTrailer && !trailerUrl.isNullOrBlank() && !suppressTrailerAfterOverlayBack) {
                val wasFocused = isFocused
                val delayMs = if (wasFocused) 2000L else 3000L
                kotlinx.coroutines.delay(delayMs)
                // Only start if focus state did not change during the wait AND nadal nie jesteśmy na channels
                if (!trailerUrl.isNullOrBlank() && isFocused == wasFocused && !isOnChannelsBelow && !suppressTrailerAfterOverlayBack && !com.uxellence.tv.v3.VodDataCache.overlayActive.value) {
                    showTrailer = true
                    val reason = if (wasFocused) "slider focus" else "menu idle"
                    android.util.Log.d("VodHeroSliderV4", "Trailer START ($reason) for: ${stableItem.title}")
                }
            }
            kotlinx.coroutines.delay(100)
        }
    }

    // Immersive mode: after 6s of idle on a focused slider (user on Wypożycz, trailer playing),
    // hide gradients/texts/secondary button/bullets — only trailer + Wypożycz button remain.
    // Any interaction (slide change, button change, losing focus) resets the timer and exits immersive.
    var immersiveMode by remember { mutableStateOf(false) }
    LaunchedEffect(currentSlide, externalButtonIndex, isFocused, showTrailer) {
        immersiveMode = false
        if (isFocused && externalButtonIndex == 0) {
            kotlinx.coroutines.delay(6000)
            if (isFocused && externalButtonIndex == 0 && showTrailer) {
                immersiveMode = true
                android.util.Log.d("VodHeroSliderV4", "Immersive mode ON (6s idle) for: ${stableItem?.title}")
            }
        }
    }

    // Focus restoration when slider becomes focused
    LaunchedEffect(isFocused) {
        if (isFocused) {
            focusRequester.requestFocus()
        }
    }

    // External-trigger refocus: when the parent flips refocusTriggerKey (e.g. KINO_PLAY's
    // overlay refocus signal after MovieDetail closes), re-grab keyboard focus on the
    // slider's FR. Needed because LaunchedEffect(isFocused) above only fires on
    // isFocused TRANSITIONS — when isFocused stays true across overlay open/close,
    // Compose's actual focus owner was lost (MovieDetail captured it) but the parameter
    // never changed, so no re-trigger.
    //
    // Also: stop the trailer (player ended while we were in MovieDetail anyway) and
    // suppress auto-restart, so the user lands on a static poster instead of an
    // unexpected re-playing trailer. Suppression lifts the moment the user does anything
    // (changes slide / switches button / leaves slider).
    // Skip first fire so a non-zero session-wide trigger from earlier rentals doesn't
    // auto-grab focus on every slider mount.
    var didSliderRefocusInitialFire by remember { mutableStateOf(false) }
    LaunchedEffect(refocusTriggerKey) {
        if (!didSliderRefocusInitialFire) {
            didSliderRefocusInitialFire = true
            return@LaunchedEffect
        }
        if (refocusTriggerKey > 0 && isFocused) {
            showTrailer = false
            suppressTrailerAfterOverlayBack = true
            kotlinx.coroutines.delay(50)
            try { focusRequester.requestFocus() } catch (_: Exception) {}
        }
    }
    // Lift trailer suppression on any user interaction with the slider
    LaunchedEffect(currentSlide, externalButtonIndex, isOnChannelsBelow) {
        if (suppressTrailerAfterOverlayBack) suppressTrailerAfterOverlayBack = false
    }

    // Scroll to current slide
    LaunchedEffect(currentSlide) {
        if (sliderItems.isNotEmpty()) {
            listState.animateScrollToItem(
                index = currentSlide,
                scrollOffset = 0
            )
        }
        // Reset trailer when changing slides
        showTrailer = false
    }

    Box(
        modifier = Modifier
            .fillMaxSize()
            .padding(top = sy(topPadding))
            .focusRequester(focusRequester)
            .focusable()
            .onPreviewKeyEvent { event ->
                if (!isFocused) return@onPreviewKeyEvent false
                if (event.type != androidx.compose.ui.input.key.KeyEventType.KeyDown) return@onPreviewKeyEvent false
                if (sliderItems.isEmpty()) return@onPreviewKeyEvent false

                // Note: UP/DOWN navigation is handled by parent (handleVodNavigation)
                // This handler only handles LEFT/RIGHT (slide change) and ENTER (action)
                when (event.key) {
                    androidx.compose.ui.input.key.Key.DirectionLeft -> {
                        if (currentSlide > 0) {
                            currentSlide--
                        }
                        true
                    }
                    androidx.compose.ui.input.key.Key.DirectionRight -> {
                        if (currentSlide < sliderItems.size - 1) {
                            currentSlide++
                        }
                        true
                    }
                    androidx.compose.ui.input.key.Key.Enter,
                    androidx.compose.ui.input.key.Key.DirectionCenter -> {
                        sliderItems.getOrNull(currentSlide)?.let { item ->
                            // If movie is rented, button 0 acts like "Oglądaj" → route to
                            // MovieDetail (the same place where rented branch shows watch UI).
                            val rentalsSnapshot = com.uxellence.tv.v3.rental.RentalManager.rentals.value
                            val isItemRented = (rentalsSnapshot[item.title] ?: 0L) > System.currentTimeMillis()
                            when (focusedButtonIndex) {
                                0 -> if (isItemRented) onMoreInfoClicked?.invoke(item) else onRentClicked?.invoke(item)
                                1 -> onMoreInfoClicked?.invoke(item)
                            }
                        }
                        true
                    }
                    else -> false  // Let parent handle UP/DOWN
                }
            }
    ) {
        if (sliderItems.isEmpty()) {
            // Loading state
            Box(
                modifier = Modifier.fillMaxSize(),
                contentAlignment = Alignment.Center
            ) {
                CircularProgressIndicator(
                    color = Color(0xFF5AECD3),
                    modifier = Modifier.size(56.dp),
                    strokeWidth = 4.dp
                )
            }
        } else {
            // LazyRow carousel (like V2/V3)
            LazyRow(
                state = listState,
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.spacedBy(sx(20)),
                contentPadding = PaddingValues(start = sx(60), end = sx(400))
            ) {
                itemsIndexed(sliderItems) { index, item ->
                    SliderV4Card(
                        item = item,
                        sectionType = sectionType,
                        slideIndex = index,
                        currentSlide = currentSlide,
                        isSelected = index == currentSlide,
                        isSliderFocused = isFocused,
                        focusedButtonIndex = focusedButtonIndex,
                        showTrailer = showTrailer && index == currentSlide,  // Only show trailer on selected card
                        immersiveMode = immersiveMode && index == currentSlide,  // Immersive only on selected card
                        onRentClicked = onRentClicked,
                        onMoreInfoClicked = onMoreInfoClicked,
                        sx = sx,
                        sy = sy
                    )
                }
            }

            // Slide indicator dots (20px below slider, same as V2)
            // Only show when showBullets is true (hidden when focused below slider or immersive mode)
            if (sliderItems.size > 1 && showBullets) {
                AnimatedVisibility(
                    visible = !immersiveMode,
                    enter = fadeIn(animationSpec = tween(300)) +
                            slideInVertically(animationSpec = tween(300)) { it },
                    exit = fadeOut(animationSpec = tween(300)) +
                            slideOutVertically(animationSpec = tween(300)) { it },
                    modifier = Modifier
                        .align(Alignment.TopCenter)
                        .offset(y = sy(695))
                ) {
                    Row(
                        horizontalArrangement = Arrangement.spacedBy(sx(12)),
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        sliderItems.forEachIndexed { index, _ ->
                            Box(
                                modifier = Modifier
                                    .size(if (index == currentSlide) sx(12) else sx(8))
                                    .background(
                                        color = if (index == currentSlide) Color.White else Color(0x80EEEEEE),
                                        shape = CircleShape
                                    )
                            )
                        }
                    }
                }
            }
        }
    }
}

/**
 * SliderV4Card - Card with 2 focusable buttons for V4 slider
 *
 * Figma specs:
 * - Size: 1468×675px
 * - Border: 2px #EEEEEE (unfocused), 4px #5FEDD4 (focused)
 * - Radius: 16px
 * - Adjacent slides: 30% opacity
 */
@Composable
private fun SliderV4Card(
    item: VodSlideData,
    sectionType: String,
    slideIndex: Int,
    currentSlide: Int,
    isSelected: Boolean,
    isSliderFocused: Boolean,
    focusedButtonIndex: Int,  // 0=rent, 1=info
    showTrailer: Boolean = false,  // Show video trailer instead of backdrop image
    immersiveMode: Boolean = false,  // Hide everything except trailer + Wypożycz button
    onRentClicked: ((VodSlideData) -> Unit)?,
    onMoreInfoClicked: ((VodSlideData) -> Unit)?,
    sx: (Int) -> androidx.compose.ui.unit.Dp,
    sy: (Int) -> androidx.compose.ui.unit.Dp
) {
    val isCardFocused = isSelected && isSliderFocused
    val isNextSlide = slideIndex == currentSlide + 1
    val isPrevSlide = slideIndex == currentSlide - 1
    val cardOpacity = if (isNextSlide || isPrevSlide) 0.3f else 1f

    Card(
        modifier = Modifier
            .width(sx(1468))
            .height(sy(675))
            .alpha(cardOpacity),
        shape = RoundedCornerShape(sx(16)),
        colors = CardDefaults.cardColors(containerColor = Color(0xFF281443)),
        border = if (isCardFocused)
            BorderStroke(sx(4), Color(0xFF5FEDD4))
        else
            BorderStroke(sx(2), Color(0xFFEEEEEE).copy(alpha = 0.2f)),
        elevation = CardDefaults.cardElevation(
            defaultElevation = if (isCardFocused) 16.dp else 4.dp
        )
    ) {
        Box(modifier = Modifier.fillMaxSize()) {
            // 1. Background: Trailer video OR static image
            // Trailer plays in two cases (controlled by parent via showTrailer):
            //  - slider focused for 2s (classic autoplay-on-focus)
            //  - top menu idle for 3s (ambient autoplay while browsing menu)
            val shouldShowTrailer = showTrailer && !item.youtubeUrl.isNullOrBlank() && isSelected

            Box(
                modifier = Modifier.fillMaxSize(),
                contentAlignment = Alignment.CenterEnd
            ) {
                // Layer 1: Static backdrop image (always present, hidden when trailer plays)
                if (!shouldShowTrailer) {
                    AsyncImage(
                        model = item.backgroundUrl,
                        contentDescription = null,
                        modifier = Modifier
                            .fillMaxHeight()
                            .offset(x = if (isNextSlide) sx(-755) else 0.dp),
                        contentScale = ContentScale.FillHeight
                    )
                }

                // Layer 2: Trailer video (when shouldShowTrailer=true)
                if (shouldShowTrailer) {
                    Log.d("SliderV4Card", "Playing trailer for ${item.title}: ${item.youtubeUrl}")
                    YouTubeTrailerPlayer(
                        youtubeUrl = item.youtubeUrl!!,
                        modifier = Modifier
                            .fillMaxSize()
                            .scale(1.1f)  // hero slider: lekkie powiększenie video
                            .zIndex(2f),
                        startPositionMs = 2_000L
                    )
                }
            }

            // 2. Glow overlay (slide_glow_left.png) - only when slider focused and not in immersive mode
            if (!isNextSlide && sectionType == "KINO_PLAY") {
                androidx.compose.animation.AnimatedVisibility(
                    visible = isSliderFocused && !immersiveMode,
                    enter = fadeIn(animationSpec = tween(300)),
                    exit = fadeOut(animationSpec = tween(300)),
                    modifier = Modifier.align(Alignment.TopStart)
                ) {
                    Image(
                        painter = painterResource(id = R.drawable.slide_glow_left),
                        contentDescription = null,
                        modifier = Modifier
                            .width(sx(1151))
                            .height(sy(675)),
                        contentScale = ContentScale.FillBounds
                    )
                }
            }

            // 3. Left gradient overlay
            // When trailer plays, extend gradient to left edge (no offset)
            if (!isNextSlide) {
                val gradientOffset = if (shouldShowTrailer) sx(0) else sx(266)
                val gradientWidth = if (shouldShowTrailer) sx(856) else sx(590) // 266 + 590 = 856
                androidx.compose.animation.AnimatedVisibility(
                    visible = !immersiveMode,
                    enter = fadeIn(animationSpec = tween(300)),
                    exit = fadeOut(animationSpec = tween(300)),
                    modifier = Modifier.align(Alignment.CenterStart)
                ) {
                    Box(
                        modifier = Modifier
                            .fillMaxHeight()
                            .width(gradientWidth)
                            .offset(x = gradientOffset)
                            .background(
                                brush = Brush.horizontalGradient(
                                    colors = listOf(
                                        Color(0xFF281443),
                                        Color.Transparent
                                    )
                                )
                            )
                    )
                }
            }

            // 4. Content area (hidden for next slide preview)
            if (!isNextSlide) {
                Box(
                    modifier = Modifier
                        .fillMaxSize()
                        .padding(start = sx(50))
                ) {
                    // EMBLEM: Logo + labels at TOP - only when slider focused and not in immersive mode
                    // Enters sliding from above + fade; exits sliding up + fade
                    androidx.compose.animation.AnimatedVisibility(
                        visible = isSliderFocused && !immersiveMode,
                        enter = fadeIn(animationSpec = tween(300)) +
                                slideInVertically(animationSpec = tween(300)) { -it },
                        exit = fadeOut(animationSpec = tween(300)) +
                                slideOutVertically(animationSpec = tween(300)) { -it },
                        modifier = Modifier
                            .align(Alignment.TopStart)
                            .zIndex(1f)
                    ) {
                        Box(
                            modifier = Modifier.height(sy(160)),
                            contentAlignment = Alignment.CenterStart
                        ) {
                            Row(
                                verticalAlignment = Alignment.CenterVertically,
                                horizontalArrangement = Arrangement.spacedBy(sx(30))
                            ) {
                                // KINO PLAY logo
                                if (item.isKinoPlay || sectionType == "KINO_PLAY") {
                                    Image(
                                        painter = painterResource(id = R.drawable.logo_kino_pay),
                                        contentDescription = "KINO PLAY"
                                    )
                                    // Premiera premium label
                                    ContentLabelV2(
                                        label = "Premiera premium",
                                        show4K = true,
                                        sx = sx,
                                        sy = sy
                                    )
                                }
                            }
                        }
                    }

                    // NOT FOCUSED + HAS LOGO: Show logo centered vertically
                    // Logo width limited to half of slide width (1468 / 2 = 734px)
                    if (!isSliderFocused && !item.selectedLogoUrl.isNullOrBlank()) {
                        Box(
                            modifier = Modifier
                                .align(Alignment.CenterStart)  // Centered vertically, left aligned
                        ) {
                            AsyncImage(
                                model = item.selectedLogoUrl,
                                contentDescription = item.title,
                                modifier = Modifier
                                    .widthIn(max = sx(734))
                                    .heightIn(max = sy(300)),
                                contentScale = ContentScale.Fit
                            )
                        }
                    }

                    // === V4: Buttons at BOTTOM ===
                    // Original order preserved: Wypożycz (button 1) on top, Dowiedz się więcej (button 2) below.
                    // Each button anchored independently so button 1 never shifts when button 2 / texts animate.
                    val buttonBottomPadding = sy(50)
                    val button2Height = sy(72)
                    val buttonGap = sy(24)

                    // Content column ABOVE Button 1 (title/meta/desc or non-focused big title)
                    Column(
                        modifier = Modifier
                            .align(Alignment.BottomStart)
                            .padding(bottom = buttonBottomPadding + button2Height + buttonGap + sy(72) + buttonGap),
                        verticalArrangement = Arrangement.spacedBy(sy(24))
                    ) {
                        // FOCUSED STATE: Title + metadata + description
                        // Hidden in immersive mode. Slides down + fade on exit.
                        AnimatedVisibility(
                            visible = isSliderFocused && !immersiveMode,
                            enter = fadeIn(animationSpec = tween(300)) +
                                    slideInVertically(animationSpec = tween(300)) { it },
                            exit = fadeOut(animationSpec = tween(300)) +
                                    slideOutVertically(animationSpec = tween(300)) { it }
                        ) {
                            Column(
                                verticalArrangement = Arrangement.spacedBy(sy(24))
                            ) {
                                // Title — gdy jest logo filmu, pokaż logo zamiast pisanego tytułu
                                if (!item.selectedLogoUrl.isNullOrBlank()) {
                                    AsyncImage(
                                        model = item.selectedLogoUrl,
                                        contentDescription = item.title,
                                        contentScale = ContentScale.Fit,
                                        modifier = Modifier
                                            .heightIn(max = sy(120))
                                            .widthIn(max = sx(600))
                                    )
                                } else {
                                    Text(
                                        text = item.title,
                                        color = Color(0xFFEEEEEE),
                                        fontSize = sy(48).value.sp,
                                        fontWeight = FontWeight.Medium,
                                        maxLines = 2,
                                        overflow = TextOverflow.Ellipsis,
                                        lineHeight = sy(56).value.sp,
                                        modifier = Modifier.widthIn(max = sx(600))
                                    )
                                }

                                // Metadata row
                                SliderMetadataRowV2(
                                    genre = item.genre,
                                    duration = item.duration,
                                    ageRating = item.ageRating,
                                    sectionType = sectionType,
                                    showKrritImage = sectionType == "KINO_PLAY",
                                    sx = sx,
                                    sy = sy
                                )

                                // Description (max 3 lines)
                                Text(
                                    text = item.description,
                                    color = Color(0xFFEEEEEE),
                                    fontSize = sy(24).value.sp,
                                    fontWeight = FontWeight.Normal,
                                    maxLines = 3,
                                    overflow = TextOverflow.Ellipsis,
                                    lineHeight = sy(32).value.sp,
                                    modifier = Modifier
                                        .widthIn(max = sx(550))
                                        .heightIn(max = sy(100))
                                )
                            }
                        }

                        // NOT FOCUSED + NO LOGO: Title above button
                        if (!isSliderFocused && item.selectedLogoUrl.isNullOrBlank()) {
                            Text(
                                text = item.title,
                                color = Color(0xFFEEEEEE),
                                fontSize = sy(72).value.sp,
                                fontWeight = FontWeight.Medium,
                                maxLines = 3,
                                overflow = TextOverflow.Clip,
                                lineHeight = sy(84).value.sp,
                                modifier = Modifier
                                    .widthIn(max = sx(600))
                                    .padding(bottom = sy(16))
                            )
                        }
                    }

                    // Button 1 (Wypożycz) — stays up when slider focused with UI visible (space reserved for Button 2 below);
                    // slides down to the very bottom when slider unfocused OR in immersive mode (Button 2 hidden).
                    val wypozyczBottomPadding by animateDpAsState(
                        targetValue = if (isSliderFocused && !immersiveMode) buttonBottomPadding + button2Height + buttonGap else buttonBottomPadding,
                        animationSpec = tween(300),
                        label = "wypozyczBottomPadding"
                    )
                    // Rented? Flip button label to "Oglądaj" and route ENTER to the
                    // "watch" path. Read directly from RentalManager so it stays reactive.
                    val rentalsSnapshot = com.uxellence.tv.v3.rental.RentalManager.rentals.value
                    val isItemRented = (rentalsSnapshot[item.title] ?: 0L) > System.currentTimeMillis()

                    Box(
                        modifier = Modifier
                            .align(Alignment.BottomStart)
                            .padding(bottom = wypozyczBottomPadding)
                    ) {
                        V4SliderButtonVisual(
                            label = if (isItemRented) "Oglądaj" else "Wypożycz: ${item.price}",
                            iconType = V4ButtonIcon.PLAY,
                            isFocused = isCardFocused && focusedButtonIndex == 0,
                            sx = sx,
                            sy = sy,
                            onClick = {
                                // Rented: route to MovieDetail (which exposes "Oglądaj" + countdown).
                                // Not rented: existing rent path (PurchaseScreen).
                                if (isItemRented) {
                                    onMoreInfoClicked?.invoke(item)
                                } else {
                                    onRentClicked?.invoke(item)
                                }
                            }
                        )
                    }

                    // Button 2 (Dowiedz się więcej) — below Wypożycz, animates in/out independently
                    androidx.compose.animation.AnimatedVisibility(
                        visible = isSliderFocused && !immersiveMode,
                        enter = fadeIn(animationSpec = tween(300)) +
                                slideInVertically(animationSpec = tween(300)) { it },
                        exit = fadeOut(animationSpec = tween(300)) +
                                slideOutVertically(animationSpec = tween(300)) { it },
                        modifier = Modifier
                            .align(Alignment.BottomStart)
                            .padding(bottom = buttonBottomPadding)
                    ) {
                        V4SliderButtonVisual(
                            label = "Dowiedz się więcej",
                            iconType = V4ButtonIcon.INFO,
                            isFocused = isCardFocused && focusedButtonIndex == 1,
                            sx = sx,
                            sy = sy,
                            onClick = { onMoreInfoClicked?.invoke(item) }
                        )
                    }
                }
            }
        }
    }
}

/**
 * V4SliderButtonVisual - Visual-only button for V4 slider cards (no FocusRequester)
 * Focus state is controlled by parent via isFocused prop
 */
@Composable
private fun V4SliderButtonVisual(
    label: String,
    iconType: V4ButtonIcon,
    isFocused: Boolean,
    sx: (Int) -> androidx.compose.ui.unit.Dp,
    sy: (Int) -> androidx.compose.ui.unit.Dp,
    onClick: () -> Unit
) {
    val backgroundColor by animateColorAsState(
        targetValue = if (isFocused) Color(0xFF5FEDD4) else Color(0x33EEEEEE),
        animationSpec = tween(150),
        label = "v4ButtonBg"
    )

    val contentColor by animateColorAsState(
        targetValue = if (isFocused) Color(0xFF48227C) else Color(0xFFEEEEEE),
        animationSpec = tween(150),
        label = "v4ButtonContent"
    )

    Row(
        modifier = Modifier
            .height(sy(72))
            .widthIn(max = sx(472))
            .clip(RoundedCornerShape(sx(8)))
            .background(backgroundColor)
            .clickable { onClick() }
            .padding(horizontal = sx(32)),
        horizontalArrangement = Arrangement.spacedBy(sx(8)),
        verticalAlignment = Alignment.CenterVertically
    ) {
        Icon(
            imageVector = when (iconType) {
                V4ButtonIcon.PLAY -> Icons.Filled.PlayArrow
                V4ButtonIcon.INFO -> Icons.Filled.Info
            },
            contentDescription = null,
            tint = contentColor,
            modifier = Modifier.size(sx(32))
        )

        Text(
            text = label,
            style = TextStyle(
                fontSize = (24 * sy(1).value / 1).sp,
                fontWeight = FontWeight.Bold,
                color = contentColor,
                letterSpacing = (-0.48).sp,
                lineHeight = (32 * sy(1).value / 1).sp
            )
        )
    }
}

private enum class V4ButtonIcon { PLAY, INFO }

/**
 * V4SliderButton - Focusable button for V4 slider
 *
 * Figma specs:
 * - Size: max 472px × 72px
 * - Border radius: 8px
 * - Padding: 32px horizontal
 * - Icon: 32x32px
 * - Gap icon-text: 8px
 * - Font: Manrope Bold 24px, letter-spacing: -0.48px
 * - Focused: bg=#5FEDD4, text=#48227C
 * - Unfocused: bg=rgba(238,238,238,0.2), text=#EEEEEE
 */
@Composable
private fun V4SliderButton(
    label: String,
    iconType: V4ButtonIcon,
    isFocused: Boolean,
    focusRequester: FocusRequester,
    sx: (Int) -> androidx.compose.ui.unit.Dp,
    sy: (Int) -> androidx.compose.ui.unit.Dp,
    onFocusChanged: (Boolean) -> Unit,
    onClick: () -> Unit
) {
    // Animated colors
    val backgroundColor by animateColorAsState(
        targetValue = if (isFocused) Color(0xFF5FEDD4) else Color(0x33EEEEEE),
        animationSpec = tween(150),
        label = "v4ButtonBg"
    )

    val contentColor by animateColorAsState(
        targetValue = if (isFocused) Color(0xFF48227C) else Color(0xFFEEEEEE),
        animationSpec = tween(150),
        label = "v4ButtonContent"
    )

    Row(
        modifier = Modifier
            .height(sy(72))
            .widthIn(max = sx(472))
            .clip(RoundedCornerShape(sx(8)))
            .background(backgroundColor)
            .focusRequester(focusRequester)
            .onFocusChanged { state -> onFocusChanged(state.isFocused) }
            .focusable()
            .clickable { onClick() }
            .padding(horizontal = sx(32)),
        horizontalArrangement = Arrangement.spacedBy(sx(8)),
        verticalAlignment = Alignment.CenterVertically
    ) {
        // Icon 32x32
        Icon(
            imageVector = when (iconType) {
                V4ButtonIcon.PLAY -> Icons.Filled.PlayArrow
                V4ButtonIcon.INFO -> Icons.Filled.Info
            },
            contentDescription = null,
            tint = contentColor,
            modifier = Modifier.size(sx(32))
        )

        // Label
        Text(
            text = label,
            style = TextStyle(
                fontSize = (24 * sy(1).value / 1).sp,
                fontWeight = FontWeight.Bold,
                color = contentColor,
                letterSpacing = (-0.48).sp,
                lineHeight = (32 * sy(1).value / 1).sp
            )
        )
    }
}

/**
 * Single card for V2 Slider carousel
 * Width: 1468px, Height: 742px
 * V2 visual style: aqua border, logo, metadata, button
 */
@Composable
private fun SliderV2Card(
    item: VodSlideData,
    sectionType: String,
    focusRequester: FocusRequester,
    sx: (Int) -> androidx.compose.ui.unit.Dp,
    sy: (Int) -> androidx.compose.ui.unit.Dp,
    enabled: Boolean = true,
    index: Int = 0,
    itemCount: Int = 1,
    onCardFocused: (Boolean) -> Unit
) {
    var isCardFocused by remember { mutableStateOf(false) }
    val isFirstItem = index == 0
    val isLastItem = index == itemCount - 1

    Card(
        modifier = Modifier
            .width(sx(1468))
            .height(sy(675))
            .focusRequester(focusRequester)
            .onFocusChanged { focusState ->
                isCardFocused = focusState.isFocused
                onCardFocused(focusState.isFocused)
            }
            .onPreviewKeyEvent { event ->
                if (event.type == androidx.compose.ui.input.key.KeyEventType.KeyDown) {
                    when (event.key) {
                        // Only block at boundaries - let default focus system handle normal navigation
                        androidx.compose.ui.input.key.Key.DirectionLeft -> {
                            if (isFirstItem) true else false // Block only on first item
                        }
                        androidx.compose.ui.input.key.Key.DirectionRight -> {
                            if (isLastItem) true else false // Block only on last item
                        }
                        else -> false
                    }
                } else {
                    false
                }
            }
            .focusable(enabled = enabled),
        shape = RoundedCornerShape(sx(16)),
        colors = CardDefaults.cardColors(
            containerColor = Color(0xFF2A1B3D)
        ),
        border = if (isCardFocused) BorderStroke(sx(4), Color(0xFF5FEDD4)) else BorderStroke(sx(2), Color(0xFFEEEEEE).copy(alpha = 0.2f)),
        elevation = CardDefaults.cardElevation(
            defaultElevation = if (isCardFocused) 16.dp else 4.dp
        )
    ) {
        Box(modifier = Modifier.fillMaxSize()) {
            // Background image (aligned to right, scaled to fit height)
            Box(
                modifier = Modifier.fillMaxSize(),
                contentAlignment = Alignment.CenterEnd
            ) {
                AsyncImage(
                    model = item.backgroundUrl,
                    contentDescription = null,
                    modifier = Modifier.fillMaxHeight(),
                    contentScale = ContentScale.FillHeight
                )
            }

            // Left gradient overlay
            Box(
                modifier = Modifier
                    .fillMaxSize()
                    .background(
                        brush = Brush.horizontalGradient(
                            colors = listOf(
                                Color(0xFF2A1B3D), // Solid purple
                                Color(0xE62A1B3D), // 90%
                                Color(0xB32A1B3D), // 70%
                                Color(0x662A1B3D), // 40%
                                Color.Transparent
                            ),
                            endX = sx(900).value
                        )
                    )
            )

            // Content column
            Column(
                modifier = Modifier
                    .fillMaxSize()
                    .padding(start = sx(48), top = sy(32), bottom = sy(32))
            ) {
                // Top row: Section logo + Content labels
                Row(
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.spacedBy(sx(16))
                ) {
                    // Section logo text
                    Text(
                        text = when (sectionType) {
                            "KINO_PLAY" -> "KINO PLAY"
                            else -> sectionType
                        },
                        color = Color(0xFF5FEDD4),
                        fontSize = sy(20).value.sp,
                        fontWeight = FontWeight.Bold
                    )

                    // Content labels
                    ContentLabelV2(
                        label = "Premiera premium",
                        show4K = true,
                        sx = sx,
                        sy = sy
                    )
                }

                Spacer(modifier = Modifier.height(sy(32)))

                // Title (max 3 lines)
                Text(
                    text = item.title,
                    color = Color(0xFFEEEEEE),
                    fontSize = sy(48).value.sp,
                    fontWeight = FontWeight.Medium,
                    maxLines = 3,
                    overflow = TextOverflow.Ellipsis,
                    lineHeight = sy(56).value.sp,
                    modifier = Modifier.widthIn(max = sx(600))
                )

                Spacer(modifier = Modifier.height(sy(16)))

                // Metadata row - KRRIT image for KINO_PLAY, WIDEO, or ODKRYWAJ movie/vod content
                SliderMetadataRowV2(
                    genre = item.genre,
                    duration = item.duration,
                    ageRating = item.ageRating,
                    sectionType = sectionType,
                    showKrritImage = sectionType in listOf("KINO_PLAY", "WIDEO") || item.showKrrit,
                    sx = sx,
                    sy = sy
                )

                Spacer(modifier = Modifier.height(sy(16)))

                // Description (max 3 lines)
                Text(
                    text = item.description,
                    color = Color(0xCCEEEEEE),
                    fontSize = sy(24).value.sp,
                    fontWeight = FontWeight.Normal,
                    maxLines = 3,
                    overflow = TextOverflow.Ellipsis,
                    lineHeight = sy(32).value.sp,
                    modifier = Modifier
                        .widthIn(max = sx(550))
                        .heightIn(max = sy(100))
                )

                Spacer(modifier = Modifier.weight(1f))

                // Action button (visible only when card is focused)
                if (isCardFocused) {
                    SliderActionButtonV2(
                        text = "Wypożycz: ${item.price}",
                        isFocused = true,
                        showIcon = true,
                        sx = sx,
                        sy = sy
                    )
                }
            }
        }
    }
}

/**
 * State-based card for V2 Slider carousel (no individual FocusRequester)
 * Width: 1468px, Height: 675px
 * V2 visual style: aqua border, logo, metadata, button
 *
 * Used by VodHeroSliderV2 with state-based navigation.
 * Focus is controlled by parent via isSelected/isSliderFocused props, not per-card focus.
 */
@Composable
private fun SliderV2CardStateBased(
    item: VodSlideData,
    sectionType: String,
    slideIndex: Int,          // Index slajdu (0, 1, 2, ...)
    currentSlide: Int,        // Aktualnie wybrany slajd (do określenia następnego)
    isSelected: Boolean,      // Czy ta karta jest wybrana (currentSlide)
    isSliderFocused: Boolean, // Czy slider ma fokus
    focusedButtonIndex: Int = 0,  // Button index for KINO PLAY content (0=rent, 1=info)
    sx: (Int) -> androidx.compose.ui.unit.Dp,
    sy: (Int) -> androidx.compose.ui.unit.Dp
) {
    // Card is "focused" when it's both selected AND the slider has focus
    val isCardFocused = isSelected && isSliderFocused

    // Czy to następny/poprzedni slajd (do specjalnej wizualizacji)
    val isNextSlide = slideIndex == currentSlide + 1
    val isPrevSlide = slideIndex == currentSlide - 1

    // Opacity: 30% dla następnego i poprzedniego slajdu
    val cardOpacity = if (isNextSlide || isPrevSlide) 0.3f else 1f

    Card(
        modifier = Modifier
            .width(sx(1468))
            .height(sy(675))
            .alpha(cardOpacity),
        shape = RoundedCornerShape(sx(16)),
        colors = CardDefaults.cardColors(
            containerColor = Color(0xFF281443)
        ),
        border = if (isCardFocused) BorderStroke(sx(4), Color(0xFF5FEDD4)) else BorderStroke(sx(2), Color(0xFFEEEEEE).copy(alpha = 0.2f)),
        elevation = CardDefaults.cardElevation(
            defaultElevation = if (isCardFocused) 16.dp else 4.dp
        )
    ) {
        Box(modifier = Modifier.fillMaxSize()) {
            // Background image (aligned to right, scaled to fit height)
            // Dla następnego slajdu: przesunięcie -487px (w lewo)
            Box(
                modifier = Modifier.fillMaxSize(),
                contentAlignment = Alignment.CenterEnd
            ) {
                AsyncImage(
                    model = item.backgroundUrl,
                    contentDescription = null,
                    modifier = Modifier
                        .fillMaxHeight()
                        .offset(x = if (isNextSlide) sx(-755) else 0.dp),
                    contentScale = ContentScale.FillHeight
                )
            }

            // Glow overlay (slide_glow_left.png) - pod tekstem, nad ilustracją
            // Only visible when slider is FOCUSED (like SliderV4Card)
            // Original image: 1151x675px - positioned at left edge of slide
            // APLIKACJE: glow zawsze widoczny (focus i bez focusa). Inne sekcje: tylko gdy focused.
            if (!isNextSlide && (sectionType == "APLIKACJE" || (isSliderFocused && sectionType in listOf("KINO_PLAY", "WIDEO", "ODKRYWAJ")))) {
                Image(
                    painter = painterResource(id = R.drawable.slide_glow_left),
                    contentDescription = null,
                    modifier = Modifier
                        .width(sx(1151))
                        .height(sy(675))
                        .align(Alignment.TopStart),
                    contentScale = ContentScale.FillBounds
                )
            }

            // Left gradient overlay - ukryty dla następnego slajdu
            if (!isNextSlide) {
                Box(
                    modifier = Modifier
                        .fillMaxHeight()
                        .width(sx(590))
                        .align(Alignment.CenterStart)
                        .offset(x = sx(266))  // Start from image left edge
                        .background(
                            brush = Brush.horizontalGradient(
                                colors = listOf(
                                    Color(0xFF281443),    // 100% #281443
                                    Color.Transparent     // 0% transparent
                                )
                            )
                        )
                )
            }

            // Content area - ukryty dla następnego slajdu (tylko ilustracja widoczna)
            if (!isNextSlide) {
                // Check if this is KINO PLAY content (either KINO_PLAY section or ODKRYWAJ with isKinoPlay)
                val isKinoPlayContent = item.isKinoPlay || sectionType == "KINO_PLAY"
                val useKinoPlayLayout = isKinoPlayContent && sectionType in listOf("KINO_PLAY", "ODKRYWAJ")

                Box(
                    modifier = Modifier
                        .fillMaxSize()
                        .padding(start = sx(50))
                ) {
                // === KINO PLAY LAYOUT (same states as SliderV4Card) ===
                if (useKinoPlayLayout) {
                    // EMBLEM: Logo + labels at TOP - only when slider focused
                    if (isSliderFocused) {
                        Box(
                            modifier = Modifier
                                .align(Alignment.TopStart)
                                .height(sy(160))
                                .zIndex(1f),
                            contentAlignment = Alignment.CenterStart
                        ) {
                            Row(
                                verticalAlignment = Alignment.CenterVertically,
                                horizontalArrangement = Arrangement.spacedBy(sx(30))
                            ) {
                                Image(
                                    painter = painterResource(id = R.drawable.logo_kino_pay),
                                    contentDescription = "KINO PLAY"
                                )
                                ContentLabelV2(
                                    label = "Premiera premium",
                                    show4K = true,
                                    sx = sx,
                                    sy = sy
                                )
                            }
                        }
                    }

                    // NOT FOCUSED + HAS LOGO: Show logo centered vertically
                    // Logo width limited to half of slide width (1468 / 2 = 734px)
                    if (!isSliderFocused && !item.selectedLogoUrl.isNullOrBlank()) {
                        Box(
                            modifier = Modifier
                                .align(Alignment.CenterStart)  // Centered vertically, left aligned
                        ) {
                            AsyncImage(
                                model = item.selectedLogoUrl,
                                contentDescription = item.title,
                                modifier = Modifier
                                    .widthIn(max = sx(734))
                                    .heightIn(max = sy(300)),
                                contentScale = ContentScale.Fit
                            )
                        }
                    }

                    // Content + Buttons at BOTTOM
                    Column(
                        modifier = Modifier
                            .align(Alignment.BottomStart)
                            .padding(bottom = sy(50)),
                        verticalArrangement = Arrangement.spacedBy(sy(24))
                    ) {
                        // FOCUSED STATE: Title + metadata + description ABOVE buttons
                        if (isSliderFocused) {
                            Text(
                                text = item.title,
                                color = Color(0xFFEEEEEE),
                                fontSize = sy(48).value.sp,
                                fontWeight = FontWeight.Medium,
                                maxLines = 2,
                                overflow = TextOverflow.Ellipsis,
                                lineHeight = sy(56).value.sp,
                                modifier = Modifier.widthIn(max = sx(600))
                            )

                            SliderMetadataRowV2(
                                genre = item.genre,
                                duration = item.duration,
                                ageRating = item.ageRating,
                                sectionType = sectionType,
                                showKrritImage = true,
                                sx = sx,
                                sy = sy
                            )

                            Text(
                                text = item.description,
                                color = Color(0xFFEEEEEE),
                                fontSize = sy(24).value.sp,
                                fontWeight = FontWeight.Normal,
                                maxLines = 3,
                                overflow = TextOverflow.Ellipsis,
                                lineHeight = sy(32).value.sp,
                                modifier = Modifier
                                    .widthIn(max = sx(550))
                                    .heightIn(max = sy(100))
                            )
                        }

                        // NOT FOCUSED + NO LOGO: Big title above button
                        if (!isSliderFocused && item.selectedLogoUrl.isNullOrBlank()) {
                            Text(
                                text = item.title,
                                color = Color(0xFFEEEEEE),
                                fontSize = sy(72).value.sp,
                                fontWeight = FontWeight.Medium,
                                maxLines = 3,
                                overflow = TextOverflow.Clip,
                                lineHeight = sy(84).value.sp,
                                modifier = Modifier
                                    .widthIn(max = sx(600))
                                    .padding(bottom = sy(16))
                            )
                        }

                        // Button 1: Wypożycz (always visible)
                        // item.price contains just the price for KINO PLAY content (e.g. "19.99 zł / 48h")
                        V4SliderButtonVisual(
                            label = if (item.price.startsWith("Wypożycz")) item.price else "Wypożycz: ${item.price}",
                            iconType = V4ButtonIcon.PLAY,
                            isFocused = isCardFocused && focusedButtonIndex == 0,
                            sx = sx,
                            sy = sy,
                            onClick = { }
                        )

                        // Button 2: Dowiedz się więcej (only when slider focused)
                        if (isSliderFocused) {
                            V4SliderButtonVisual(
                                label = "Dowiedz się więcej",
                                iconType = V4ButtonIcon.INFO,
                                isFocused = isCardFocused && focusedButtonIndex == 1,
                                sx = sx,
                                sy = sy,
                                onClick = { }
                            )
                        }
                    }
                }
                // === STANDARD LAYOUT (WIDEO and non-KINO PLAY ODKRYWAJ) ===
                else {
                    // EMBLEM: Logo at TOP
                    Box(
                        modifier = Modifier
                            .align(Alignment.TopStart)
                            .height(sy(160))
                            .zIndex(1f),
                        contentAlignment = Alignment.CenterStart
                    ) {
                        Row(
                            verticalAlignment = Alignment.CenterVertically,
                            horizontalArrangement = Arrangement.spacedBy(sx(30))
                        ) {
                            when (sectionType) {
                                "WIDEO" -> {
                                    if (!item.channelLogoUrl.isNullOrEmpty()) {
                                        AsyncImage(
                                            model = item.channelLogoUrl,
                                            contentDescription = "Channel logo",
                                            modifier = Modifier.heightIn(max = sy(100)),
                                            contentScale = ContentScale.Fit
                                        )
                                    }
                                }
                                "ODKRYWAJ" -> {
                                    if (!item.channelLogoUrl.isNullOrEmpty()) {
                                        AsyncImage(
                                            model = item.channelLogoUrl,
                                            contentDescription = "Logo",
                                            modifier = Modifier.heightIn(max = sy(100)),
                                            contentScale = ContentScale.Fit
                                        )
                                    }
                                }
                                "APLIKACJE" -> {
                                    // Logo aplikacji u góry (sztywno, niezależnie od focus)
                                    if (!item.selectedLogoUrl.isNullOrEmpty()) {
                                        AsyncImage(
                                            model = item.selectedLogoUrl,
                                            contentDescription = item.title,
                                            modifier = Modifier
                                                .heightIn(max = sy(120))
                                                .widthIn(max = sx(400)),
                                            contentScale = ContentScale.Fit
                                        )
                                    } else {
                                        Text(
                                            text = item.title,
                                            color = Color(0xFFEEEEEE),
                                            fontSize = sy(32).value.sp,
                                            fontWeight = FontWeight.Bold
                                        )
                                    }
                                }
                                else -> {
                                    Text(
                                        text = sectionType,
                                        color = Color(0xFF5FEDD4),
                                        fontSize = sy(20).value.sp,
                                        fontWeight = FontWeight.Bold
                                    )
                                }
                            }
                        }
                    }

                    // Content at BOTTOM
                    Column(
                        modifier = Modifier
                            .align(Alignment.BottomStart)
                            .padding(bottom = sy(50)),
                        verticalArrangement = Arrangement.spacedBy(sy(24))
                    ) {
                        // FOCUSED STATE: title (48sp) + metadata + description + button
                        if (isSliderFocused) {
                            Text(
                                text = item.title,
                                color = Color(0xFFEEEEEE),
                                fontSize = sy(48).value.sp,
                                fontWeight = FontWeight.Medium,
                                maxLines = if (sectionType == "APLIKACJE") 3 else 2,
                                overflow = TextOverflow.Ellipsis,
                                lineHeight = sy(56).value.sp,
                                modifier = Modifier.widthIn(max = sx(600))
                            )

                            // Metadata row pomijamy dla APLIKACJE (genre/duration/ageRating nieistotne)
                            if (sectionType != "APLIKACJE") {
                                SliderMetadataRowV2(
                                    genre = item.genre,
                                    duration = item.duration,
                                    ageRating = item.ageRating,
                                    sectionType = sectionType,
                                    showKrritImage = sectionType == "WIDEO",
                                    sx = sx,
                                    sy = sy
                                )
                            }

                            Text(
                                text = item.description,
                                color = Color(0xFFEEEEEE),
                                fontSize = sy(24).value.sp,
                                fontWeight = FontWeight.Normal,
                                maxLines = 3,
                                overflow = TextOverflow.Ellipsis,
                                lineHeight = sy(32).value.sp,
                                modifier = Modifier
                                    .widthIn(max = sx(550))
                                    .heightIn(max = sy(100))
                            )
                        }

                        // UNFOCUSED STATE: big title (72sp) only - like KINO PLAY unfocused
                        if (!isSliderFocused) {
                            Text(
                                text = item.title,
                                color = Color(0xFFEEEEEE),
                                fontSize = sy(72).value.sp,
                                fontWeight = FontWeight.Medium,
                                maxLines = 3,
                                overflow = TextOverflow.Clip,
                                lineHeight = sy(84).value.sp,
                                modifier = Modifier
                                    .widthIn(max = sx(600))
                                    .padding(bottom = sy(16))
                            )
                        }

                        // Single button (always visible)
                        val buttonText = when (sectionType) {
                            "WIDEO" -> "Oglądaj"
                            "ODKRYWAJ" -> item.price
                            "APLIKACJE" -> item.price  // np. "Otwórz aplikację" / "Zainstaluj aplikację"
                            else -> "Wypożycz: ${item.price}"
                        }
                        val isStandardButton = item.price.startsWith("Oglądaj") || item.price.startsWith("Wypożycz") || item.price.startsWith("Otwórz") || item.price.startsWith("Zainstaluj")
                        // APLIKACJE: button bez ikonki, sam tekst
                        val showIcon = sectionType != "APLIKACJE" && (sectionType != "ODKRYWAJ" || isStandardButton)
                        val usePlayIcon = sectionType == "WIDEO" ||
                            (sectionType == "ODKRYWAJ" && item.price.startsWith("Oglądaj"))

                        SliderActionButtonV2(
                            text = buttonText,
                            isFocused = isCardFocused,
                            showIcon = showIcon,
                            usePlayIcon = usePlayIcon,
                            sx = sx,
                            sy = sy
                        )
                    }
                }
                } // Close Box (content area)
            } // Close if (!isNextSlide)
        } // Close Box (main container)
    } // Close Card
} // Close function

@Composable
private fun VodChannelRows(
    channels: List<String>,
    gridContent: Map<String, List<VodContent>>,
    focusedRowIndex: Int,
    focusedColIndex: Int,
    channelFocusRequesters: Map<Pair<Int, Int>, FocusRequester>,
    onChannelContentFocusChange: (Int, Int) -> Unit,
    onNavigateToVodGrid: (title: String, prefiltered: List<VodContent>?, sourceSection: String) -> Unit = { _, _, _ -> },
    onNavigateToKinoGrid: (title: String, prefiltered: List<VodContent>?, sourceSection: String) -> Unit = { _, _, _ -> },
    lazyListStates: Map<Int, LazyListState>,
    sx: (Int) -> androidx.compose.ui.unit.Dp,
    sy: (Int) -> androidx.compose.ui.unit.Dp,
    sliderRowIndex: Int = 1  // V1 = 2 (slider sits BELOW Wypożyczone Kino on row 1)
) {
    Box(modifier = Modifier.fillMaxSize()) {
        channels.forEachIndexed { channelIndex, channelName ->
            // V2: channels start at row 2 (slider on row 1).
            // V1: channelIndex 0 (Wypożyczone) → row 1 (above slider on row 2);
            //     channelIndex 1+ → row 3+ (below slider).
            val actualRowIndex = if (sliderRowIndex == 2 && channelIndex == 0) {
                1
            } else {
                channelIndex + 2
            }
            val rowContent = gridContent[channelName] ?: emptyList()
            val lazyListState = lazyListStates[channelIndex] ?: LazyListState()

            // All channels use the same scrolling system (like MOJE)
            val targetY = calculateVodChannelYPosition(
                channelIndex = channelIndex,
                channelName = channelName,
                focusedRowIndex = focusedRowIndex,
                focusedColIndex = focusedColIndex,
                channels = channels,
                sy = sy,
                sliderRowIndex = sliderRowIndex
            )

            val channelYOffset by animateDpAsState(
                targetValue = targetY,
                animationSpec = tween(
                    durationMillis = 350, // Sync z miniatures (było 500ms)
                    easing = androidx.compose.animation.core.EaseInOutCubic // Match miniatures easing
                ),
                label = "vod_channel_y_offset_$channelIndex"
            )

            Box(
                modifier = Modifier.offset(y = channelYOffset)
            ) {
                when (channelName) {
                    "Wszystkie" -> {
                        VodWszystkieRow(
                            actualRowIndex = actualRowIndex,
                            focusedRowIndex = focusedRowIndex,
                            focusedColIndex = focusedColIndex,
                            channelFocusRequesters = channelFocusRequesters,
                            onChannelContentFocusChange = onChannelContentFocusChange,
                            onNavigateToKinoGrid = onNavigateToKinoGrid,
                            lazyListState = lazyListState,
                            sx = sx,
                            sy = sy
                        )
                    }
                    "Więcej" -> {
                        VodWiecejRow(
                            actualRowIndex = actualRowIndex,
                            focusedRowIndex = focusedRowIndex,
                            focusedColIndex = focusedColIndex,
                            channelFocusRequesters = channelFocusRequesters,
                            onChannelContentFocusChange = onChannelContentFocusChange,
                            onNavigateToKinoGrid = onNavigateToKinoGrid,
                            sx = sx,
                            sy = sy
                        )
                    }
                    else -> {
                        VodUnifiedChannelRow(
                            channel = channelName,
                            actualRowIndex = actualRowIndex,
                            rowContent = rowContent,
                            focusedRowIndex = focusedRowIndex,
                            focusedColIndex = focusedColIndex,
                            channelFocusRequesters = channelFocusRequesters,
                            onChannelContentFocusChange = onChannelContentFocusChange,
                            onNavigateToKinoGrid = onNavigateToKinoGrid,
                            sx = sx,
                            sy = sy,
                            lazyListState = lazyListState
                        )
                    }
                }
            }
        }

        // === BOTTOM TEXT (Naciśnij wstecz) - Shows when near bottom of list ===
        // focusedRowIndex uses actual row (2 = first channel), so channels.size - 1 + 2 = last channel row
        val lastActualRowIndex = channels.size - 1 + 2  // Last channel actual row index
        if (focusedRowIndex >= lastActualRowIndex - 2) {  // Show for last 3 channels
            val lastChannelIndex = channels.size - 1
            val lastChannelY = calculateVodChannelYPosition(
                channelIndex = lastChannelIndex,
                channelName = channels[lastChannelIndex],
                focusedRowIndex = focusedRowIndex,
                focusedColIndex = focusedColIndex,
                channels = channels,
                sy = sy,
                sliderRowIndex = sliderRowIndex
            )
            val lastChannelHeight = if (focusedRowIndex == lastActualRowIndex && focusedColIndex >= 0) {
                sy(VOD_HORIZONTAL_EXPANDED_ROW_HEIGHT)
            } else {
                sy(VOD_HORIZONTAL_NORMAL_ROW_HEIGHT)
            }

            val textYOffset by animateDpAsState(
                targetValue = lastChannelY + lastChannelHeight + sy(80),
                animationSpec = tween(durationMillis = 500),
                label = "vod_bottom_text_y_offset"
            )
            val glowYOffset by animateDpAsState(
                targetValue = lastChannelY + lastChannelHeight - sy(100),
                animationSpec = tween(durationMillis = 500),
                label = "vod_glow_y_offset"
            )

            // Glow background - lower z-index
            Image(
                painter = painterResource(id = R.drawable.glow_bottom),
                contentDescription = null,
                contentScale = ContentScale.None,
                alpha = 0.8f,
                modifier = Modifier
                    .fillMaxWidth()
                    .offset(y = glowYOffset)
                    .zIndex(-1f)
            )

            // Text and remote icon
            Row(
                verticalAlignment = Alignment.CenterVertically,
                horizontalArrangement = Arrangement.Center,
                modifier = Modifier
                    .fillMaxWidth()
                    .offset(y = textYOffset)
            ) {
                Text(
                    text = "Naciśnij",
                    color = Color(0xFFEEEEEE),
                    fontSize = sx(24).value.sp,
                    fontWeight = FontWeight.Bold,
                    letterSpacing = (-0.48).sp
                )
                Spacer(modifier = Modifier.width(sx(12)))
                Image(
                    painter = painterResource(id = R.drawable.remote_back),
                    contentDescription = "Wstecz",
                    contentScale = ContentScale.None
                )
                Spacer(modifier = Modifier.width(sx(12)))
                Text(
                    text = "na pilocie, aby wrócić do góry",
                    color = Color(0xFFEEEEEE),
                    fontSize = sx(24).value.sp,
                    fontWeight = FontWeight.Bold,
                    letterSpacing = (-0.48).sp
                )
            }
        }
    }
}

@Composable
private fun VodUnifiedChannelRow(
    channel: String,
    actualRowIndex: Int,
    rowContent: List<VodContent>,
    focusedRowIndex: Int,
    focusedColIndex: Int,
    channelFocusRequesters: Map<Pair<Int, Int>, FocusRequester>,
    onChannelContentFocusChange: (Int, Int) -> Unit,
    onNavigateToVodGrid: (title: String, prefiltered: List<VodContent>?, sourceSection: String) -> Unit = { _, _, _ -> },
    onNavigateToKinoGrid: (title: String, prefiltered: List<VodContent>?, sourceSection: String) -> Unit = { _, _, _ -> },
    sx: (Int) -> androidx.compose.ui.unit.Dp,
    sy: (Int) -> androidx.compose.ui.unit.Dp,
    lazyListState: LazyListState
) {
    val isCurrentRow = actualRowIndex == focusedRowIndex

    var showDetailsWithDelay by remember { mutableStateOf(false) }

    LaunchedEffect(isCurrentRow, focusedColIndex) {
        val shouldShowDetails = isCurrentRow && focusedColIndex == 0

        if (shouldShowDetails) {
            kotlinx.coroutines.delay(350)
            showDetailsWithDelay = true
        } else {
            showDetailsWithDelay = false
        }
    }

    Box(modifier = Modifier.fillMaxWidth()) {
        val isMiniaturesOnScreen = isCurrentRow && focusedColIndex >= 0
        val miniaturesYOffset by animateDpAsState(
            targetValue = if (isMiniaturesOnScreen) sy(290) else sy(0),
            animationSpec = tween(durationMillis = 350, easing = androidx.compose.animation.core.EaseInOutCubic),
            label = "vod_miniatures_y_offset_$actualRowIndex"
        )

        LazyRow(
            modifier = Modifier
                .fillMaxWidth()
                .offset(y = miniaturesYOffset), // Animacja 350ms - sync z channel offset
            state = lazyListState,
            contentPadding = PaddingValues(
                start = sx(380),
                end = sx(20)
                // top usunięte - pozycjonowanie przez .offset() dla smooth animation
            ),
            horizontalArrangement = Arrangement.spacedBy(sx(20))
        ) {
            items(rowContent.size) { colIndex ->
                val vodContent = rowContent[colIndex]
                val isItemFocused = actualRowIndex == focusedRowIndex &&
                        colIndex == lazyListState.firstVisibleItemIndex &&
                        focusedColIndex == 0

                val focusRequester = channelFocusRequesters[Pair(actualRowIndex, colIndex)] ?: FocusRequester()

                // Detect content type based on channel name
                val isHorizontal = false // No horizontal channels anymore - all use vertical posters

                when {
                    isHorizontal -> {
                        ContentCard(
                            vodContent = vodContent,
                            channelNumber = String.format("%03d", (actualRowIndex * 10 + colIndex + 1)),
                            isFocused = isItemFocused,
                            focusRequester = focusRequester,
                            onFocusChange = { onChannelContentFocusChange(actualRowIndex, colIndex) },
                            sx = sx,
                            sy = sy,
                            lazyListState = lazyListState
                        )
                    }
                    channel == "Top 10" -> {
                        Top10ContentCard(
                            vodContent = vodContent,
                            rankingNumber = colIndex + 1,
                            isFocused = isItemFocused,
                            focusRequester = focusRequester,
                            onFocusChange = { onChannelContentFocusChange(actualRowIndex, colIndex) },
                            sx = sx,
                            sy = sy
                        )
                    }
                    else -> {
                        VodContentCard(
                            vodContent = vodContent,
                            isFocused = isItemFocused,
                            focusRequester = focusRequester,
                            onFocusChange = { onChannelContentFocusChange(actualRowIndex, colIndex) },
                            sx = sx,
                            sy = sy
                        )
                    }
                }
            }

            // Spacer items - different sizes for Top 10 vs vertical posters
            items(8) {
                val isTop10 = channel == "Top 10"

                val spacerWidth = when {
                    isTop10 -> sx(261)
                    else -> sx(220) // Vertical poster width (all new channels)
                }

                val spacerHeight = when {
                    isTop10 -> sy(324)
                    else -> sy(380) // Vertical poster height (all new channels)
                }

                Spacer(
                    modifier = Modifier
                        .width(spacerWidth)
                        .height(spacerHeight)
                )
            }
        }

        // Details overlay (KINO_PLAY VodUnifiedChannelRow)
        if (isCurrentRow && focusedColIndex == 0 && showDetailsWithDelay) {
            val firstVisibleContent = rowContent.getOrNull(lazyListState.firstVisibleItemIndex)
            if (firstVisibleContent != null) {
                Box(
                    modifier = Modifier
                        .offset(x = sx(380), y = sy(0))
                        .width(sx(1500))
                ) {
                    Column(
                        verticalArrangement = Arrangement.spacedBy(sy(14))
                    ) {
                        Text(
                            text = firstVisibleContent.title,
                            color = Color(0xFFEEEEEE),
                            fontSize = (64 * (sy(1).value / 1.dp.value)).sp,
                            fontWeight = FontWeight.Medium,
                            lineHeight = (64 * 1.38f * (sy(1).value / 1.dp.value)).sp,
                            maxLines = 1,
                            overflow = TextOverflow.Ellipsis,
                            softWrap = false,
                            modifier = Modifier.width(sx(1500))
                        )

                        Row(
                            horizontalArrangement = Arrangement.spacedBy(sx(16)),
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            Text(
                                text = firstVisibleContent.category,
                                color = Color(0xCCEEEEEE),
                                fontSize = (20 * (sy(1).value / 1.dp.value)).sp,
                                fontWeight = FontWeight.Bold,
                                lineHeight = (20 * 1.4f * (sy(1).value / 1.dp.value)).sp,
                                letterSpacing = (0.4 * (sy(1).value / 1.dp.value)).sp
                            )
                        }

                        Text(
                            text = firstVisibleContent.description,
                            color = Color(0xFFEEEEEE),
                            fontSize = (28 * (sy(1).value / 1.dp.value)).sp,
                            fontWeight = FontWeight.Medium,
                            lineHeight = (28 * 1.43f * (sy(1).value / 1.dp.value)).sp,
                            maxLines = 3,
                            overflow = TextOverflow.Ellipsis,
                            modifier = Modifier.width(sx(874))
                        )
                    }
                }
            }
        }

        // CategoryIcon
        Box(modifier = Modifier.offset(x = sx(80), y = sy(0))) {
            val categoryIsFocused = actualRowIndex == focusedRowIndex && focusedColIndex == -1
            val categoryFocusRequester = channelFocusRequesters[Pair(actualRowIndex, -1)]

            // Logo dla różnych channeli
            val logoUrl = if (channel == "Cinemax") {
                "https://n-1411-1.dcs.redcdn.pl/scale/play/playtv/upload/live/19195238/images/1050844145?srcmode=3&srcx=0&srcy=0&srcw=1&srch=1&dstw=512&dsth=512&type=0"
            } else null

            val logoDrawableId = when (channel) {
                "Kino Play", "Polecane", "Top 10", "Ostatnio dodane\nwideo" -> R.drawable.kinoplay2
                "Seriale", "Filmy fabularne" -> R.drawable.wideo_kat
                else -> null
            }

            // VOD channels that should be text-only (like WIDEO style)
            val isVodCategoryChannel = channel in listOf("Akcja", "Komedie", "Horror", "Biograficzne")

            // "Wypożyczone Kino" channel mirrors MOJE/Wypożyczone visually — icon + label.
            val isRentedChannel = channel == "Wypożyczone Kino"
            val rentedIcon = if (isRentedChannel) R.drawable.ic_rented else null

            CategoryIcon(
                text = if (isRentedChannel) "Wypożyczone" else channel,
                isFocused = categoryIsFocused,
                onClick = {
                    // Navigate to KinoGridScreen with category-specific filtered content
                    if (isVodCategoryChannel) {
                        val vodList = VodDataCache.getKinoPlayMovies()
                        val categoryFilter = when (channel) {
                            "Akcja" -> "Akcja|Action"
                            "Komedie" -> "Komedia|Comedy"
                            "Horror" -> "Horror"
                            "Biograficzne" -> "Biograficzny|Biography|Biographical"
                            else -> channel
                        }
                        val filtered = filterMoviesByCategory(vodList, categoryFilter)
                        onNavigateToKinoGrid(channel, filtered, "KINO_PLAY")
                    }
                },
                onFocused = { isFocused ->
                    if (isFocused) {
                        Log.d("VOD_DEBUG", "CategoryIcon '$channel' (row $actualRowIndex) gained focus")
                        onChannelContentFocusChange(actualRowIndex, -1)
                    }
                },
                focusRequester = categoryFocusRequester ?: FocusRequester(),
                sx = sx,
                sy = sy,
                logoUrl = null,
                logoDrawableId = rentedIcon,
                showIcon = isRentedChannel,                          // Wypożyczone has icon; rest of Kino Play stays text-only per Figma
                showBackgroundWhenFocused = true                     // czarne tło na fokusie (jak EPG channels)
            )
        }
    }
}

@Composable
private fun ContentCard(
    vodContent: VodContent,
    channelNumber: String,
    isFocused: Boolean,
    focusRequester: FocusRequester,
    onFocusChange: () -> Unit,
    sx: (Int) -> androidx.compose.ui.unit.Dp,
    sy: (Int) -> androidx.compose.ui.unit.Dp,
    lazyListState: LazyListState,
    onClick: () -> Unit = {},
    showChannelNumber: Boolean = true,
    trailerUrl: String? = null,            // gdy podany i karta focused — po 2s odpala trailer overlay
    trailerStartPositionMs: Long = 0L      // od jakiej sekundy odpalić trailer
) {
    val baseWidth = sx(368)
    val baseHeight = sy(208)

    // Globalny zoom-on-focus: animowane width/height (zamiast graphicsLayer scale).
    // Dzięki temu LazyRow naturalnie przesuwa kolejne kafle w prawo, zachowując margines.
    val itemWidth by androidx.compose.animation.core.animateDpAsState(
        targetValue = if (isFocused) baseWidth * 1.22f else baseWidth,
        animationSpec = androidx.compose.animation.core.tween(durationMillis = 200),
        label = "card_width_on_focus"
    )
    val itemHeight by androidx.compose.animation.core.animateDpAsState(
        targetValue = if (isFocused) baseHeight * 1.22f else baseHeight,
        animationSpec = androidx.compose.animation.core.tween(durationMillis = 200),
        label = "card_height_on_focus"
    )

    // Autoplay trailer po 2s fokusa
    var showTrailer by remember { mutableStateOf(false) }
    LaunchedEffect(isFocused, trailerUrl) {
        if (isFocused && !trailerUrl.isNullOrBlank()) {
            kotlinx.coroutines.delay(2000)
            showTrailer = true
        } else {
            showTrailer = false
        }
    }

    // Offset w górę o połowę przyrostu height — żeby kafelek rósł symetrycznie góra/dół
    // (wycentrowany pionowo zamiast tylko w dół).
    val verticalCenterOffset = -((itemHeight - baseHeight) / 2)

    Box(
        modifier = Modifier
            .width(itemWidth)
            .height(itemHeight)
            .offset(y = verticalCenterOffset)
            .zIndex(if (isFocused) 1f else 0f)  // focused na wierzchu
            .clip(RoundedCornerShape(sx(12)))
            .then(
                if (isFocused) Modifier.border(
                    width = (6 * sx(1).value / 1.dp.value).dp,
                    color = Color(0xFF5AECD3),
                    shape = RoundedCornerShape(sx(12))
                ) else Modifier
            )
            .focusRequester(focusRequester)
            .onFocusChanged { if (it.isFocused) onFocusChange() }
            .onPreviewKeyEvent { event ->
                if (event.type == KeyEventType.KeyDown &&
                    (event.key == Key.Enter || event.key == Key.DirectionCenter)) {
                    onClick()
                    true
                } else {
                    false
                }
            }
            .focusable()
    ) {
        AsyncImage(
            model = vodContent.imageUrl,
            contentDescription = vodContent.title,
            modifier = Modifier.fillMaxSize(),
            contentScale = ContentScale.Crop
        )

        // Trailer overlay — pokrywa ilustrację gdy showTrailer (po 2s fokusa)
        // Modifier.scale(1.3f) powiększa video o 30% — eliminuje czarne pasy,
        // a clip kafelka (RoundedCornerShape) wycina nadmiar wystający poza kontener.
        // key(vodContent.id) wymusza recreate playera per kafel — bez tego state z poprzedniego kafla
        // (wszystkie używają tego samego mock URL) powoduje przesunięcie video.
        if (showTrailer && !trailerUrl.isNullOrBlank()) {
            androidx.compose.runtime.key(vodContent.id) {
                Box(modifier = Modifier.fillMaxSize().zIndex(2f)) {
                    com.uxellence.tv.v3.components.YouTubeTrailerPlayer(
                        youtubeUrl = trailerUrl,
                        modifier = Modifier
                            .fillMaxSize()
                            .scale(1.3f),
                        startPositionMs = trailerStartPositionMs,
                        stretchToFill = true  // mini kafel: stretch zamiast letterbox
                    )
                }
            }
        }

        // Gradient
        Box(
            modifier = Modifier
                .align(Alignment.BottomCenter)
                .fillMaxWidth()
                .height(sy(88))
                .background(
                    brush = Brush.verticalGradient(
                        colors = listOf(
                            Color.Transparent,
                            Color.Black.copy(alpha = 0.8f),
                            Color.Black
                        )
                    ),
                    shape = RoundedCornerShape(
                        bottomStart = sx(12),
                        bottomEnd = sx(12)
                    )
                )
        )

        // Channel number (only show if showChannelNumber is true)
        if (showChannelNumber) {
            Box(
                modifier = Modifier
                    .align(Alignment.TopEnd)
                    .padding(end = sx(12), top = sy(12))
                    .border(width = sx(1), color = Color.White.copy(alpha = 0.4f), shape = RoundedCornerShape(sx(4)))
                    .padding(horizontal = sx(12), vertical = sy(8)),
                contentAlignment = Alignment.Center
            ) {
                Text(
                    text = channelNumber,
                    color = Color.White,
                    fontSize = (20 * (sy(1).value / 1.dp.value)).sp,
                    fontWeight = FontWeight.Medium
                )
            }
        }

        // Title
        Text(
            text = vodContent.title,
            color = Color.White,
            fontSize = (20 * (sy(1).value / 1.dp.value)).sp,
            fontWeight = FontWeight.Bold,
            maxLines = 2,
            overflow = TextOverflow.Ellipsis,
            modifier = Modifier
                .align(Alignment.BottomStart)
                .padding(start = sx(12), bottom = sy(12), end = sx(12))
        )
    }
}

@OptIn(ExperimentalComposeUiApi::class)
@Composable
private fun SliderMiniatureCard(
    vodContent: VodContent,
    isFocused: Boolean,
    focusRequester: FocusRequester,
    onFocusChange: () -> Unit,
    sx: (Int) -> androidx.compose.ui.unit.Dp,
    sy: (Int) -> androidx.compose.ui.unit.Dp
) {
    val context = LocalContext.current
    val itemWidth = sx(368)
    val itemHeight = sy(208)

    // ExoPlayer for TV Live
    val player = remember {
        com.google.android.exoplayer2.ExoPlayer.Builder(context).build()
    }

    // Play TV stream when focused
    LaunchedEffect(isFocused, vodContent.link) {
        if (isFocused && vodContent.link.isNotEmpty()) {
            try {
                val mediaItem = com.google.android.exoplayer2.MediaItem.fromUri(vodContent.link)
                player.setMediaItem(mediaItem)
                player.prepare()
                player.playWhenReady = true
            } catch (e: Exception) {
                android.util.Log.e("SliderMiniatureCard", "Error playing TV stream: ${e.message}")
            }
        } else {
            player.stop()
            player.clearMediaItems()
        }
    }

    DisposableEffect(Unit) {
        onDispose {
            player.release()
        }
    }

    Box(
        modifier = Modifier
            .width(itemWidth)
            .height(itemHeight)
            .clip(RoundedCornerShape(sx(12)))
            .then(
                if (isFocused) Modifier.border(
                    width = (6 * sx(1).value / 1.dp.value).dp,
                    color = Color(0xFF5AECD3),
                    shape = RoundedCornerShape(sx(12))
                ) else Modifier
            )
            .focusRequester(focusRequester)
            .onFocusChanged { if (it.isFocused) onFocusChange() }
            .focusable()
    ) {
        // ExoPlayer view
        if (isFocused && vodContent.link.isNotEmpty()) {
            AndroidView(
                factory = { ctx ->
                    com.google.android.exoplayer2.ui.PlayerView(ctx).apply {
                        this.player = player
                        layoutParams = android.widget.FrameLayout.LayoutParams(
                            android.view.ViewGroup.LayoutParams.MATCH_PARENT,
                            android.view.ViewGroup.LayoutParams.MATCH_PARENT
                        )
                        useController = false
                        setShutterBackgroundColor(android.graphics.Color.TRANSPARENT)
                    }
                },
                modifier = Modifier.fillMaxSize()
            )
        } else {
            // Static placeholder when not focused
            Box(
                modifier = Modifier
                    .fillMaxSize()
                    .background(Color(0xFF1a1a1a))
            )
        }

        // Gradient overlay
        Box(
            modifier = Modifier
                .align(Alignment.BottomCenter)
                .fillMaxWidth()
                .height(sy(80))
                .background(
                    brush = Brush.verticalGradient(
                        colors = listOf(
                            Color.Transparent,
                            Color.Black.copy(alpha = 0.7f),
                            Color.Black
                        )
                    ),
                    shape = RoundedCornerShape(
                        bottomStart = sx(12),
                        bottomEnd = sx(12)
                    )
                )
        )

        // Channel title
        Text(
            text = vodContent.title,
            color = Color.White,
            fontSize = (18 * (sy(1).value / 1.dp.value)).sp,
            fontWeight = FontWeight.Bold,
            maxLines = 1,
            modifier = Modifier
                .align(Alignment.BottomStart)
                .padding(start = sx(16), bottom = sy(12))
        )

        // "LIVE" badge
        if (isFocused && vodContent.category == "Live TV") {
            Box(
                modifier = Modifier
                    .align(Alignment.TopStart)
                    .padding(start = sx(12), top = sy(12))
                    .background(Color.Red, shape = RoundedCornerShape(sx(4)))
                    .padding(horizontal = sx(8), vertical = sy(4)),
                contentAlignment = Alignment.Center
            ) {
                Text(
                    text = "LIVE",
                    color = Color.White,
                    fontSize = (14 * (sy(1).value / 1.dp.value)).sp,
                    fontWeight = FontWeight.Bold
                )
            }
        }
    }
}

