@OptIn(ExperimentalComposeUiApi::class)
@Composable
private fun CollectionSliderCard(
    vodContent: VodContent,
    isFocused: Boolean,
    focusRequester: FocusRequester,
    onFocusChange: () -> Unit,
    onClick: () -> Unit = {},
    sx: (Int) -> androidx.compose.ui.unit.Dp,
    sy: (Int) -> androidx.compose.ui.unit.Dp,
    hideOverlayContent: Boolean = false,  // Hide title, metadata, progress bar, logo when shortcuts focused
    mojaListaChannel: TvChannel? = null,  // NEW: channel from "Moja lista kanałów" for correct logo
    positionNumber: Int = 0,              // NEW: position-based number (1-9)
    useZeroPadding: Boolean = false,      // NEW: true = "01", false = "1"
    showPolecaneLabel: Boolean = false,   // NEW: show "polecane" label in top left
    showMojeLabel: Boolean = false        // NEW: show "moje" label in top left
) {
    val cardWidth = sx(640)  // Figma: 640x360px
    val cardHeight = sy(360)

    // Detect if this is an EPG card (link contains timestamps)
    val isEpgCard = vodContent.link.contains("|")

    // Parse EPG data if available
    val epgData = if (isEpgCard) {
        val parts = vodContent.link.split("|")
        if (parts.size >= 4) {
            val startUtc = java.time.Instant.parse(parts[0])
            val endUtc = java.time.Instant.parse(parts[1])
            val channelId = parts[2]
            val channelName = parts[3]

            // Calculate progress
            val now = java.time.Instant.now()
            val totalDuration = java.time.Duration.between(startUtc, endUtc).toMillis().toFloat()
            val elapsed = java.time.Duration.between(startUtc, now).toMillis().toFloat()
            val progress = if (totalDuration > 0) (elapsed / totalDuration).coerceIn(0f, 1f) else 0f

            // Format time
            val timeFormatter = java.time.format.DateTimeFormatter.ofPattern("HH:mm")
            val zoneId = java.time.ZoneId.systemDefault()
            val startTime = startUtc.atZone(zoneId).format(timeFormatter)
            val endTime = endUtc.atZone(zoneId).format(timeFormatter)

            Triple(progress, "$channelName | $startTime - $endTime", channelName)
        } else null
    } else null

    // Live TV playback support for EPG cards
    val context = androidx.compose.ui.platform.LocalContext.current
    var isPlayingLive by remember { mutableStateOf(false) }
    var isLoadingStream by remember { mutableStateOf(false) }

    // Metadata visibility state - show for 5 seconds after focus, then hide
    // DEFAULT: hidden (only logo, title, progress bar visible)
    // FOCUSED: metadata appears for 5 seconds, then hides
    var showMetadata by remember { mutableStateOf(false) }

    // ExoPlayer instance
    val player = remember {
        com.google.android.exoplayer2.ExoPlayer.Builder(context).build()
    }

    // Extract channel ID from EPG data
    val channelId = if (isEpgCard) {
        val parts = vodContent.link.split("|")
        if (parts.size >= 4) parts[2] else null
    } else null

    // Player listener to detect when video is actually ready to play
    DisposableEffect(player) {
        val listener = object : com.google.android.exoplayer2.Player.Listener {
            override fun onPlaybackStateChanged(playbackState: Int) {
                if (playbackState == com.google.android.exoplayer2.Player.STATE_READY && player.playWhenReady) {
                    isPlayingLive = true
                }
            }
        }
        player.addListener(listener)
        onDispose {
            player.removeListener(listener)
        }
    }

    // Start live TV in background on focus (no visible loader)
    LaunchedEffect(isFocused, channelId) {
        if (isFocused && isEpgCard && channelId != null) {
            isPlayingLive = false
            player.stop()

            // Small delay to avoid loading streams when quickly scrolling (1 second)
            kotlinx.coroutines.delay(1000)

            // After delay, check if still focused - load in background
            if (isFocused) {
                val streamUrl = ChannelStreamMapping.getStreamUrl(channelId)
                if (streamUrl != null) {
                    try {
                        val mediaItem = com.google.android.exoplayer2.MediaItem.fromUri(streamUrl)
                        player.setMediaItem(mediaItem)
                        player.prepare()
                        player.playWhenReady = true
                        // isPlayingLive will be set by listener when video is ready
                    } catch (e: Exception) {
                        isPlayingLive = false
                    }
                }
            }
        } else {
            // Lost focus or not EPG card - stop playback
            isPlayingLive = false
            player.stop()
        }
    }

    // Cleanup player on disposal
    DisposableEffect(Unit) {
        onDispose {
            player.release()
        }
    }

    // Timer to show metadata for 5 seconds after focus, then hide
    LaunchedEffect(isFocused) {
        if (isFocused) {
            // Show metadata when focused
            showMetadata = true
            // Wait 5 seconds, then hide metadata
            kotlinx.coroutines.delay(5000)
            showMetadata = false
        } else {
            // Hide metadata when unfocused
            showMetadata = false
        }
    }

    Card(
        modifier = Modifier
            .width(cardWidth)
            .height(cardHeight)
            .focusRequester(focusRequester)
            .onFocusChanged { focusState ->
                if (focusState.isFocused) {
                    onFocusChange()
                }
            }
            .onPreviewKeyEvent { event ->
                if (event.type == KeyEventType.KeyDown &&
                    (event.key == Key.Enter || event.key == Key.DirectionCenter)) {
                    android.util.Log.d("COLLECTION_SLIDER_CLICK", "OK pressed on: ${vodContent.title}")
                    // Zatrzymaj mini player jeśli jest aktywny
                    if (isPlayingLive) {
                        player.stop()
                        isPlayingLive = false
                    }
                    // Wywołaj callback - otwórz LiveScreen
                    onClick()
                    true
                } else {
                    false
                }
            }
            .focusable(),
        shape = RoundedCornerShape(sx(21)),  // Figma: 20.87px
        colors = CardDefaults.cardColors(
            containerColor = Color(0xFF5B3987)
        ),
        border = if (isFocused) BorderStroke(sx(6), Color(0xFF5FEDD4)) else BorderStroke(sx(2), Color(0xFFEEEEEE).copy(alpha = 0.2f)),  // Figma: 6px aqua or 2px white 20%
        elevation = CardDefaults.cardElevation(defaultElevation = if (isFocused) 12.dp else 4.dp)
    ) {
        Box(
            modifier = Modifier.fillMaxSize()
        ) {
            // Background image with gradient overlay
            Box(
                modifier = Modifier
                    .fillMaxSize()
                    .clip(RoundedCornerShape(sx(21)))  // Figma: 20.87px
            ) {
                // Background image from collection imageUrl
                AsyncImage(
                    model = vodContent.imageUrl,
                    contentDescription = vodContent.title,
                    modifier = Modifier.fillMaxSize(),
                    contentScale = ContentScale.Crop
                )

                // Live TV player overlay (replaces static image when playing)
                if (isPlayingLive) {
                    androidx.compose.ui.viewinterop.AndroidView(
                        factory = { ctx ->
                            com.google.android.exoplayer2.ui.PlayerView(ctx).apply {
                                this.player = player
                                useController = false
                                controllerAutoShow = false
                                controllerHideOnTouch = true
                                hideController()
                                setShowBuffering(com.google.android.exoplayer2.ui.PlayerView.SHOW_BUFFERING_WHEN_PLAYING)
                            }
                        },
                        modifier = Modifier.fillMaxSize()
                    )
                }

                // Gradient overlay - PNG images from Figma
                // For EPG cards: always use same gradient (bottom_gradient.png)
                // For non-EPG: horizontal purple gradient
                if (isEpgCard) {
                    // EPG cards: always use the same taller gradient
                    Image(
                        painter = painterResource(R.drawable.bottom_gradient),
                        contentDescription = null,
                        modifier = Modifier
                            .align(Alignment.BottomCenter)
                            .fillMaxWidth(),
                        contentScale = ContentScale.FillWidth
                    )
                } else {
                    // Non-EPG collection slider: horizontal purple gradient
                    Box(
                        modifier = Modifier
                            .align(Alignment.BottomCenter)
                            .fillMaxWidth()
                            .fillMaxHeight()
                            .background(
                                brush = Brush.horizontalGradient(
                                    colors = listOf(
                                        Color(0xFF5A3887),
                                        Color(0xFF5A3887).copy(alpha = 0f)
                                    ),
                                    startX = 0f,
                                    endX = 1000f
                                )
                            )
                    )
                }
            }

            // Content overlay (EPG layout vs Collection layout)
            // Fade animation for overlay content when shortcuts focused
            val overlayAlpha by animateFloatAsState(
                targetValue = if (hideOverlayContent) 0f else 1f,
                animationSpec = tween(durationMillis = 300),
                label = "overlay_alpha"
            )

            // Metadata visibility is controlled by showMetadata state
            // Hidden by default, appears for 5 seconds on focus, then animates out
            // Using AnimatedVisibility for smooth height animation (no gap when hidden)

            if (isEpgCard && epgData != null) {
                // EPG Layout according to Figma:
                // - Channel NUMBER in top RIGHT corner (with border)
                // - Channel LOGO in bottom LEFT corner (circular)
                // - Title, metadata, progress bar in bottom area
                val (progress, channelAndTime, channelName) = epgData

                // Get channel logo - prioritize mojaListaChannel over getTvChannelByEpgId
                val tvChannelData = getTvChannelByEpgId(channelName)
                val channelLogoUrl = mojaListaChannel?.logo
                    ?: tvChannelData?.logo
                    ?: vodContent.channelLogoUrl
                    ?: ""
                // Use position-based number (positionNumber) for display, fallback to channelNumber
                val displayNumber = if (positionNumber > 0) positionNumber
                    else mojaListaChannel?.channelNumber
                    ?: tvChannelData?.channelNumber
                    ?: 0

                // Channel NUMBER in top RIGHT corner - with PNG background and border
                if (displayNumber > 0) {
                    Box(
                        modifier = Modifier
                            .align(Alignment.TopEnd)
                            .alpha(overlayAlpha)  // Fade with shortcuts focus
                    ) {
                        // PNG background (Figma: 164x164px) - covers the corner
                        Image(
                            painter = painterResource(id = R.drawable.pod_numer),
                            contentDescription = null,
                            modifier = Modifier.size(sx(164), sy(164)),
                            contentScale = ContentScale.Fit
                        )
                        // Number with border - positioned 24px from top (same as label), 24px from right
                        Box(
                            modifier = Modifier
                                .align(Alignment.TopEnd)
                                .padding(top = sy(24), end = sx(24))
                                .height(sy(40))
                                .widthIn(max = sx(64))
                                .border(
                                    width = sx(2),
                                    color = Color(0xFFEEEEEE).copy(alpha = 0.4f),
                                    shape = RoundedCornerShape(sx(4))
                                )
                                .padding(horizontal = sx(12), vertical = sy(8)),
                            contentAlignment = Alignment.Center
                        ) {
                            Text(
                                text = if (useZeroPadding) displayNumber.toString().padStart(2, '0') else displayNumber.toString(),
                                color = Color(0xFFEEEEEE),
                                fontSize = (24 * (sy(1).value / 1.dp.value)).sp,
                                fontWeight = FontWeight.Medium
                            )
                        }
                    }
                }

                // Label in top LEFT corner - "polecane" or "moje"
                if (showPolecaneLabel || showMojeLabel) {
                    Image(
                        painter = painterResource(
                            id = if (showMojeLabel) R.drawable.moje_label else R.drawable.polecane_label
                        ),
                        contentDescription = if (showMojeLabel) "Moje" else "Polecane",
                        modifier = Modifier
                            .align(Alignment.TopStart)
                            .padding(top = sy(24), start = sx(24))  // Figma: 24px padding
                            .alpha(overlayAlpha),
                        contentScale = ContentScale.Fit
                    )
                }

                // Channel LOGO in bottom LEFT corner - always visible
                if (channelLogoUrl.isNotBlank()) {
                    AsyncImage(
                        model = channelLogoUrl,
                        contentDescription = "Channel logo",
                        modifier = Modifier
                            .align(Alignment.BottomStart)
                            .padding(start = sx(32), bottom = sy(16))  // Centered in available space
                            .size(sx(72))  // Logo fills entire space
                            .alpha(overlayAlpha)  // Fade with shortcuts focus
                            .clip(CircleShape),
                        contentScale = ContentScale.Crop
                    )
                }

                // Content area - always full content (title, metadata, progress bar)
                // Same layout for both thumbnail and live video modes
                Column(
                        modifier = Modifier
                            .align(Alignment.BottomStart)
                            .padding(start = sx(136), bottom = sy(26), end = sx(32))  // +10px higher from bottom
                            .fillMaxWidth()
                            .alpha(overlayAlpha),  // Fade with shortcuts focus
                        verticalArrangement = Arrangement.spacedBy(sy(4))  // Reduced spacing
                    ) {
                        // Program title - Figma: 24sp Medium, Manrope, line-height 32px, tracking 0.48px
                        Text(
                            text = vodContent.title,
                            color = Color(0xFFEEEEEE),
                            fontSize = (24 * (sy(1).value / 1.dp.value)).sp,
                            fontFamily = ManropeFamily,
                            fontWeight = FontWeight.Medium,
                            lineHeight = (32 * (sy(1).value / 1.dp.value)).sp,
                            maxLines = 1,
                            overflow = TextOverflow.Ellipsis,
                            letterSpacing = 0.48.sp
                        )

                        // Metadata row: time | age - 18sp Medium, Manrope
                        // AnimatedVisibility: smooth fade + height animation (no gap when hidden)
                        // Appears for 5 seconds on focus, then slides out
                        androidx.compose.animation.AnimatedVisibility(
                            visible = showMetadata,
                            enter = androidx.compose.animation.fadeIn(
                                animationSpec = tween(durationMillis = 300)
                            ) + androidx.compose.animation.expandVertically(
                                animationSpec = tween(durationMillis = 300)
                            ),
                            exit = androidx.compose.animation.fadeOut(
                                animationSpec = tween(durationMillis = 400)
                            ) + androidx.compose.animation.shrinkVertically(
                                animationSpec = tween(durationMillis = 400)
                            )
                        ) {
                            Row(
                                modifier = Modifier.fillMaxWidth(),
                                horizontalArrangement = Arrangement.spacedBy(sx(12)),
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                // Time range
                                Text(
                                    text = channelAndTime.substringAfter(" | ").ifEmpty { channelAndTime },
                                    color = Color(0xFFEEEEEE).copy(alpha = 0.8f),
                                    fontSize = (18 * (sy(1).value / 1.dp.value)).sp,
                                    fontFamily = ManropeFamily,
                                    fontWeight = FontWeight.Medium,
                                    maxLines = 1,
                                    letterSpacing = 0.4.sp
                                )
                                // Divider + Category (if fits)
                                if (vodContent.category.isNotBlank()) {
                                    Box(
                                        modifier = Modifier
                                            .width(sx(2))
                                            .height(sy(18))
                                            .background(Color(0xFFEEEEEE).copy(alpha = 0.4f))
                                    )
                                    // Category/age - truncate if doesn't fit
                                    Text(
                                        text = vodContent.category,
                                        color = Color(0xFFEEEEEE).copy(alpha = 0.8f),
                                        fontSize = (18 * (sy(1).value / 1.dp.value)).sp,
                                        fontFamily = ManropeFamily,
                                        fontWeight = FontWeight.Medium,
                                        maxLines = 1,
                                        overflow = TextOverflow.Ellipsis,
                                        letterSpacing = 0.4.sp
                                    )
                                }
                            }
                        }

                        // Progress bar - Figma: 8px height, radius-8
                        Box(
                            modifier = Modifier
                                .fillMaxWidth()
                                .height(sy(8))  // Figma: 8px
                                .clip(RoundedCornerShape(sx(8)))  // Figma: radius-8
                                .background(Color(0xFFEEEEEE).copy(alpha = 0.4f))  // Figma: stroke-disabled
                        ) {
                            Box(
                                modifier = Modifier
                                    .fillMaxHeight()
                                    .fillMaxWidth(progress)
                                    .clip(RoundedCornerShape(sx(8)))
                                    .background(Color(0xFFEEEEEE))  // Figma: stroke-primary
                            )
                        }
                    }
            } else if (!isEpgCard) {
                // Collection Layout: Title + Description + Logo
                Column(
                    modifier = Modifier
                        .align(Alignment.BottomStart)
                        .padding(start = sx(100), bottom = sy(100), end = sx(100))
                        .width(sx(442))
                        .alpha(overlayAlpha),  // Fade with shortcuts focus
                    verticalArrangement = Arrangement.spacedBy(sy(20))
                ) {
                    // Collection title
                    Text(
                        text = vodContent.title,
                        color = Color(0xFFEEEEEE),
                        fontSize = (41 * (sy(1).value / 1.dp.value)).sp,
                        fontWeight = FontWeight.Medium,
                        lineHeight = (57 * (sy(1).value / 1.dp.value)).sp,
                        maxLines = 2,
                        overflow = TextOverflow.Ellipsis
                    )

                    // Collection description
                    if (vodContent.description.isNotBlank()) {
                        Text(
                            text = vodContent.description,
                            color = Color(0xFFEEEEEE).copy(alpha = 0.8f),
                            fontSize = (20 * (sy(1).value / 1.dp.value)).sp,
                            fontWeight = FontWeight.Normal,
                            maxLines = 2,
                            overflow = TextOverflow.Ellipsis
                        )
                    }
                }

                // Logo in bottom right corner (only for collections)
                Box(
                    modifier = Modifier
                        .align(Alignment.BottomEnd)
                        .padding(end = sx(40), bottom = sy(40))
                        .size(sx(90), sy(90))
                        .alpha(overlayAlpha)  // Fade with shortcuts focus
                        .clip(RoundedCornerShape(sx(8)))
                        .background(Color.White.copy(alpha = 0.1f)),
                    contentAlignment = Alignment.Center
                ) {
                    // Placeholder for logo
                    Text(
                        text = vodContent.category.take(1),
                        color = Color.White,
                        fontSize = (40 * (sy(1).value / 1.dp.value)).sp,
                        fontWeight = FontWeight.Bold
                    )
                }
            }
        }
    }
}

// EPG Collection Slider Card for TELEWIZJA "Kategorie EPG" channel
// States:
// - Unfocused: show logo, title, progress bar (NO metadata)
// - Focused: show metadata (time, category) for 5 seconds, then hide
// - Playing live: different gradient
@Composable
private fun EpgCollectionSliderCard(
    epgProgram: com.uxellence.tv.v3.epg.EpgProgram,
    isFocused: Boolean,
    focusRequester: FocusRequester,
    onFocusChange: () -> Unit,
    sx: (Int) -> androidx.compose.ui.unit.Dp,
    sy: (Int) -> androidx.compose.ui.unit.Dp,
    isPlayingLive: Boolean = false  // True when live video is playing
) {
    val cardWidth = sx(640)  // Figma: 640px
    val cardHeight = sy(360)  // Figma: 360px

    // Metadata visibility state - show for 5 seconds after focus, then hide
    var showMetadata by remember { mutableStateOf(false) }

    // Timer to hide metadata after 5 seconds of focus
    LaunchedEffect(isFocused) {
        if (isFocused) {
            // Show metadata when focused
            showMetadata = true
            // Wait 5 seconds, then hide metadata
            kotlinx.coroutines.delay(5000)
            showMetadata = false
        } else {
            // Hide metadata when unfocused
            showMetadata = false
        }
    }

    // Calculate progress (how much of the program has elapsed)
    val now = java.time.Instant.now()
    val totalDuration = java.time.Duration.between(epgProgram.startUtc, epgProgram.endUtc).toMillis().toFloat()
    val elapsed = java.time.Duration.between(epgProgram.startUtc, now).toMillis().toFloat()
    val progress = if (totalDuration > 0) (elapsed / totalDuration).coerceIn(0f, 1f) else 0f

    // Format time
    val timeFormatter = java.time.format.DateTimeFormatter.ofPattern("HH:mm")
    val zoneId = java.time.ZoneId.systemDefault()
    val startTime = epgProgram.startUtc.atZone(zoneId).format(timeFormatter)
    val endTime = epgProgram.endUtc.atZone(zoneId).format(timeFormatter)

    // Get channel name from channelId
    val channelName = com.uxellence.tv.v3.utils.EpgAdapter.getChannelNameFromEpgId(epgProgram.channelId)

    Card(
        modifier = Modifier
            .width(cardWidth)
            .height(cardHeight)
            .focusRequester(focusRequester)
            .onFocusChanged { focusState ->
                if (focusState.isFocused) {
                    onFocusChange()
                }
            }
            .focusable(),
        shape = RoundedCornerShape(sx(21)),  // Figma: 20.87px
        colors = CardDefaults.cardColors(
            containerColor = Color(0xFF5B3987)
        ),
        border = if (isFocused) BorderStroke(sx(6), Color(0xFF5FEDD4)) else BorderStroke(sx(2), Color(0xFFEEEEEE).copy(alpha = 0.2f)),  // Figma: 6px aqua or 2px white 20%
        elevation = CardDefaults.cardElevation(defaultElevation = if (isFocused) 12.dp else 4.dp)
    ) {
        Box(
            modifier = Modifier.fillMaxSize()
        ) {
            // Background image
            Box(
                modifier = Modifier
                    .fillMaxSize()
                    .clip(RoundedCornerShape(sx(21)))  // Figma: 20.87px
            ) {
                AsyncImage(
                    model = epgProgram.iconUrl ?: "https://epg.ovh/logo/${channelName.lowercase().replace(" ", "-")}.png",
                    contentDescription = epgProgram.title,
                    modifier = Modifier.fillMaxSize(),
                    contentScale = ContentScale.Crop
                )

                // Gradient overlay - PNG image (different for live video vs thumbnail)
                Image(
                    painter = painterResource(
                        if (isPlayingLive) R.drawable.bottom_gradient_live else R.drawable.bottom_gradient
                    ),
                    contentDescription = null,
                    modifier = Modifier
                        .fillMaxWidth()
                        .align(Alignment.BottomCenter),
                    contentScale = ContentScale.FillWidth
                )
            }

            // Get channel logo and number from our channel list
            val tvChannel = getTvChannelByEpgId(channelName)
            val channelLogoUrl = tvChannel?.logo ?: ""
            val channelNumber = tvChannel?.channelNumber ?: 0

            // Content overlay (Figma layout) - offset for channel logo space
            Column(
                modifier = Modifier
                    .align(Alignment.BottomStart)
                    .padding(start = sx(136), bottom = sy(26), end = sx(32))  // +10px higher from bottom
                    .fillMaxWidth(),
                verticalArrangement = Arrangement.spacedBy(sy(4))  // Reduced spacing
            ) {
                // Program title - 31sp Medium, Manrope (ALWAYS VISIBLE)
                Text(
                    text = epgProgram.title,
                    color = Color(0xFFEEEEEE),
                    fontSize = (31 * (sy(1).value / 1.dp.value)).sp,
                    fontFamily = ManropeFamily,
                    fontWeight = FontWeight.Medium,
                    lineHeight = (40 * (sy(1).value / 1.dp.value)).sp,
                    maxLines = 1,
                    overflow = TextOverflow.Ellipsis,
                    letterSpacing = 0.64.sp
                )

                // Metadata row - 18sp Medium, Manrope (ONLY VISIBLE when focused for first 5 seconds)
                if (showMetadata) {
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.spacedBy(sx(12)),
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        // Time
                        Text(
                            text = "$startTime - $endTime",
                            color = Color(0xFFEEEEEE).copy(alpha = 0.8f),
                            fontSize = (18 * (sy(1).value / 1.dp.value)).sp,
                            fontFamily = ManropeFamily,
                            fontWeight = FontWeight.Medium,
                            maxLines = 1,
                            letterSpacing = 0.4.sp
                        )
                        // Divider + Category (if fits)
                        val categoriesText = epgProgram.categories.firstOrNull() ?: ""
                        if (categoriesText.isNotBlank()) {
                            Box(
                                modifier = Modifier
                                    .width(sx(2))
                                    .height(sy(18))
                                    .background(Color(0xFFEEEEEE).copy(alpha = 0.4f))
                            )
                            // Category - truncate if doesn't fit
                            Text(
                                text = categoriesText,
                                color = Color(0xFFEEEEEE).copy(alpha = 0.8f),
                                fontSize = (18 * (sy(1).value / 1.dp.value)).sp,
                                fontFamily = ManropeFamily,
                                fontWeight = FontWeight.Medium,
                                maxLines = 1,
                                overflow = TextOverflow.Ellipsis,
                                letterSpacing = 0.4.sp
                            )
                        }
                    }
                }

                // Progress bar - Figma: 8px height, radius-8 (ALWAYS VISIBLE)
                Box(
                    modifier = Modifier
                        .fillMaxWidth()
                        .height(sy(8))  // Figma: 8px
                        .clip(RoundedCornerShape(sx(8)))  // Figma: radius-8
                        .background(Color(0xFFEEEEEE).copy(alpha = 0.4f))  // Figma: stroke-disabled
                ) {
                    Box(
                        modifier = Modifier
                            .fillMaxHeight()
                            .fillMaxWidth(progress)
                            .clip(RoundedCornerShape(sx(8)))
                            .background(Color(0xFFEEEEEE))  // Figma: stroke-primary
                    )
                }
            }

            // Channel NUMBER in top RIGHT corner - Figma layout
            if (channelNumber > 0) {
                Box(
                    modifier = Modifier
                        .align(Alignment.TopEnd)
                        .padding(top = sy(16), end = sx(16))
                        .size(sx(48), sy(48))
                        .border(
                            width = sx(2),
                            color = Color(0xFFEEEEEE).copy(alpha = 0.4f),
                            shape = RoundedCornerShape(sx(4))
                        ),
                    contentAlignment = Alignment.Center
                ) {
                    Text(
                        text = channelNumber.toString(),
                        color = Color(0xFFEEEEEE),
                        fontSize = (24 * (sy(1).value / 1.dp.value)).sp,
                        fontWeight = FontWeight.Medium
                    )
                }
            }

            // Channel LOGO in bottom LEFT corner - circular, no background (Figma layout)
            if (channelLogoUrl.isNotBlank()) {
                AsyncImage(
                    model = channelLogoUrl,
                    contentDescription = "Channel logo",
                    modifier = Modifier
                        .align(Alignment.BottomStart)
                        .padding(start = sx(32), bottom = sy(16))  // Lower position
                        .size(sx(72))  // Logo fills entire space
                        .clip(CircleShape),
                    contentScale = ContentScale.Crop
                )
            }
        }
    }
}

@Composable
private fun VerticalContentCard(
    vodContent: VodContent,
    channelNumber: String,
    isFocused: Boolean,
    focusRequester: FocusRequester,
    onFocusChange: () -> Unit,
    sx: (Int) -> androidx.compose.ui.unit.Dp,
    sy: (Int) -> androidx.compose.ui.unit.Dp,
    showChannelNumber: Boolean = true
) {
    val itemWidth = sx(220)
    val itemHeight = sy(280)

    Box(
        modifier = Modifier
            .width(itemWidth)
            .height(itemHeight)
            .clip(RoundedCornerShape(sx(12)))
            .then(
                if (isFocused) Modifier.border(
                    width = (6 * sx(1).value / 1.dp.value).dp,
                    color = Color(0xFF5AECD3),
                    shape = RoundedCornerShape(sx(12))
                ) else Modifier
            )
            .focusRequester(focusRequester)
            .onFocusChanged { if (it.isFocused) onFocusChange() }
            .focusable()
    ) {
        AsyncImage(
            model = vodContent.imageUrl,
            contentDescription = vodContent.title,
            modifier = Modifier.fillMaxSize(),
            contentScale = ContentScale.Crop
        )

        // Gradient
        Box(
            modifier = Modifier
                .align(Alignment.BottomCenter)
                .fillMaxWidth()
                .height(sy(100))
                .background(
                    brush = Brush.verticalGradient(
                        colors = listOf(
                            Color.Transparent,
                            Color.Black.copy(alpha = 0.8f),
                            Color.Black
                        )
                    ),
                    shape = RoundedCornerShape(
                        bottomStart = sx(12),
                        bottomEnd = sx(12)
                    )
                )
        )

        // Channel number (only show if showChannelNumber is true)
        if (showChannelNumber) {
            Box(
                modifier = Modifier
                    .align(Alignment.TopEnd)
                    .padding(end = sx(12), top = sy(12))
                    .border(width = sx(1), color = Color.White.copy(alpha = 0.4f), shape = RoundedCornerShape(sx(4)))
                    .padding(horizontal = sx(12), vertical = sy(8)),
                contentAlignment = Alignment.Center
            ) {
                Text(
                    text = channelNumber,
                    color = Color.White,
                    fontSize = (20 * (sy(1).value / 1.dp.value)).sp,
                    fontWeight = FontWeight.Medium
                )
            }
        }

        // Title
        Text(
            text = vodContent.title,
            color = Color.White,
            fontSize = (18 * (sy(1).value / 1.dp.value)).sp,
            fontWeight = FontWeight.Bold,
            maxLines = 2,
            overflow = TextOverflow.Ellipsis,
            modifier = Modifier
                .align(Alignment.BottomStart)
                .padding(start = sx(12), bottom = sy(12), end = sx(12))
        )
    }
}

/**
 * "Wszystkie" channel — same chipy (BEZ CategoryIcon), 11 pozycji.
 * Layout taki sam jak poprzedni "Skróty v3" + 56px spacing po dolnej krawędzi.
 *
 * focusedColIndex semantyka: 0..10 → chip focused.
 */
@Composable
private fun VodWszystkieRow(
    actualRowIndex: Int,
    focusedRowIndex: Int,
    focusedColIndex: Int,
    channelFocusRequesters: Map<Pair<Int, Int>, FocusRequester>,
    onChannelContentFocusChange: (Int, Int) -> Unit,
    onNavigateToVodGrid: (title: String, prefiltered: List<VodContent>?, sourceSection: String) -> Unit = { _, _, _ -> },
    onNavigateToKinoGrid: (title: String, prefiltered: List<VodContent>?, sourceSection: String) -> Unit = { _, _, _ -> },
    lazyListState: LazyListState,
    sx: (Int) -> androidx.compose.ui.unit.Dp,
    sy: (Int) -> androidx.compose.ui.unit.Dp
) {
    // 11 chipów — pierwszy "Wszystkie" otwiera grid bez filtra
    val categories = remember {
        listOf(
            "Wszystkie" to null,
            "Nowości 🔥" to "__NEW__",
            "Akcja" to "Akcja|Action",
            "Biograficzne" to "Biograficzny|Biography|Biographical",
            "Disney" to "Disney",
            "Dokument" to "Dokumentalny|Documentary",
            "Dramat" to "Dramat|Drama",
            "Familijne" to "Familijny|Family",
            "Filmy polskie" to "Polski|Polish",
            "Gwiezdne Wojny" to "Star Wars|Gwiezdne Wojny",
            "Universal" to "Universal"
        )
    }

    val isCurrentRow = actualRowIndex == focusedRowIndex

    LazyRow(
        state = lazyListState,
        modifier = Modifier
            .fillMaxWidth()
            .height(sy(80)),
        contentPadding = PaddingValues(start = sx(80), end = sx(20)),
        horizontalArrangement = Arrangement.spacedBy(sx(24)),
        verticalAlignment = Alignment.CenterVertically
    ) {
        itemsIndexed(categories) { index, (label, filter) ->
            val isChipFocused = isCurrentRow && focusedColIndex == index
            val focusRequester = channelFocusRequesters[Pair(actualRowIndex, index)] ?: FocusRequester()

            CategoryChip(
                label = label,
                isFocused = isChipFocused,
                focusRequester = focusRequester,
                sx = sx,
                sy = sy,
                onFocusChange = { focused ->
                    if (focused) onChannelContentFocusChange(actualRowIndex, index)
                },
                onClick = {
                    val vodList = VodDataCache.getKinoPlayMovies()
                    val filtered = when {
                        filter == null -> vodList
                        filter == "__NEW__" -> vodList.shuffled().take(10)
                        else -> filterMoviesByCategory(vodList, filter)
                    }
                    onNavigateToKinoGrid(label, filtered, "KINO_PLAY")
                }
            )
        }
    }
}

/**
 * "Więcej" channel — sam CategoryIcon, ENTER → grid wszystkich filmów Kino Play.
 */
@Composable
private fun VodWiecejRow(
    actualRowIndex: Int,
    focusedRowIndex: Int,
    focusedColIndex: Int,
    channelFocusRequesters: Map<Pair<Int, Int>, FocusRequester>,
    onChannelContentFocusChange: (Int, Int) -> Unit,
    onNavigateToKinoGrid: (title: String, prefiltered: List<VodContent>?, sourceSection: String) -> Unit = { _, _, _ -> },
    sx: (Int) -> androidx.compose.ui.unit.Dp,
    sy: (Int) -> androidx.compose.ui.unit.Dp
) {
    val isCurrentRow = actualRowIndex == focusedRowIndex
    val isFocused = isCurrentRow && focusedColIndex == -1
    val focusRequester = channelFocusRequesters[Pair(actualRowIndex, -1)] ?: FocusRequester()

    Row(
        modifier = Modifier.fillMaxWidth().padding(start = sx(80)),
        verticalAlignment = Alignment.CenterVertically
    ) {
        CategoryIcon(
            text = "Więcej",
            isFocused = isFocused,
            onClick = {
                onNavigateToKinoGrid("Wszystkie filmy", null, "KINO_PLAY")
            },
            onFocused = { focused ->
                if (focused) onChannelContentFocusChange(actualRowIndex, -1)
            },
            focusRequester = focusRequester,
            sx = sx,
            sy = sy,
            showIcon = false,
            showBackgroundWhenFocused = true
        )
    }
}

/**
 * Chip-style category button for KinoPlay shortcuts row.
 *
 * Source: Figma "Nowa strona główna BOX" → Kategorie (node 3061:27419)
 *
 * Specs (Figma):
 * - Padding: 16px horizontal, 24px vertical
 * - Border radius: 16px
 * - Background: rgba(0,0,0,0.4) — gradient/black-40%
 * - Border (default): 2px solid rgba(238,238,238,0.2)
 * - Border (focused): 8px solid #5FEDD4 (aqua)
 * - Gap between chips: 24px (handled by parent LazyRow)
 * - Text width: max 170px, ellipsis on overflow
 *
 * Typography (Figma "Caption medium"):
 * - Font: Manrope Medium 24px
 * - Color: #EEEEEE
 * - Letter-spacing: 0.48 (2% of 24px)
 * - Line-height: 32px
 * - Align: center
 */
@Composable
private fun CategoryChip(
    label: String,
    isFocused: Boolean,
    focusRequester: FocusRequester,
    sx: (Int) -> androidx.compose.ui.unit.Dp,
    sy: (Int) -> androidx.compose.ui.unit.Dp,
    onClick: () -> Unit,
    onFocusChange: (Boolean) -> Unit
) {
    // Figma: stroke/stroke-focused (#5FEDD4) when focused, rgba(238,238,238,0.2) otherwise
    val borderColor = if (isFocused) Color(0xFF5FEDD4) else Color(0x33EEEEEE)
    // Figma: stroke/stroke-8 (8px) focused, stroke/stroke-2 (2px) default
    val borderWidth = if (isFocused) sx(8) else sx(2)
    // Figma: radius/radius-16
    val shape = RoundedCornerShape(sx(16))

    Box(
        modifier = Modifier
            .size(sx(202), sy(80))                                      // Figma: chip W=202px, H=80px (fixed)
            .clip(shape)
            .background(Color(0x66000000))                              // Figma: rgba(0,0,0,0.4)
            .border(width = borderWidth, color = borderColor, shape = shape)
            .padding(horizontal = sx(16), vertical = sy(24))            // Figma: px-16 horizontal, py-24 vertical
            .focusRequester(focusRequester)
            .onPreviewKeyEvent { event ->
                if (event.type == KeyEventType.KeyDown &&
                    (event.key == Key.Enter || event.key == Key.DirectionCenter)) {
                    onClick()
                    true
                } else false
            }
            .onFocusChanged { onFocusChange(it.isFocused) }
            .focusable(),
        contentAlignment = Alignment.Center
    ) {
        Text(
            text = label,
            color = Color(0xFFEEEEEE),                       // Figma: text/text-primary #EEE
            fontSize = (24 * sy(1).value).sp,                // Figma: 24px
            fontFamily = ManropeFamily,                      // Figma: family/manrope
            fontWeight = FontWeight.Medium,                  // Figma: weight/medium (500)
            letterSpacing = 0.48.sp,                         // Figma: tracking 0.48
            lineHeight = (32 * sy(1).value).sp,              // Figma: line-height 32
            textAlign = TextAlign.Center,
            maxLines = 1,
            overflow = TextOverflow.Ellipsis,
            modifier = Modifier.widthIn(max = sx(170))       // Figma: max-w 170px
        )
    }
}

@Composable
private fun VodContentCard(
    vodContent: VodContent,
    isFocused: Boolean,
    focusRequester: FocusRequester,
    onFocusChange: () -> Unit,
    sx: (Int) -> androidx.compose.ui.unit.Dp,
    sy: (Int) -> androidx.compose.ui.unit.Dp,
    expiryText: String? = null,
    onClick: () -> Unit = {}
) {
    val itemWidth = sx(220)
    val itemHeight = sy(380)

    val scale by animateFloatAsState(if (isFocused) 1.1f else 1.0f)

    // Real rental expiry (preferred) — falls back to a stable mock day if the movie
    // isn't tracked by RentalManager (legacy "Wypożyczone" mock list / placeholder).
    val rentalExpiresAt = com.uxellence.tv.v3.rental.RentalManager.rentals.value[vodContent.title]
    val realExpiryLabel = remember(rentalExpiresAt) {
        rentalExpiresAt?.let { ts ->
            val sdf = java.text.SimpleDateFormat("EEEE", java.util.Locale("pl"))
            sdf.format(java.util.Date(ts))
        }
    }
    val mockExpiryDay = remember(vodContent.title) {
        val days = listOf("piątek", "sobota", "niedziela", "poniedziałek")
        days[Math.floorMod(vodContent.title.hashCode(), days.size)]
    }
    val expiryDay = realExpiryLabel ?: mockExpiryDay

    Column(
        modifier = Modifier
            .width(itemWidth)
            .height(itemHeight)
            .scale(scale)
            .focusRequester(focusRequester)
            .onFocusChanged { focusState ->
                if (focusState.isFocused) onFocusChange()
            }
            .onPreviewKeyEvent { event ->
                if (event.type == KeyEventType.KeyDown &&
                    (event.key == Key.Enter ||
                        event.key == Key.NumPadEnter ||
                        event.key == Key.DirectionCenter)
                ) {
                    onClick(); true
                } else false
            }
            .focusable(),
        horizontalAlignment = Alignment.CenterHorizontally,
        verticalArrangement = Arrangement.spacedBy(sy(16))
    ) {
        Box(
            modifier = Modifier
                .width(sx(200))
                .height(sy(280))
                .clip(RoundedCornerShape(sx(12)))
                .border(
                    width = if (isFocused) (6 * sx(1).value / 1.dp.value).dp else 0.dp,
                    color = if (isFocused) Color(0xFF5AECD3) else Color.Transparent,
                    shape = RoundedCornerShape(sx(12))
                )
        ) {
            AsyncImage(
                model = vodContent.imageUrl,
                contentDescription = vodContent.title,
                modifier = Modifier.fillMaxSize(),
                contentScale = ContentScale.Crop
            )
        }
        if (isFocused) {
            // Rented overrides everything — even if the parent didn't pass `expiryText`,
            // a real RentalManager entry means we should advertise the watch deadline,
            // not the price. Falls back to expiryText (legacy "Wypożyczone" channel hint)
            // and finally to the movie's price string.
            val labelText = when {
                rentalExpiresAt != null -> "oglądaj do: $expiryDay"
                expiryText != null -> "oglądaj do: $expiryDay"
                else -> vodContent.price ?: "Wypożycz"
            }
            Text(
                text = labelText,
                color = Color(0xFFEEEEEE),
                fontSize = (20 * (sy(1).value / 1.dp.value)).sp,
                fontWeight = FontWeight.W700,
                letterSpacing = 0.4.sp
            )
        }
    }
}

