@Composable
private fun Top10ContentCard(
    vodContent: VodContent,
    rankingNumber: Int,
    isFocused: Boolean,
    focusRequester: FocusRequester,
    onFocusChange: () -> Unit,
    sx: (Int) -> androidx.compose.ui.unit.Dp,
    sy: (Int) -> androidx.compose.ui.unit.Dp
) {
    val itemWidth = sx(261)
    val itemHeight = sy(324)

    val scale by animateFloatAsState(if (isFocused) 1.1f else 1.0f)

    // Mapowanie numeru na drawable resource
    val rankingDrawable = when (rankingNumber) {
        1 -> R.drawable.top10_1
        2 -> R.drawable.top10_2
        3 -> R.drawable.top10_3
        4 -> R.drawable.top10_4
        5 -> R.drawable.top10_5
        6 -> R.drawable.top10_6
        7 -> R.drawable.top10_7
        8 -> R.drawable.top10_8
        9 -> R.drawable.top10_9
        10 -> R.drawable.top10_10
        else -> null
    }

    Box(
        modifier = Modifier
            .width(itemWidth)
            .height(itemHeight)
            .scale(scale)
            .focusRequester(focusRequester)
            .onFocusChanged { focusState ->
                if (focusState.isFocused) onFocusChange()
            }
            .focusable()
    ) {
        // Duży numer rankingu po lewej
        if (rankingDrawable != null) {
            Icon(
                painter = painterResource(id = rankingDrawable),
                contentDescription = "Ranking $rankingNumber",
                modifier = Modifier
                    .align(Alignment.TopStart)
                    .size(sx(61), sy(115)),
                tint = if (isFocused) Color(0xFF5AECD3) else Color(0xFFEEEEEE)
            )
        }

        // Kolumna z plakatem i tekstem po prawej (left: 61px)
        Column(
            modifier = Modifier
                .align(Alignment.TopEnd)
                .width(sx(200)),
            horizontalAlignment = Alignment.CenterHorizontally,
            verticalArrangement = Arrangement.spacedBy(sy(16))
        ) {
            // Plakat 200x280px
            Box(
                modifier = Modifier
                    .width(sx(200))
                    .height(sy(280))
                    .clip(RoundedCornerShape(sx(12)))
                    .border(
                        width = if (isFocused) (6 * sx(1).value / 1.dp.value).dp else 0.dp,
                        color = if (isFocused) Color(0xFF5AECD3) else Color.Transparent,
                        shape = RoundedCornerShape(sx(12))
                    )
            ) {
                AsyncImage(
                    model = vodContent.imageUrl,
                    contentDescription = vodContent.title,
                    modifier = Modifier.fillMaxSize(),
                    contentScale = ContentScale.Crop
                )
            }

            // Label (tylko gdy jest fokus): rental status overrides price.
            if (isFocused) {
                val rentalExpiresAt = com.uxellence.tv.v3.rental.RentalManager.rentals.value[vodContent.title]
                val labelText = if (rentalExpiresAt != null) {
                    val sdf = java.text.SimpleDateFormat("EEEE", java.util.Locale("pl"))
                    "oglądaj do: ${sdf.format(java.util.Date(rentalExpiresAt))}"
                } else {
                    vodContent.price ?: "Wypożycz"
                }
                Text(
                    text = labelText,
                    textAlign = TextAlign.Center,
                    color = Color(0xFFEEEEEE),
                    fontSize = (20 * (sy(1).value / 1.dp.value)).sp,
                    fontWeight = FontWeight.W700,
                    letterSpacing = 0.4.sp
                )
            }
        }
    }
}

// VOD Screen spacing constants
private const val VOD_FIXED_FOCUS_Y = 340 // Focused channel always at this height
// Vertical posters (Kino Play, Polecane, Top 10, Ostatnio dodane wideo) - large spacing
private const val VOD_VERTICAL_NORMAL_ROW_HEIGHT = 346 // CategoryIcon (216px) + spacing (130px)
private const val VOD_VERTICAL_EXPANDED_ROW_HEIGHT = 636 // CategoryIcon (216px) + miniatures (290px) + spacing (130px)
// Horizontal miniatures (Seriale, Filmy fabularne, Cinemax) - small spacing like MOJE
private const val VOD_HORIZONTAL_NORMAL_ROW_HEIGHT = 256 // CategoryIcon (216px) + spacing (40px)
private const val VOD_HORIZONTAL_EXPANDED_ROW_HEIGHT = 546 // CategoryIcon (216px) + miniatures (290px) + spacing (40px)
private const val VOD_CONTENT_FOCUS_EXTRA_SPACING = 100 // Extra spacing above focused content row

private fun calculateVodChannelYPosition(
    channelIndex: Int,
    channelName: String,
    focusedRowIndex: Int,
    focusedColIndex: Int,
    channels: List<String>,
    sy: (Int) -> androidx.compose.ui.unit.Dp,
    firstChannelBaseY: Int = 280,
    sliderRowIndex: Int = 1  // V1 = 2 (Wypożyczone above slider)
): androidx.compose.ui.unit.Dp {
    // V1: Wypożyczone (channelIndex 0) renders ABOVE the slider; slider has been pushed
    // down by `sliderTopOffset` (see VodLayoutWithSlider). Other channels (1+) sit below
    // the slider as in V2 but their entire stack is offset down by sliderTopOffset.
    val isV1 = sliderRowIndex == 2
    val sliderTopOffset = if (isV1) 280 else 0
    val isWypozyczoneAboveSlider = isV1 && channelIndex == 0

    if (isWypozyczoneAboveSlider) {
        // Focused → fixed focus Y; otherwise tucked at top above slider.
        return if (focusedRowIndex == 1) sy(VOD_FIXED_FOCUS_Y) else sy(40)
    }

    // Convert channelIndex to rowIndex.
    // V2: channelIndex N → row N+2.
    // V1 (channelIndex>=1): channelIndex N → row N+2 (slider takes the gap on row 2).
    val rowIndex = channelIndex + 2

    // Determine if channel is horizontal, vertical, Wszystkie (chipy + CategoryIcon), or Więcej
    val isHorizontal = channelName in emptyList<String>() // No horizontal channels anymore - all use vertical posters
    val isShortcutsV3 = channelName == "Wszystkie"  // (zmienna name retained for diff readability)
    val isWiecej = channelName == "Więcej"

    val normalRowHeight = when {
        isHorizontal -> VOD_HORIZONTAL_NORMAL_ROW_HEIGHT
        isShortcutsV3 -> 136  // CategoryIcon 216 + spacing 40
        isWiecej -> 256       // CategoryIcon "Więcej" + spacing
        else -> VOD_VERTICAL_NORMAL_ROW_HEIGHT
    }

    val expandedRowHeight = when {
        isHorizontal -> VOD_HORIZONTAL_EXPANDED_ROW_HEIGHT
        isShortcutsV3 -> 136
        isWiecej -> 256
        else -> VOD_VERTICAL_EXPANDED_ROW_HEIGHT
    }

    return when {
        // When on menu (row 0), Wypożyczone-V1 (row 1) or slider (row sliderRowIndex)
        focusedRowIndex <= sliderRowIndex -> {
            // Calculate cumulative height for all channels above this one.
            // 926 = slider bottom (742px) + spacing (184px) in V2; offset by sliderTopOffset
            // in V1 (slider has been pushed down to make room for Wypożyczone).
            var cumulativeHeight = 926 + sliderTopOffset
            // V1: skip channelIndex 0 (Wypożyczone) — it's painted above the slider, not
            // in the stack below. V2: count from 0 as before.
            val startIndex = if (isV1) 1 else 0
            for (i in startIndex until channelIndex) {
                val prevChannelName = channels.getOrNull(i) ?: ""
                val prevIsHorizontal = prevChannelName in emptyList<String>()
                val prevIsShortcutsV3 = prevChannelName == "Wszystkie"
                val prevIsWiecej = prevChannelName == "Więcej"
                cumulativeHeight += when {
                    prevIsHorizontal -> VOD_HORIZONTAL_NORMAL_ROW_HEIGHT
                    prevIsShortcutsV3 -> 136
                    prevIsWiecej -> 256
                    else -> VOD_VERTICAL_NORMAL_ROW_HEIGHT
                }
            }
            sy(cumulativeHeight)
        }
        // Focused channel - always at Y: 340px (VOD_FIXED_FOCUS_Y)
        rowIndex == focusedRowIndex -> {
            sy(VOD_FIXED_FOCUS_Y)
        }
        // Channels above focused - scroll up
        rowIndex < focusedRowIndex -> {
            // Extra 100px spacing when content is focused (focusedColIndex >= 0); pomijamy dla Skróty v3 (no expansion)
            val focusedChannelName = channels.getOrNull(focusedRowIndex - 2) ?: ""
            val focusedIsShortcutsV3 = focusedChannelName == "Wszystkie"
            val focusedIsWiecej = focusedChannelName == "Więcej"
            val extraSpacing = if (focusedColIndex >= 0 && !focusedIsShortcutsV3 && !focusedIsWiecej) VOD_CONTENT_FOCUS_EXTRA_SPACING else 0
            // Calculate cumulative height from focused to this channel
            // Subtract heights of channels FROM current TO (focused-1), inclusive of current channel itself
            var cumulativeHeight = VOD_FIXED_FOCUS_Y
            for (i in channelIndex until focusedRowIndex - 2) {
                val betweenChannelName = channels.getOrNull(i) ?: ""  // FIX: było channels[i+1] (skipowało własną wysokość, brało focusedRow)
                val betweenIsHorizontal = betweenChannelName in emptyList<String>() // No horizontal channels anymore - all use vertical posters
                val betweenIsShortcutsV3 = betweenChannelName == "Wszystkie"
                val betweenIsWiecej = betweenChannelName == "Więcej"
                cumulativeHeight -= when {
                    betweenIsHorizontal -> VOD_HORIZONTAL_NORMAL_ROW_HEIGHT
                    betweenIsShortcutsV3 -> 136
                    betweenIsWiecej -> 256
                    else -> VOD_VERTICAL_NORMAL_ROW_HEIGHT
                }
            }
            sy(cumulativeHeight - extraSpacing)
        }
        // Channels below focused - scroll down to make room
        rowIndex > focusedRowIndex -> {
            // Check if focused channel is expanded (content focused)
            val focusedChannelName = channels.getOrNull(focusedRowIndex - 2) ?: ""
            val focusedIsHorizontal = focusedChannelName in emptyList<String>() // No horizontal channels anymore - all use vertical posters
            val focusedIsShortcutsV3 = focusedChannelName == "Wszystkie"
            val focusedIsWiecej = focusedChannelName == "Więcej"
            val focusedChannelExpansion = if (focusedColIndex >= 0) {
                when {
                    focusedIsHorizontal -> VOD_HORIZONTAL_EXPANDED_ROW_HEIGHT
                    focusedIsShortcutsV3 -> 136
                    focusedIsWiecej -> 256
                    else -> VOD_VERTICAL_EXPANDED_ROW_HEIGHT
                }
            } else {
                when {
                    focusedIsHorizontal -> VOD_HORIZONTAL_NORMAL_ROW_HEIGHT
                    focusedIsShortcutsV3 -> 136
                    focusedIsWiecej -> 256
                    else -> VOD_VERTICAL_NORMAL_ROW_HEIGHT
                }
            }
            // 30px extra spacing for vertical channels when content is focused; pomijamy dla Wszystkie/Więcej (no expansion)
            val verticalExtraSpacing = if (!focusedIsHorizontal && !focusedIsShortcutsV3 && !focusedIsWiecej && focusedColIndex >= 0) 30 else 0
            // Calculate cumulative height from focused to this channel
            var cumulativeHeight = VOD_FIXED_FOCUS_Y + focusedChannelExpansion + verticalExtraSpacing
            for (i in (focusedRowIndex - 2 + 1) until channelIndex) {
                val betweenChannelName = channels.getOrNull(i) ?: ""
                val betweenIsHorizontal = betweenChannelName in emptyList<String>() // No horizontal channels anymore - all use vertical posters
                val betweenIsShortcutsV3 = betweenChannelName == "Wszystkie"
                val betweenIsWiecej = betweenChannelName == "Więcej"
                cumulativeHeight += when {
                    betweenIsHorizontal -> VOD_HORIZONTAL_NORMAL_ROW_HEIGHT
                    betweenIsShortcutsV3 -> 136
                    betweenIsWiecej -> 256
                    else -> VOD_VERTICAL_NORMAL_ROW_HEIGHT
                }
            }
            sy(cumulativeHeight)
        }
        // Fallback (should not happen)
        else -> sy(140 + rowIndex * normalRowHeight)
    }
}

// Helper to detect if channel uses chip-row layout (Wszystkie — chips obok CategoryIcon)
private fun isShortcutsV3Channel(rowIndex: Int, channels: List<String>): Boolean {
    val channelIndex = rowIndex - 2
    return channels.getOrNull(channelIndex) == "Wszystkie"
}

fun handleVodNavigation(
    event: KeyEvent,
    focusedRowIndex: Int,
    focusedColIndex: Int,
    onFocusChange: (Int, Int) -> Unit,
    channelFocusRequesters: Map<Pair<Int, Int>, FocusRequester>,
    channels: List<String>,
    lazyListStates: Map<Int, LazyListState>,
    coroutineScope: CoroutineScope,
    gridContent: Map<String, List<VodContent>>,
    onReturnToMenu: () -> Unit,
    // V4 slider button navigation (optional - only used when sliderVersion == 4)
    sliderVersion: Int = 2,
    v4ButtonIndex: Int = 0,
    onV4ButtonIndexChange: (Int) -> Unit = {},
    // VOD Player navigation (legacy — używane gdy nie chcemy MovieDetail)
    onNavigateToVodPlayer: (url: String, title: String) -> Unit = { _, _ -> },
    // Wywoływany gdy ENTER na CategoryIcon (kanał) — np. "Akcja" → otwórz grid filmów akcji
    onCategoryEnter: (channelName: String) -> Unit = {},
    // Wywoływany gdy ENTER na plakacie filmu — otwórz MovieDetailScreen
    onMovieClicked: (VodContent) -> Unit = {},
    // Slider's row index in focus indexing — 1 in V2 (default), 2 in V1 (Wypożyczone above)
    sliderRowIndex: Int = 1
): Boolean {
    // Helpers — channel index ↔ row mapping that respects sliderRowIndex.
    // V1 puts Wypożyczone (channelIndex 0) on row 1 and slider on row 2; channelIndex 1+
    // map to rows 3+. V2 keeps the simple `+ 2` shift.
    fun rowToChannelIndex(row: Int): Int =
        if (sliderRowIndex == 2 && row == 1) 0 else row - 2
    fun channelIndexToRow(idx: Int): Int =
        if (sliderRowIndex == 2 && idx == 0) 1 else idx + 2
    if (event.nativeKeyEvent.action != android.view.KeyEvent.ACTION_DOWN) return false

    when (event.key) {
        Key.DirectionUp -> {
            android.util.Log.d("VOD_NAV", "UP pressed: focusedRowIndex=$focusedRowIndex, focusedColIndex=$focusedColIndex, sliderRowIndex=$sliderRowIndex, sliderVersion=$sliderVersion, v4ButtonIndex=$v4ButtonIndex")
            when {
                focusedRowIndex == sliderRowIndex -> {
                    // Slider focused — V4: toggle button before exiting upward
                    if (sliderVersion == 4 && v4ButtonIndex > 0) {
                        onV4ButtonIndexChange(0)
                        return true
                    }
                    // From slider go up — V2: to menu, V1: to row above slider (Wypożyczone)
                    if (sliderRowIndex == 1) {
                        onReturnToMenu()
                    } else {
                        onFocusChange(1, -1)
                        channelFocusRequesters[Pair(1, -1)]?.requestFocus()
                    }
                }
                focusedRowIndex == 1 && sliderRowIndex == 2 -> {
                    // V1: Wypożyczone (above slider) UP → menu
                    if (focusedColIndex == -1) {
                        onReturnToMenu()
                    } else {
                        onFocusChange(1, -1)
                        channelFocusRequesters[Pair(1, -1)]?.requestFocus()
                    }
                }
                focusedRowIndex == sliderRowIndex + 1 -> {
                    // First channel below slider
                    if (focusedColIndex == -1) {
                        onFocusChange(sliderRowIndex, 0)
                    } else {
                        onFocusChange(focusedRowIndex, -1)
                        channelFocusRequesters[Pair(focusedRowIndex, -1)]?.requestFocus()
                    }
                }
                focusedRowIndex > sliderRowIndex + 1 -> {
                    val newRowIndex = focusedRowIndex - 1
                    val currentIsShortcutsV3 = isShortcutsV3Channel(focusedRowIndex, channels)
                    val targetIsShortcutsV3 = isShortcutsV3Channel(newRowIndex, channels)

                    val targetColIndex = when {
                        targetIsShortcutsV3 -> 0
                        currentIsShortcutsV3 -> -1
                        focusedColIndex == -1 -> -1
                        else -> 0
                    }

                    onFocusChange(newRowIndex, targetColIndex)
                    channelFocusRequesters[Pair(newRowIndex, targetColIndex)]?.requestFocus()
                }
            }
            return true
        }

        Key.DirectionDown -> {
            android.util.Log.d("VOD_NAV", "DOWN pressed: focusedRowIndex=$focusedRowIndex, sliderRowIndex=$sliderRowIndex, sliderVersion=$sliderVersion, v4ButtonIndex=$v4ButtonIndex")
            when {
                focusedRowIndex == sliderRowIndex -> {
                    // V4 slider: DOWN switches between buttons before going to channels
                    if (sliderVersion == 4 && v4ButtonIndex < 1) {
                        onV4ButtonIndexChange(1)
                        return true
                    }
                    if (sliderVersion == 4) {
                        onV4ButtonIndexChange(0)
                    }
                    val nextRow = sliderRowIndex + 1
                    onFocusChange(nextRow, -1)
                    channelFocusRequesters[Pair(nextRow, -1)]?.requestFocus()
                }
                focusedRowIndex == 1 && sliderRowIndex == 2 -> {
                    // V1: Wypożyczone (above slider) DOWN → slider
                    onFocusChange(sliderRowIndex, 0)
                }
                focusedRowIndex < channels.size + 1 -> {
                    // Between channels - smart targeting for Skróty v3
                    val newRowIndex = focusedRowIndex + 1
                    val currentIsShortcutsV3 = isShortcutsV3Channel(focusedRowIndex, channels)
                    val targetIsShortcutsV3 = isShortcutsV3Channel(newRowIndex, channels)

                    val targetColIndex = when {
                        targetIsShortcutsV3 -> 0 // Go to first shortcut (no CategoryIcon)
                        currentIsShortcutsV3 -> -1 // Coming from shortcuts, go to CategoryIcon
                        focusedColIndex == -1 -> -1 // Preserve CategoryIcon
                        else -> 0 // Preserve content
                    }

                    onFocusChange(newRowIndex, targetColIndex)
                    channelFocusRequesters[Pair(newRowIndex, targetColIndex)]?.requestFocus()
                }
            }
            return true
        }

        Key.DirectionLeft -> {
            if (focusedRowIndex == sliderRowIndex) {
                // Slider navigation handled by VodHeroSlider
                return false
            }

            // Special handling for Skróty v3
            val isShortcutsV3 = isShortcutsV3Channel(focusedRowIndex, channels)

            if (isShortcutsV3) {
                // Shortcuts v3: move between items 0-5
                when {
                    focusedColIndex > 0 -> {
                        // Move left within shortcuts
                        onFocusChange(focusedRowIndex, focusedColIndex - 1)
                        channelFocusRequesters[Pair(focusedRowIndex, focusedColIndex - 1)]?.requestFocus()
                    }
                    focusedColIndex == 0 -> {
                        // At first shortcut - can't go left (no CategoryIcon)
                        return true
                    }
                }
            } else {
                // Regular channel logic
                if (focusedColIndex == -1) {
                    // Already on CategoryIcon
                    return true
                } else if (focusedColIndex == 0) {
                    // Check if can scroll left
                    val channelIndex = rowToChannelIndex(focusedRowIndex)
                    val lazyListState = lazyListStates[channelIndex]
                    if (lazyListState != null && lazyListState.firstVisibleItemIndex > 0) {
                        coroutineScope.launch {
                            val newIndex = lazyListState.firstVisibleItemIndex - 1
                            lazyListState.animateScrollToItem(newIndex)
                            delay(50)
                            channelFocusRequesters[Pair(focusedRowIndex, newIndex)]?.requestFocus()
                        }
                    } else {
                        onFocusChange(focusedRowIndex, -1)
                        channelFocusRequesters[Pair(focusedRowIndex, -1)]?.requestFocus()
                    }
                }
            }
            return true
        }

        Key.DirectionRight -> {
            if (focusedRowIndex == sliderRowIndex) {
                // Slider navigation handled by VodHeroSlider
                return false
            }

            val isShortcutsV3 = isShortcutsV3Channel(focusedRowIndex, channels)

            if (isShortcutsV3) {
                val maxColIndex = (channelFocusRequesters.keys
                    .filter { it.first == focusedRowIndex }
                    .maxOfOrNull { it.second } ?: 0)
                if (focusedColIndex < maxColIndex) {
                    onFocusChange(focusedRowIndex, focusedColIndex + 1)
                    channelFocusRequesters[Pair(focusedRowIndex, focusedColIndex + 1)]?.requestFocus()
                }
            } else {
                if (focusedColIndex == -1) {
                    onFocusChange(focusedRowIndex, 0)
                    channelFocusRequesters[Pair(focusedRowIndex, 0)]?.requestFocus()
                } else if (focusedColIndex == 0) {
                    val channelIndex = rowToChannelIndex(focusedRowIndex)
                    val lazyListState = lazyListStates[channelIndex]
                    val channelName = channels.getOrNull(channelIndex)
                    val channelContent = gridContent[channelName] ?: emptyList()

                    if (lazyListState != null && lazyListState.firstVisibleItemIndex < channelContent.size - 1) {
                        coroutineScope.launch {
                            val newIndex = lazyListState.firstVisibleItemIndex + 1
                            lazyListState.animateScrollToItem(newIndex)
                            delay(50)
                            channelFocusRequesters[Pair(focusedRowIndex, newIndex)]?.requestFocus()
                        }
                    }
                }
            }
            return true
        }

        Key.Enter, Key.DirectionCenter -> {
            if (focusedRowIndex == sliderRowIndex) {
                // Slider — delegate to VodHeroSlider
                return false
            }

            // Channel row — find focused item and open MovieDetail / category grid
            if (focusedColIndex < 0) {
                val channelIndex = rowToChannelIndex(focusedRowIndex)
                val channelName = channels.getOrNull(channelIndex) ?: return true
                onCategoryEnter(channelName)
                return true
            }

            val channelIndex = rowToChannelIndex(focusedRowIndex)
            val channelName = channels.getOrNull(channelIndex) ?: return true
            val rowContent = gridContent[channelName]
            // Channels bez content (np. "Skróty v3") — deleguj ENTER do child composable (np. ShortcutCard.onClick)
            if (rowContent.isNullOrEmpty()) return false

            val lazyListState = lazyListStates[channelIndex]
            val itemIndex = (lazyListState?.firstVisibleItemIndex ?: 0) + focusedColIndex
            val item = rowContent.getOrNull(itemIndex)

            if (item != null) {
                android.util.Log.d("VOD_NAV", "OK pressed on '${item.title}' → MovieDetailScreen")
                onMovieClicked(item)
            }
            return true
        }

        else -> return false
    }
}

@OptIn(ExperimentalComposeUiApi::class)
@Composable
fun VodFullscreenSlider(
    sx: (Int) -> androidx.compose.ui.unit.Dp,
    sy: (Int) -> androidx.compose.ui.unit.Dp
) {
    var currentSlide by remember { mutableStateOf(0) }
    var currentFocusArea by remember { mutableStateOf(VodFocusArea.MAIN_CONTENT) }
    val focusRequester = remember { FocusRequester() }
    
    val sliderItems = remember {
        listOf(
            VodSlideData(
