/**
 * User profile data model
 */
private data class UserProfile(
    val id: String,
    val name: String,
    val avatarType: ProfileAvatarType,
    val avatarContent: String // letter, icon name, or "kids"
)

/**
 * Avatar type variants
 */
private sealed class ProfileAvatarType {
    data object Letter : ProfileAvatarType()      // Single letter with color
    data object Icon : ProfileAvatarType()        // Icon image (monster, pokemon)
    data object Kids : ProfileAvatarType()        // Gradient with "Dzieci" text
}

/**
 * Profile Avatar composable
 * Renders different avatar types: Letter, Icon, Kids gradient
 */
@Composable
private fun ProfileAvatar(
    profile: UserProfile,
    isFocused: Boolean,
    onClick: () -> Unit,
    sx: (Int) -> Dp,
    sy: (Int) -> Dp
) {
    val avatarSize = sx(216)
    val focusBorderColor = Color(0xFF5AECD3) // aqua
    val avatarBgColor = Color(0x33EEEEEE) // 20% white
    val letterColor = Color(0xFFE2AE29) // yellow for letters

    // Focus managed by parent - no individual focusable (Focus Architect pattern)
    Column(
        horizontalAlignment = Alignment.CenterHorizontally
    ) {
        // Avatar circle
        Box(
            modifier = Modifier
                .size(avatarSize)
                .then(
                    if (isFocused) {
                        Modifier.border(
                            width = 4.dp,
                            color = focusBorderColor,
                            shape = CircleShape
                        )
                    } else Modifier
                )
                .then(
                    when (profile.avatarType) {
                        is ProfileAvatarType.Kids -> Modifier.background(
                            brush = Brush.linearGradient(
                                colors = listOf(Color(0xFFF0B71C), Color(0xFFE61BCF))
                            ),
                            shape = CircleShape
                        )
                        else -> Modifier.background(
                            color = avatarBgColor,
                            shape = CircleShape
                        )
                    }
                ),
            contentAlignment = Alignment.Center
        ) {
            when (profile.avatarType) {
                is ProfileAvatarType.Letter -> {
                    Text(
                        text = profile.avatarContent,
                        color = letterColor,
                        fontSize = (88 * sy(1).value / 1).sp,  // Figma: 88px
                        fontWeight = FontWeight.Medium
                    )
                }
                is ProfileAvatarType.Icon -> {
                    when (profile.avatarContent) {
                        "monster" -> {
                            // Angelika — lampka Pixar
                            androidx.compose.foundation.Image(
                                painter = androidx.compose.ui.res.painterResource(id = R.drawable.av_pixar_lamp),
                                contentDescription = profile.name,
                                modifier = Modifier.size(sx(120))
                            )
                        }
                        else -> {
                            Icon(
                                imageVector = when (profile.avatarContent) {
                                    "pokemon" -> Icons.Default.Info
                                    else -> Icons.Default.Person
                                },
                                contentDescription = profile.name,
                                tint = Color(0xFFEEEEEE),
                                modifier = Modifier.size(sx(96))
                            )
                        }
                    }
                }
                is ProfileAvatarType.Kids -> {
                    Text(
                        text = "Dzieci",
                        color = Color.White,
                        fontSize = (32 * sy(1).value / 1).sp,  // Figma: 32px
                        fontWeight = FontWeight.Bold
                    )
                }
            }
        }

        Spacer(modifier = Modifier.height(sy(16)))

        // Profile name - Figma: 28px
        Text(
            text = if (profile.name.length > 15) "${profile.name.take(15)}..." else profile.name,
            color = Color(0xFFEEEEEE),
            fontSize = (28 * sy(1).value / 1).sp,  // Figma: 28px
            fontWeight = FontWeight.Medium,
            maxLines = 1,
            overflow = TextOverflow.Ellipsis
        )
    }
}

/**
 * Profile action button (Nowy profil / Edytuj profile)
 */
@Composable
private fun ProfileActionButton(
    text: String,
    icon: androidx.compose.ui.graphics.vector.ImageVector,
    isFocused: Boolean,
    isPrimary: Boolean, // true = aqua, false = gray
    onClick: () -> Unit,
    sx: (Int) -> Dp,
    sy: (Int) -> Dp
) {
    val aquaColor = Color(0xFF5AECD3)
    val purpleColor = Color(0xFF48227C)
    val grayBgColor = Color(0x33EEEEEE) // 20% white

    val backgroundColor = when {
        isFocused -> aquaColor
        isPrimary -> aquaColor
        else -> grayBgColor
    }

    val contentColor = when {
        isFocused -> purpleColor
        isPrimary -> purpleColor
        else -> Color(0xFFEEEEEE)
    }

    // Focus managed by parent - no individual focusable (Focus Architect pattern)
    Row(
        modifier = Modifier
            .height(sy(72))
            .background(
                color = backgroundColor,
                shape = RoundedCornerShape(sx(8))
            )
            .padding(horizontal = sx(32)),
        verticalAlignment = Alignment.CenterVertically,
        horizontalArrangement = Arrangement.spacedBy(sx(12))
    ) {
        Icon(
            imageVector = icon,
            contentDescription = text,
            tint = contentColor,
            modifier = Modifier.size(sx(24))
        )
        Text(
            text = text,
            color = contentColor,
            fontSize = (24 * sy(1).value / 1).sp,  // Figma: 24px
            fontWeight = FontWeight.Bold
        )
    }
}

/**
 * Profile section - "Kto ogląda?" screen
 * Figma design node: 908:7954
 *
 * Layout:
 * - Row 0: 4 profile avatars
 * - Row 1: 2 action buttons (Nowy profil, Edytuj profile)
 *
 * Navigation:
 * - LEFT/RIGHT: move within row
 * - UP/DOWN: switch between rows
 * - ENTER: select profile or button action
 * - BACK: return to menu
 */
@Composable
private fun ProfileScreenContent(
    globalFocusState: MutableState<GlobalFocusState>,
    onPrepareReturnFocus: () -> Unit = {},  // Set button focus state BEFORE returning
    onProfileSelected: (UserProfile) -> Unit = {},
    sx: (Int) -> Dp,
    sy: (Int) -> Dp
) {
    // Profiles: Piotr (selected), Angelika, Dzieci - 3 profiles
    val profiles = remember {
        listOf(
            UserProfile("1", "Piotr", ProfileAvatarType.Letter, "P"),        // Selected profile
            UserProfile("2", "Angelika", ProfileAvatarType.Icon, "monster"),
            UserProfile("kids", "Dzieci", ProfileAvatarType.Kids, "kids")
        )
    }

    // Focus state: row (-1=none, 0=profiles, 1=buttons), column (0-2 for profiles, 0-1 for buttons)
    // Start with -1 = nothing focused until user presses DOWN or OK
    var focusedRow by remember { mutableIntStateOf(-1) }
    var focusedCol by remember { mutableIntStateOf(0) }

    // Single FocusRequester for the main container (Focus Architect pattern)
    val mainFocusRequester = remember { FocusRequester() }

    // Auto-focus first avatar when entering content
    LaunchedEffect(globalFocusState.value.currentRow) {
        if (globalFocusState.value.currentRow > 0 && globalFocusState.value.sectionId == "PROFILE") {
            delay(150)
            mainFocusRequester.requestFocus()
            // Automatically focus first avatar when entering PROFILE section
            focusedRow = 0
            focusedCol = 0
        }
    }

    Box(
        modifier = Modifier
            .fillMaxSize()
            .background(Color(0xFF281443)) // purple background
            .focusRequester(mainFocusRequester)
            .focusable()
            .onPreviewKeyEvent { event ->
                if (event.type != KeyEventType.KeyDown) return@onPreviewKeyEvent false

                when (event.key) {
                    Key.DirectionLeft -> {
                        if (focusedRow >= 0 && focusedCol > 0) {
                            focusedCol--
                        }
                        true
                    }
                    Key.DirectionRight -> {
                        if (focusedRow >= 0) {
                            val maxCol = if (focusedRow == 0) profiles.size - 1 else 1
                            if (focusedCol < maxCol) {
                                focusedCol++
                            }
                        }
                        true
                    }
                    Key.DirectionUp -> {
                        when {
                            focusedRow == 1 -> {
                                focusedRow = 0
                                focusedCol = focusedCol.coerceAtMost(profiles.size - 1)
                            }
                            focusedRow == 0 -> {
                                // Return to menu when pressing UP from avatars
                                focusedRow = -1
                                onPrepareReturnFocus()
                                globalFocusState.value = GlobalFocusManager.returnToMenu(globalFocusState.value)
                            }
                        }
                        true
                    }
                    Key.DirectionDown -> {
                        when {
                            focusedRow == -1 -> {
                                // First activation - focus first avatar
                                focusedRow = 0
                                focusedCol = 0
                            }
                            focusedRow == 0 -> {
                                focusedRow = 1
                                focusedCol = focusedCol.coerceAtMost(1)
                            }
                        }
                        true
                    }
                    Key.Enter, Key.NumPadEnter, Key.DirectionCenter -> {
                        when {
                            focusedRow == -1 -> {
                                // First activation via OK - focus first avatar
                                focusedRow = 0
                                focusedCol = 0
                            }
                            focusedRow == 0 && focusedCol in profiles.indices -> {
                                onProfileSelected(profiles[focusedCol])
                            }
                            focusedRow == 1 -> {
                                when (focusedCol) {
                                    0 -> { /* TODO: Nowy profil */ }
                                    1 -> { /* TODO: Edytuj profile */ }
                                }
                            }
                        }
                        true
                    }
                    Key.Back -> {
                        onPrepareReturnFocus()
                        globalFocusState.value = GlobalFocusManager.returnToMenu(globalFocusState.value)
                        true
                    }
                    else -> false
                }
            },
        contentAlignment = Alignment.TopCenter
    ) {
        Column(
            horizontalAlignment = Alignment.CenterHorizontally,
            modifier = Modifier.fillMaxSize()
        ) {
            // Top padding - 340px (raised by 80px from 420)
            Spacer(modifier = Modifier.height(sy(340)))

            // Title "Kto ogląda?" - 60px
            Text(
                text = "Kto ogląda?",
                color = Color(0xFFEEEEEE),
                fontSize = (60 * sy(1).value / 1).sp,  // 60px
                fontWeight = FontWeight.Medium
            )

            // Gap: title → profiles
            Spacer(modifier = Modifier.height(sy(64)))

            // Row of profile avatars (3 profiles)
            Row(
                horizontalArrangement = Arrangement.spacedBy(sx(40)),
                verticalAlignment = Alignment.Top
            ) {
                profiles.forEachIndexed { index, profile ->
                    ProfileAvatar(
                        profile = profile,
                        isFocused = focusedRow == 0 && focusedCol == index,
                        onClick = { onProfileSelected(profile) },
                        sx = sx,
                        sy = sy
                    )
                }
            }

            // Gap: profiles → buttons
            Spacer(modifier = Modifier.height(sy(112)))

            // Action buttons row
            Row(
                horizontalArrangement = Arrangement.spacedBy(sx(24)),
                verticalAlignment = Alignment.CenterVertically
            ) {
                // "Nowy profil" button (default gray, aqua only when focused)
                ProfileActionButton(
                    text = "Nowy profil",
                    icon = Icons.Default.Add,
                    isFocused = focusedRow == 1 && focusedCol == 0,
                    isPrimary = false,
                    onClick = { /* TODO: Navigate to new profile screen */ },
                    sx = sx,
                    sy = sy
                )

                // "Edytuj profile" button (secondary - gray)
                ProfileActionButton(
                    text = "Edytuj profile",
                    icon = Icons.Default.Settings, // Using Settings as pencil placeholder
                    isFocused = focusedRow == 1 && focusedCol == 1,
                    isPrimary = false,
                    onClick = { /* TODO: Navigate to edit profiles screen */ },
                    sx = sx,
                    sy = sy
                )
            }
        }
    }
}

@Composable
private fun AccountScreenContent(
    globalFocusState: MutableState<GlobalFocusState>,
    onNavigateToStartupMode: () -> Unit,
    onPrepareReturnFocus: () -> Unit = {},  // Set button focus state BEFORE returning
    sx: (Int) -> Dp,
    sy: (Int) -> Dp,
    availableUpdate: com.uxellence.tv.v3.update.AppUpdateInfo? = null,
    updateState: com.uxellence.tv.v3.update.UpdateState = com.uxellence.tv.v3.update.UpdateState.READY,
    onUpdateDownload: (com.uxellence.tv.v3.update.AppUpdateInfo) -> Unit = {},
    onUpdateInstall: () -> Unit = {},
    onDismissUpdateBadge: () -> Unit = {}
) {
    var resetTrigger by remember { mutableStateOf(0) }

    // Reset when returning to menu
    LaunchedEffect(globalFocusState.value.currentRow) {
        if (globalFocusState.value.currentRow == 0 && globalFocusState.value.sectionId == "ACCOUNT") {
            resetTrigger++
        }
    }

    AccountChannelsScreen(
        onReturnToMenu = {
            // Set button focus state FIRST to prevent "through Start" flash
            onPrepareReturnFocus()
            // Then return to menu
            globalFocusState.value = globalFocusState.value.copy(
                currentRow = 0,
                isActive = true
            )
        },
        onNavigateToStartupMode = onNavigateToStartupMode,
        shouldAutoFocus = globalFocusState.value.sectionId == "ACCOUNT" && globalFocusState.value.currentRow > 0,
        sx = sx,
        sy = sy,
        resetTrigger = resetTrigger,
        availableUpdate = availableUpdate,
        updateState = updateState,
        onUpdateDownload = onUpdateDownload,
        onUpdateInstall = onUpdateInstall,
        onDismissUpdateBadge = onDismissUpdateBadge
    )
}

/**
 * Focus levels for Account section
 * Level 1: Top Menu (handled by GlobalFocusManager)
 * Level 2: Menu List (10 menu items: Powiadomienia + 9 others)
 */
private enum class AccountFocusLevel {
    PROFILE,      // Unused - kept for compatibility
    MENU_LIST     // Lista menu (starts with Powiadomienia)
}

/**
 * AccountChannelsScreen - Main Account section component
 *
 * Design:
 * - Menu List: 10 menu items (Powiadomienia as first item)
 *
 * Focus Hierarchy:
 * 1. Top Menu → MENU_LIST (auto-focus on Powiadomienia)
 * 2. MENU_LIST → UP/DOWN within list (10 items)
 * 3. MENU_LIST → UP (from Powiadomienia) → return to top menu
 * 4. Any level → BACK/LEFT → return to top menu
 */

/**
 * Get current startup mode label for Account menu subtitle
 */
private fun getCurrentStartupModeLabel(context: Context): String {
    return when (VersionTracker.getStartupMode(context)) {
        VersionTracker.MODE_EPG_DAY -> "Wybrany ekran startowy: Telewizja"
        VersionTracker.MODE_TOP_MENU -> "Wybrany ekran startowy: Telewizja i Aplikacje"
        else -> "Wybrany ekran startowy: Telewizja i Aplikacje" // fallback
    }
}

@Composable
private fun AccountChannelsScreen(
    onReturnToMenu: () -> Unit = {},
    onNavigateToStartupMode: () -> Unit = {},
    shouldAutoFocus: Boolean = false,
    sx: (Int) -> Dp,
    sy: (Int) -> Dp,
    resetTrigger: Int = 0,
    availableUpdate: com.uxellence.tv.v3.update.AppUpdateInfo? = null,
    updateState: com.uxellence.tv.v3.update.UpdateState = com.uxellence.tv.v3.update.UpdateState.READY,
    onUpdateDownload: (com.uxellence.tv.v3.update.AppUpdateInfo) -> Unit = {},
    onUpdateInstall: () -> Unit = {},
    onDismissUpdateBadge: () -> Unit = {}
) {
    val context = LocalContext.current

    // 10 menu items (Powiadomienia first, then Ekran startowy at row 3)
    val menuItems = remember(context, availableUpdate) {
        listOf(
            AccountMenuItem(
                id = "notifications",
                title = "Powiadomienia",
                subtitle = if (availableUpdate != null) "1 nowe powiadomienie" else "0 powiadomień",
                icon = Icons.Default.Notifications
            ),
            AccountMenuItem(
                id = "service_number",
                title = "Numer usługi: 696XXXXXXXXXX",
                subtitle = "Zaloguj się do Telewizji Play na innych urządzeniach",
                icon = Icons.Default.Info
            ),
            AccountMenuItem(
                id = "packages",
                title = "Pakiety",
                subtitle = "Zarządzaj pakietami telewizyjnymi i streamingowymi",
                icon = Icons.Default.Star
            ),
            AccountMenuItem(
                id = "startup_mode",
                title = "Ekran startowy",
                subtitle = getCurrentStartupModeLabel(context),
                icon = Icons.Default.Settings
            ),
            AccountMenuItem(
                id = "payments",
                title = "Płatności",
                subtitle = "Opłać bieżące faktury, sprawdź historię płatności",
                icon = Icons.Default.AccountCircle
            ),
            AccountMenuItem(
                id = "purchases",
                title = "Zakupy",
                subtitle = "Sprawdź m.in. historię wypożyczonych filmów",
                icon = Icons.Default.ShoppingCart
            ),
            AccountMenuItem(
                id = "pin_code",
                title = "Kod PIN",
                subtitle = "Ustaw kod blokady dostępu dla materiałów 18+",
                icon = Icons.Default.Lock
            ),
            AccountMenuItem(
                id = "diagnostics",
                title = "Diagnostyka",
                subtitle = "Sprawdź urządzenie i połączenie internetowe",
                icon = Icons.Default.Settings
            ),
            AccountMenuItem(
                id = "remote_config",
                title = "Pobierz parametry",
                subtitle = "Zaktualizuj konfigurację aplikacji z serwera",
                icon = Icons.Default.Refresh
            ),
            AccountMenuItem(
                id = "channel_search",
                title = "Wyszukiwanie kanałów TV",
                subtitle = "Podłącz kabel DVB i wyszukaj kanały naziemnej telewizji cyfrowej",
                icon = Icons.Default.Search
            ),
            AccountMenuItem(
                id = "help",
                title = "Pomoc",
                subtitle = "Znajdź odpowiedź na najczęstsze pytania",
                icon = Icons.Default.Info
            )
        )
    }

    var showNotificationUpdateDialog by remember { mutableStateOf(false) }

    // 2-level focus state (Profile, Menu List)
    var focusLevel by remember { mutableStateOf(AccountFocusLevel.PROFILE) }
    var menuListIndex by remember { mutableStateOf(0) } // 0-10 for menu items (11 total)
    val listState = rememberLazyListState()
    val coroutineScope = rememberCoroutineScope()

    // FocusRequesters for 2 levels
    val profileFocusRequester = remember { FocusRequester() }

    // FocusRequesters for Menu List (11 items: Powiadomienia + Ekran startowy + Pobierz parametry + others)
    val menuListFocusRequesters = remember {
        (0 until 11).associateWith { FocusRequester() }
    }

    // Auto-focus first menu item (Powiadomienia) when entering content (follows Focus Architect pattern)
    LaunchedEffect(shouldAutoFocus, resetTrigger) {
        if (shouldAutoFocus) {
            delay(100)
            focusLevel = AccountFocusLevel.MENU_LIST
            menuListIndex = 0
            menuListFocusRequesters[0]?.requestFocus()
        }
    }

    // Reset focus when resetTrigger changes
    LaunchedEffect(resetTrigger) {
        if (resetTrigger > 0) {
            focusLevel = AccountFocusLevel.MENU_LIST
            menuListIndex = 0
        }
    }

    // Auto-scroll to keep focused item centered
    // LazyColumn structure: [0-9] Menu items (Powiadomienia + 8 others)
    LaunchedEffect(menuListIndex, focusLevel) {
        coroutineScope.launch {
            if (focusLevel == AccountFocusLevel.MENU_LIST) {
                // Scroll to menu item
                listState.animateScrollToItem(
                    index = menuListIndex,
                    scrollOffset = -sy(200).value.toInt()
                )
            }
        }
    }

    Box(
        modifier = Modifier
            .fillMaxSize()
            .onPreviewKeyEvent { event ->
                handleAccountNavigation(
                    event = event,
                    focusLevel = focusLevel,
                    menuListIndex = menuListIndex,
                    onFocusLevelChange = { newLevel -> focusLevel = newLevel },
                    onMenuListIndexChange = { newIndex -> menuListIndex = newIndex },
                    profileFocusRequester = profileFocusRequester,
                    menuListFocusRequesters = menuListFocusRequesters,
                    menuItemsCount = menuItems.size,
                    onReturnToMenu = onReturnToMenu,
                    onItemClick = { index ->
                        val item = menuItems.getOrNull(index) ?: return@handleAccountNavigation
                        when (item.id) {
                            "notifications" -> {
                                if (availableUpdate != null) {
                                    showNotificationUpdateDialog = true
                                } else {
                                    Log.d("ACCOUNT", "Brak nowych powiadomień")
                                }
                            }
                            "startup_mode" -> {
                                Log.d("ACCOUNT", "Navigate to Startup Mode Selection")
                                onNavigateToStartupMode()
                            }
                            "remote_config" -> {
                                Log.d("ACCOUNT", "Pobierz parametry clicked - fetching config from Supabase")
                                coroutineScope.launch {
                                    val result = ConfigManager.refreshConfig(context)
                                    result.onSuccess { config ->
                                        android.widget.Toast.makeText(
                                            context,
                                            "Pobrano konfigurację v${config.version}",
                                            android.widget.Toast.LENGTH_SHORT
                                        ).show()
                                    }
                                    result.onFailure { error ->
                                        android.widget.Toast.makeText(
                                            context,
                                            "Błąd: ${error.message}",
                                            android.widget.Toast.LENGTH_LONG
                                        ).show()
                                    }
                                }
                            }
                            else -> {
                                Log.d("ACCOUNT", "Clicked: ${item.title}")
                            }
                        }
                    }
                )
            }
    ) {
        // LazyColumn with all content (header + menu items scroll together)
        LazyColumn(
            state = listState,
            modifier = Modifier
                .fillMaxSize()
                .padding(top = sy(200)),
            horizontalAlignment = Alignment.CenterHorizontally,
            verticalArrangement = Arrangement.spacedBy(sy(24)),
            contentPadding = PaddingValues(bottom = sy(150))
        ) {
            // Menu List (Powiadomienia + Ekran startowy + 8 others)
            itemsIndexed(menuItems) { index, item ->
                AccountMenuItemCard(
                    item = item,
                    isFocused = shouldAutoFocus && focusLevel == AccountFocusLevel.MENU_LIST && menuListIndex == index,
                    focusRequester = menuListFocusRequesters[index]!!,
                    onFocused = {
                        focusLevel = AccountFocusLevel.MENU_LIST
                        menuListIndex = index
                    },
                    showNewLabel = item.id == "notifications" && availableUpdate != null,
                    onClick = {
                        when (item.id) {
                            "notifications" -> {
                                if (availableUpdate != null) {
                                    showNotificationUpdateDialog = true
                                } else {
                                    Log.d("ACCOUNT", "Brak nowych powiadomień")
                                }
                            }
                            "startup_mode" -> {
                                Log.d("ACCOUNT", "Navigate to Startup Mode Selection")
                                onNavigateToStartupMode()
                            }
                            "remote_config" -> {
                                Log.d("ACCOUNT", "Pobierz parametry clicked - fetching config from Supabase")
                                coroutineScope.launch {
                                    val result = ConfigManager.refreshConfig(context)
                                    result.onSuccess { config ->
                                        android.widget.Toast.makeText(
                                            context,
                                            "Pobrano konfigurację v${config.version}",
                                            android.widget.Toast.LENGTH_SHORT
                                        ).show()
                                    }
                                    result.onFailure { error ->
                                        android.widget.Toast.makeText(
                                            context,
                                            "Błąd: ${error.message}",
                                            android.widget.Toast.LENGTH_LONG
                                        ).show()
                                    }
                                }
                            }
                            else -> {
                                Log.d("ACCOUNT", "Clicked: ${item.title}")
                            }
                        }
                    },
                    sx = sx,
                    sy = sy
                )
            }
        }

        // Version number in bottom left corner
        Text(
            text = "v${BuildConfig.VERSION_NAME}",
            modifier = Modifier
                .align(Alignment.BottomStart)
                .padding(start = sx(60), bottom = sy(40)),
            style = TextStyle(
                fontSize = (16 * sx(1).value).sp,
                fontWeight = FontWeight.Normal,
                color = Color(0xFFAAAAAA)
            )
        )
    }

    if (showNotificationUpdateDialog && availableUpdate != null) {
        com.uxellence.tv.v3.update.UpdateDialog(
            updateInfo = availableUpdate,
            currentVersion = BuildConfig.VERSION_NAME,
            updateState = updateState,
            onDownload = { onUpdateDownload(availableUpdate) },
            onInstall = { onUpdateInstall() },
            onDismiss = {
                showNotificationUpdateDialog = false
                onDismissUpdateBadge()
            }
        )
    }
}

/**
 * Data class for Account menu items
 */
data class AccountMenuItem(
    val id: String,
    val title: String,
    val subtitle: String,
    val icon: androidx.compose.ui.graphics.vector.ImageVector
)

/**
 * AccountMenuItemCard - Single menu item component
 *
 * Figma specs:
 * - Size: 756×136px
 * - Background: rgba(0,0,0,0.2)
 * - Focus border: 8px #5AECD3
 * - Border radius: 8px
 * - Icon: 64×64px
 * - Gap: 24px between icon and text
 */
@Composable
private fun AccountMenuItemCard(
    item: AccountMenuItem,
    isFocused: Boolean,
    focusRequester: FocusRequester,
    onFocused: () -> Unit,
    onClick: () -> Unit,
    showNewLabel: Boolean = false,
    sx: (Int) -> Dp,
    sy: (Int) -> Dp
) {
    val colorFocusBorder = Color(0xFF5AECD3)
    val colorBackground = Color(0x33000000) // rgba(0,0,0,0.2)
    val colorTextPrimary = Color(0xFFEEEEEE)
    val colorTextSecondary = Color(0xCCEEEEEE) // 80% opacity

    Box(
        modifier = Modifier
            .width(sx(756))
            .height(sy(136))
            .focusRequester(focusRequester)
            .onFocusChanged { focusState ->
                if (focusState.isFocused) {
                    onFocused()
                }
            }
            .focusable()
            .clickable { onClick() }
            .then(
                if (isFocused) {
                    Modifier.border(
                        width = sx(8),
                        color = colorFocusBorder,
                        shape = RoundedCornerShape(sx(8))
                    )
                } else {
                    Modifier
                }
            )
            .clip(RoundedCornerShape(sx(8)))
            .background(colorBackground)
            .padding(horizontal = sx(32), vertical = sy(32))
    ) {
        Row(
            modifier = Modifier.fillMaxSize(),
            verticalAlignment = Alignment.CenterVertically,
            horizontalArrangement = Arrangement.spacedBy(sx(24))
        ) {
            // Icon (64×64px)
            Icon(
                imageVector = item.icon,
                contentDescription = item.title,
                modifier = Modifier.size(sx(64), sy(64)),
                tint = colorTextPrimary
            )

            // Text content
            Column(
                modifier = Modifier.weight(1f),
                verticalArrangement = Arrangement.spacedBy(sy(4))
            ) {
                // Title (32px Bold from Figma)
                Text(
                    text = item.title,
                    style = TextStyle(
                        fontSize = (32 * sy(1).value / 1).sp,
                        fontWeight = FontWeight.Bold,
                        color = colorTextPrimary,
                        lineHeight = (40 * sy(1).value / 1).sp
                    ),
                    maxLines = 1,
                    overflow = TextOverflow.Ellipsis
                )

                // Subtitle (24px Medium from Figma)
                Text(
                    text = item.subtitle,
                    style = TextStyle(
                        fontSize = (24 * sy(1).value / 1).sp,
                        fontWeight = FontWeight.Medium,
                        color = colorTextSecondary,
                        lineHeight = (32 * sy(1).value / 1).sp
                    ),
                    maxLines = 2,
                    overflow = TextOverflow.Ellipsis
                )
            }

            if (showNewLabel) {
                Box(
                    modifier = Modifier
                        .background(Color.Red, RoundedCornerShape(sx(8)))
                        .padding(horizontal = sx(16), vertical = sy(4))
                ) {
                    Text(
                        text = "Nowe",
                        style = TextStyle(
                            fontSize = (20 * sy(1).value).sp,
                            fontWeight = FontWeight.Bold,
                            color = Color.White
                        )
                    )
                }
            }
        }
    }
}

